          "2. A message to the sacred heart!\nOh! Bear it back with speed,\nCome, Jesus, reign within my heart\nThy heart is all I need.\nThis prayer I'll pray while here pine,\nFrom heaven and thee apart,\nNo case, dear Lord, till I am thine\nFor ever heart to heart.",
        ],
      ),
      Hymn(
        id: 34,
        number: "34",
        title: "And The Father Will Dance",
        category: "Praise & Worship",
        refrain: "And the father will dance,\nAs on a day of joy.\nHe will exult over you\nand renew you By his love.",
        stanzas: [
          "1. Shout for joy all you his people.\nSing aloud and exult will all your heart,\nFor Yahweh, your God, is in your midst.",
          "2. You have no more evil to fear.\nYou have no more evil to fear.\nDo not let your hands fall limp\nFor Yahweh your God is in your midst.",
          "3. And when the time comes I will rescue The lame.\nAnd when the time comes I will gather the strays.\nAnd when Time comes I will be your guide.\nI will gather you in and give you\nRenown among all peoples.",
        ],
      ),
      Hymn(
        id: 35,
        number: "35",
        title: "Angels From The Realms",
        category: "Advent & Christmas",
        refrain: "Gloria in excelsis Deo.\nGloria in excelsis Deo.",
        stanzas: [
          "1. Angels from the realms of glory,\nwing your flight o'er all the earth\nYe, who sang creation's story.\nNow proclaim Messiah's birth.",
          "2. Shepherds in the field abiding,\nwatching o'er your flocks by night\nGod in man is now residing.\nYonder shines the infant light.",
          "3. Sages, leave your contemplations.\nBrighter visions gleam afar.\nSeek the great desire of nations.\nYe have seen His natal star.",
          "4. Saints before the altar bending\nwatching long in hope and fear,\nsuddenly the Lord descending,\nin His temple shall appear.",
          "5. See Him in a manger laid,\nWhom the choirs of angels praise!\nMary, Joseph lend your aid,\nwhile our hearts in love we raise.",
        ],
      ),
      Hymn(
        id: 36,
        number: "36",
        title: "Angels We Have Heard On High",
        category: "Advent & Christmas",
        refrain: "Gloria in excelsis Deo\nGloria in excelsis Deo.",
        stanzas: [
          "1. Angels we have heard on high\nsweetly singing o'er the plains.\nAnd the mountains in reply\nechoing their joyous strain.",
          "2. Shepherds, why this jubilee?\nWhy your joyous strains prolong?\nWhat the gladsome tidings be\nwhich inspire your joyous song?",
          "3. Come to Bethlehem and see\nHim whose birth the angels sing:\nCome adore on bended knee,\nChrist the Lord, the newborn King.",
          "4. See Him in a manger laid,\nWhom the choirs of angels praise!\nMary, Joseph lend your aid,\nwhile our hearts in love we raise.",
        ],
      ),
      Hymn(
        id: 37,
        number: "37",
        title: "Arise Come",
        category: "Entrance",
        refrain: "Arise, come to your God.\nSing Him your songs of rejoicing.",
        stanzas: [
          "1. Cry out with joy to the Lord all the earth.\nServe the Lord with gladness.\nCome before Him singing for joy.",
          "2. Know that He, the Lord, is God.\nHe made us; we belong to Him.\nWe are His people, the sheep of His flock.",
          "3. Go within His gates giving thanks,\nEnter His courts with songs of praise.\nGive thanks to Him and bless His Name.",
          "4. Indeed, how good is the Lord!\nEternal His merciful Love!\nHe is faithful from age to age.",
          "5. Give glory to the Father Almighty,\nto His Son Jesus Christ, the Lord\nto the Spirit who dwells in our hearts.",
        ],
      ),
      Hymn(
        id: 38,
        number: "38",
        title: "Around The Altar",
        category: "Adoration & Eucharist",
        refrain: "Around the altar we sing and pray with one heart.\nAround the altar come.\nAround this altar we celebrate our oneness.\nOur joy is full in Christ.",
        stanzas: [
          "1. Take His body singing, praying all together.\nTake the body of Christ.\nTake His body, singing, praying all together,\nTake and eat with joy.",
          "2. Drink His blood singing, praying all together.\nDrink the blood of Christ.\nDrink His blood, singing, praying all together.\nDrink His blood with joy.",
          "3. This meal given by Christ Jesus is real food indeed.\nWhoever shares it will never die.\nHe has eternal life.",
          "4. Help us, Jesus to fully understand the meaning of this meat.\nThat we may always be grateful for your death for the world.",
        ],
      ),
      Hymn(
        id: 39,
        number: "39",
        title: "Ask And You Will Receive",
        category: "Praise & Worship",
        refrain: "Ask, and you will receive.\nSeek, and you will find\nKnock, and the door will be opened.\nFor the love of the Lord has no end.",
        stanzas: [
          "1. Is there any man here, when his son asks for Bread\nwould turn him away with a stone instead?\nIs there any man here, when his son asks for meat\nwould then give him a poisonous snake to eat?",
          "2. So, then, how could your Father in heaven above\nwho knows so much more of the ways of love?\nSo then how could your Father refuse what is good\nwhen you ask in the name of the Son He loves?",
          "3. So whatever you ask you will receive.\nWhatever you seek you will always find.\nFor my Father will give to all those who believe\nin the spirit of love that will never end.",
        ],
      ),
      Hymn(
        id: 40,
        number: "40",
        title: "Asleep In Jesus",
        category: "Praise & Worship",
        stanzas: [
          "1. Asleep in Jesus blessed sleep\nfrom which none ever wakes to weep.\nA calm and undisturbed repose\nunbroken by the last of foes.",
          "2. Asleep in Jesus, oh how sweet!\nTo be for such a slumber meet\nwith holy confidence to sing\nthat death has lost its venom sting.",
          "3. Asleep in Jesus peaceful rest\nwhose waking is supremely blest\nNo fear no woe shall dim that hour\nthat manifest the Saviour's power.",
          "4. Asleep in Jesus, oh for me\nmay such a blissful refuge be.\nSecurely shall my ashes lie\nand wait the summons from on high.",
          "5. Asleep in Jesus far from thee\nthy kindred and their graves may be\nBut thine is still a blessed sleep\nfrom which none ever wakes to weep.",
        ],
      ),
      Hymn(
        id: 41,
        number: "41",
        title: "At The Cross",
        category: "Lent & Passion",
        stanzas: [
          "1. At the cross her station keeping\nstood the mournful mother weeping\nclose to Jesus to the last.",
          "2. Through her heart His sorrow sharing.\nAll His bitter anguish bearing.\nNow at length the sword has passed.",
          "3. Oh, how sad and sore distressed\nwas that mother highly blest,\nof the sole begotten one!",
          "4. Christ above in torment hangs.\nShe beneath beholds the pangs\nof her dying glorious Son.",
          "5. Is there one who would not weep\nwhelmed in miseries so deep\nChrist's dear mother to behold?",
          "6. For the sins of His own nation\nsaw Him hang in desolation,\n'til His Spirit forth He sent.",
          "7. O thou mother fount of love!\nTouch my spirit from above.\nMake my heart with thine accord.",
          "8. Make me feel so thou has felt.\nMake my soul to glow and melt\nwith the love of Christ, my Lord.",
          "9. Holy mother pierce me through.\nIn my heart each wound renew\nwith the love of Christ my Lord.",
          "10. Let me share with thee His pain,\nWho for all my sins was slain,\nWho for me in torments died.",
          "11. Can the human heart refrain\nfrom partaking in her pain?\nIn that mother's pain untold?",
          "12. Bruised, derided, cursed, defiled.\nShe beheld her tender child.\nAll with bloody scourges rent.",
          "13. Let me mingle tears with thee\nmourning Him who mourned for me.\nAll the days that I may live",
          "14. By the cross with thee to stay,\nthere with thee to weep and pray,\nis all I ask of thee to give.",
          "15. Virgin of all virgins blest!\nListen to my fond request:\nLet me share thy grief divine.",
        ],
      ),
      Hymn(
        id: 42,
        number: "42",
        title: "As The Deer",
        category: "Praise & Worship",
        refrain: "You alone are my strength, my shield\nTo you alone may my spirit yield\nYou alone are my heart's desire,\nAnd I long to worship you.",
        stanzas: [
          "1. As the deer panted for the water\nSo my soul longs after you,\nYou alone are my heart's desire\nAnd I long to worship you.",
          "2. I want you more than gold or silver\nOnly you can satisfy.\nYou alone are the real joy giver\nAnd the apple of my eye.",
          "3. You're my friend and you're my brother\nEven though you are a king!\nI love you more than any other\nSo much more than anything.",
        ],
      ),
      Hymn(
        id: 43,
        number: "43",
        title: "Ave Maria (1)",
        category: "Marian",
        stanzas: [
          "1. Ave Maria, plena, Dominus tecum,\nBenedictatu in mulieribus,\net Benedictus Fructus ventris tui, Jesu.",
          "2. Sancta Maria, Mater Dei,\nora pro nobis Pecatoribus,\nnunc et in hora mortis nostrae. Amen.",
        ],
      ),
      Hymn(
        id: 44,
        number: "44",
        title: "Ave Maria (2)",
        category: "Marian",
        refrain: "Ave Maria, gratia plena\nDominus tecum, benedicta tu.",
        stanzas: [
          "1. As I kneel before you,\nAs I bow my head in pray'r\nTake this day, and make it yours\nAnd fill me, with your love.",
          "2. All I have I give you,\nEv'ry dream and wish are yours,\nMother of Christ, Mother mine;\nPresent them to my Lord.",
          "3. As I kneel before you,\nAs I see your smiling face,\nEv'ry thought, ev'ry word\nIs lost in your embrace.",
        ],
      ),
      Hymn(
        id: 45,
        number: "45",
        title: "Ave Maris Stella",
        category: "Marian",
        stanzas: [
          "1. Ave Maris stella, Dei Mater alma,\nAtque semper Virgo, Felix caeli porta.",
          "2. Summens illud Ave, Gabrielis ore,\nFund nos in pace Muntans Havae noman.",
          "3. Solve vincla reis, Prefer lumen caecis,\nMala nostra pelle, Bona cuncta posce.",
          "4. Sit laus Deo Patri, Summo Christo decus,\nSpiritui sancto, Tribus honor unus.",
        ],
      ),
      Hymn(
        id: 46,
        number: "46",
        title: "Ave Maria, Star of the Sea",
        category: "Marian",
        refrain: "Mater amabilis, ora pro nobis,\nPray for thy children who call upon thee.\nAve sanctissima, ave purissima.\nSinless and beautiful Star of the Sea.",
        stanzas: [
          "1. Ave Maria, O maiden, O Mother\nFondly thy children are calling on thee,\nThine are the graces unclaimed by another\nSinless and beautiful Star of the Sea.",
          "2. Ave Maria, the night shades are falling.\nSoftly our voices arise unto thee.\nEarth's lonely exiles for succour are calling.\nSinless and beautiful, Star of the Sea.",
          "3. Ave Maria, thy children are kneeling.\nWords of endearment are murmured to thee.\nSoftly thy spirit upon us is stealing,\nSinless and beautiful Star of the Sea.",
          "4. Ave Maria, thou portal of heaven,\nharbour of refuge, to thee do we flee.\nLost in the darkness, driven, shine on our pathway,\nFair Star of the Sea.",
        ],
      ),
      Hymn(
        id: 47,
        number: "47",
        title: "Ave Regina Caelorum",
        category: "Marian",
        stanzas: [
          "1. Ave Regina caelorum, Ave Domina Angelorum!\nSalve radix, salve porta, Excua mundo lux ext orta,\nGaude, virgo glorioso, Super omnes speciose,\nVale, O valde decora! Et pro nobis Christum exora.",
          "2. V Dignare me laudare te. Virgo sacrata,\nR Da mihi virtutem contra hostes tuos.",
        ],
      ),
      Hymn(
        id: 48,
        number: "48",
        title: "Ave Verum",
        category: "Adoration & Eucharist",
        stanzas: [
          "1. Ave verum corpus natum de Maria Virgine:\nVere passum, immolatum in cruce pro homine:\nCujus latus fluxit aqua et Sanguine:\nEsto nobis praegustatum mortis in examine,\nO Jesu dulcis! O Jesu pie! O Jesu fili Mariae.",
        ],
      ),
      Hymn(
        id: 49,
        number: "49",
        title: "Awake From Your Slumber",
        category: "Entrance",
        refrain: "Let us build the city of God.\nMay our tears be turned into dancing.\nFor the Lord, our Light and our Love,\nhas turned the night into day.",
        stanzas: [
          "1. Awake from your slumber, arise from your sleep.\nA new day is dawning for all those who weep.\nThe people in darkness have seen a great light.\nThe Lord of our longing has conquered the night.",
          "2. We are sons of the morning. We are daughters of day.\nThe One who has loved us has brightened our way.\nThe Lord of all kindness has called us to be,\na light for His people, to set their hearts free.",
          "3. God is light. In Him there is no darkness.\nLet us walk in the light, his children one and all.\nO comfort my people; make gentle your words.\nProclaim to My city the day of her birth.",
          "4. O city of gladness, now light up your voice.\nProclaim the good tidings that all may rejoice.",
        ],
      ),
      Hymn(
        id: 50,
        number: "50",
        title: "Away In A Manger",
        category: "Advent & Christmas",
        stanzas: [
          "1. Away in a manger, no crib for a bed,\nThe little Lord Jesus lay down His sweet head.\nThe stars in the bright sky, looked down where He lay.\nThe little Lord Jesus, asleep on the hay.",
          "2. The cattle are lowing, the baby awakes.\nBut little Lord Jesus, no crying He makes.\nI love Thee, Lord Jesus, look down from the sky\nAnd stay by my cradle till morning is nigh.",
          "3. Be near me, Lord Jesus, I ask Thee to stay\nclose by me forever, and love me, I pray.\nBless all the dear children in thy tender care.\nAnd fit us for heaven, to live with thee there",
        ],
      ),
      Hymn(
        id: 51,
        number: "51",
        title: "Beautiful Saviour",
        category: "Praise & Worship",
        stanzas: [
          "1. Beautiful creator, king of creation,\nSon of God and son of Man,\nTruly I'd love Thee. Truly I'd serve Thee.\nLight of my soul, my joy, my crown!",
          "2. Fair are the meadows, fairer the Woodlands,\nRobed in flowers of blooming spring,\nJesus is fairer; Jesus is purer;\nHe makes our sorrowing spirit sing.",
        ],
      ),
      Hymn(
        id: 52,
        number: "52",
        title: "(Air) O Worship The King",
        category: "Praise & Worship",
        stanzas: [
          "1. O blessed is the Lord of Israel's old\nHe comes to redeem as he promised of old\nHe sends us a saviour of David's own line\nAs his prophet foretold us in words and in signs",
          "2. He save us from foes, from hatred and fear\nHis mercy he show to his children so dear\nHis oaths he remembers from Abraham's day\nTo make us a people who lives for his praise",
          "3. And you little child are chosen this day\nHis prophet and voice to prepare him a way\nWith news of salvation, forgiveness and love\nYou herald the dawning of light from above.",
          "4. O people who walk in darkness afraid\nWho wander alone in death's glooming shade\nO lift up your heads, now behold your release\nYour saviour is coming and his kingdom is peace.",
          "5. All praise be to God the father and son\nTo the spirit of love in whom all are one\nHe lives in the glory of life - without end\nFrom before times beginning and forever. Amen.",
        ],
      ),
      Hymn(
        id: 53,
        number: "53",
        title: "Behold a Great Priest",
        category: "Praise & Worship",
        refrain: "Behold a great priest - who in His days pleased God.\nAnd the Lord loved him and adorned him with a robe of glory",
        stanzas: [
          "1. He found grace in the eyes of the Lord.\nGood Shepherd of thy people thus hast thou pleased the Lord.",
          "2. Therefore by an oath the Lord made him father of His people,\nAnd made a covenant with Him forever.",
        ],
      ),
      Hymn(
        id: 54,
        number: "54",
        title: "Behold Among Men",
        category: "Entrance",
        refrain: "Behold, among men the dwelling place of God,\nThey shall be His people.\nAnd He shall be their Lord and God.",
        stanzas: [
          "1. People called by God through the word of the prophets.\nPeople brought together in the house of the Lord,\nPeople who attend to their Lord.\nThe Church of Christ the Lord!",
          "2. Temple built by saints, by the martyrs and apostles,\nHoly temple built upon Christ, the corner-stone,\nHoly dwelling place of our God.\nThe Church of Christ the Lord,",
          "3. People who are born in the waters of the Spirit,\nPeople who are marked by the seal of the Spirit,\nPeople in the Spirit made one,\nthe Church of Christ the Lord.",
          "4. People who are grafted on Jesus, the Vine,\nBranches bearing fruit in the grace of the Lord.\nBranches rooted in His great love.\nThe Church of Christ the Lord.",
          "5. People nourished now by the body of the Lord,\nPeople who sit down to the new paschal supper,\nwho shall pass from death into life\nThe Church of Christ the Lord.",
          "6. People justified by the grace of the Spirit,\nPeople who are heirs of an everlasting life.\nPeople now enlightened by Christ,\nThe Church of Christ the Lord.",
        ],
      ),
      Hymn(
        id: 55,
        number: "55",
        title: "Benedictus",
        category: "Praise & Worship",
        refrain: "In the morning\nLet our life be joyful in your sight (2ice)",
        stanzas: [
          "1. We sing your praises\nGod visit his people as we know\nHis mighty saviour has set us free\nThe light is before us leading forward\nAwaken the sleeping we shall be free",
          "2. You will be a prophet little child\nTell all the people they be free -\nA tender compassion is our God\nThe dawn breaks open us we shall be free.\nPrepare for the Lord is coming\nIn his forgiveness we be free\nThe light is before us leading,\nAwaken the sleeping we shall be free.",
        ],
      ),
      Hymn(
        id: 56,
        number: "56",
        title: "Be Not Afraid",
        category: "Praise & Worship",
        refrain: "Be not afraid,\nI go before you always\nCome follow Me\nAnd I will give you rest.",
        stanzas: [
          "1. You shall cross the barren desert,\nBut you shall not die of thirst:\nYou shall wander far in safety\nthough you do not know the way.\nYou shall speak your words to foreign men.\nAnd they will understand.\nYou shall see the face of God and live.",
          "2. If you pass through raging waters in the sea you shall not drown:\nIf you walk amid the burning flames you shall not be harmed.\nIf you stand before the power of hell and death is at your side,\nknow that I am with you through it all.",
        ],
      ),
      Hymn(
        id: 57,
        number: "57",
        title: "Be Ready Now to Stand",
        category: "Praise & Worship",
        stanzas: [
          "1. Be ready now to stand (2x)\nTake all your sins to Jesus who is waiting be ready now to stand\nThe saviour promised he will never leave you be ready now to stand.",
          "2. The Saviour cares for you (2x)\nHe knows that Satan never lets you to Him, the Saviour cares for you",
          "3. He is the only one to take your burdens\nThe Saviour cares for you",
          "4. Remember there is death (2x)\nA day will come when He shall have no mercy\nRemember there is death\nBe wise this is the time to take him\nRemember there is death.",
          "5. Today you have been warned (2x)\nA day will come when you shall face the judgment\nToday you have been warned\nThe way is set for you to start your journey\nToday you have been warned.",
        ],
      ),
      Hymn(
        id: 58,
        number: "58",
        title: "Be Still and Know",
        category: "Praise & Worship",
        stanzas: [
          "1. Be still and know that I am God.\nBe still and know that I am God.\nBe still and know that I am God.",
          "2. I am the Lord that healeth thee.\nI am the Lord that healeth thee.\nI am the Lord that healeth thee.",
          "3. In thee, O Lord, I put my trust.\nIn thee, O Lord, I put my trust.\nIn thee, O Lord, I put my trust.",
        ],
      ),
      Hymn(
        id: 59,
        number: "59",
        title: "Be Still and Know I Am",
        category: "Praise & Worship",
        stanzas: [
          "1. Be still and know I am with you.\nBe still, I am the Lord.\nI will not leave you orphans.\nI leave with you my word Be one.",
          "2. You fear to lose your fading\nYou fear to lose your way.\nBe still and know I am near you.\nI'll lead you to the day and the sun.",
          "3. Be glad the day you have sorrow.\nBe glad, for then you live.\nThe stars shine only in darkness.\nAnd in your need I give my peace.",
        ],
      ),
      Hymn(
        id: 60,
        number: "60",
        title: "Bethlehem of Noblest Cities",
        category: "Advent & Christmas",
        stanzas: [
          "1. Bethlehem! Of noblest cities,\nNone can one with thee compare;\nThou alone the Lord from heaven,\nDidst for us incarnate bear.",
          "2. Fairer than the sun at morning,\nWas the star that told of his birth;\nTo the lands their God announcing,\nHid beneath a form of earth.",
          "3. By its lambent beauty guided\nSee, the eastern kings, appear;\nSee them bend, their gifts to offer,\nGifts of incense, gold and myrrh.",
          "4. Solemn things of mystic meaning!\nIncense doth the God disclose;\nGold a royal child proclaimeth;\nMyrrh a future tomb foreshadows.",
          "5. Holy Jesus, in thy brightness,\nTo the gentile world displayed,\nWith the Father and the Spirit,\nEndless praise to thee be paid.",
        ],
      ),
      Hymn(
        id: 61,
        number: "61",
        title: "Be With Us Mary",
        category: "Marian",
        refrain: "Be with us Mary along the way.\nCome with us Mary, come.",
        stanzas: [
          "1. Be with us Mary along the way.\nguide every step we take.\nLead us to Jesus your loving Son.\nCome with us Mary, come.",
          "2. No man can live as an Island,\njourneying through life alone.\nSince we're most loved by a mother,\nJesus gave us His own.",
          "3. When Jesus met with rejection,\nMary stood by the Cross.\nHow can a mother desert her son?\nShe'll also stand by us.",
          "4. Help us O Star of ocean:\nBe with us in our strife.\nWhen we are faced with temptation,\ntossed by the storms of life.",
        ],
      ),
      Hymn(
        id: 62,
        number: "62",
        title: "Bind Us Together",
        category: "Recessional",
        refrain: "Bind us together, Lord;\nbind us together with cords that cannot be broken.\nBind us together, Lord, bind us together;\nBind us together with love.",
        stanzas: [
          "1. There is only one God.\nThere is only one King:\nThere is only one Body.\nThat is why we sing:",
          "2. Fit for the glory of God\nPurchased by His precious blood\nBorn with the right to be free\nFor Jesus the victory has won.",
          "3. You are the family of God.\nYou are the promise divine.\nYou are God's chosen desire.\nYou are the glorious new wine.",
        ],
      ),
      Hymn(
        id: 63,
        number: "63",
        title: "Blessed Are They Who Put Their Trust in God",
        category: "Praise & Worship",
        refrain: "The Kings of the earth, arise\nAgainst the Lord and his Christ.",
        stanzas: [
          "1. Why this tumult among nations,\nAmong peoples the useless murmuring?\nThey arise, the kings of the earth\nPrinces plot against the Lord and his Christ,\n'come let us cast off their yoke,\nCome let us cast off their yoke.'",
          "2. He who sits in the heavens laughs;\nThe Lord is laughing them to scorn.\nThen he will speak in his anger.\nHis rage will strike them with terror.\n'it is I who have set up my king\nOn Sion, my holy mountain.'",
          "3. The Lord said to me: 'you are my Son:\nIt is I who has begotten you this day.\nAsk and I shall bequeath you the nations.\nPut the ends of the earth in your possession.\nWith a rod of iron you will break them,\nShatter them like a potter's jar.'",
          "4. Now, O Kings, understand,\nTake warnings, rulers of the earth;\nServe the Lord with fear\nAnd trembling, pay him homage\nLest he'll be angry and you'll perish;\nFor suddenly his anger will blaze.",
        ],
      ),
      Hymn(
        id: 64,
        number: "64",
        title: "Blessed Be The Lord Our God",
        category: "Praise & Worship",
        refrain: "Blessed be the Lord our God\nBlessed be the Lord.",
        stanzas: [
          "1. God has come to visit us, blessed be the Lord\nAnd redeemed us from our sin, blessed be the Lord\nThe promised saviour God has sent, blessed be the Lord\nCome to free us from all harm, blessed be the Lord.\nIn faithful love of our God to fulfil the promise made of old,\nTo free our heart from every fear, and serve the Lord alone.",
          "2. You my child called by God, blessed be the Lord\nA prophet from the Lord most high, blessed be the Lord\nPreparing people for their God, blessed be the Lord\nDeclaring God's forgiving word, blessed be the Lord.",
          "3. The loving kindness of our God shall break forth like the dawn\nTo fight the shadow cast by death, and guide us to peace.",
        ],
      ),
      Hymn(
        id: 65,
        number: "65",
        title: "Blessed Lamb",
        category: "Lent & Passion",
        stanzas: [
          "1. Blessed Lamb on Calvary's mountain\nSlain to take our sins away,\nLet the drops of that rich fountain\nour tremendous ransom pay.\nSacred Saviour! Sacred Saviour!\nLowly at Thy feet we pray.",
          "2. Blessed Lamb, vouchsafe us pardon.\nIn Thy love our souls confide.\nBy Thy groans within the garden;\nby the death which Thou hast died\nlet Thy passion - let Thy Passion\nevermore with us abide.",
          "3. So shall peace, sweet peace be given\npurchase of Thy precious pain,\nso shall earth but lead to heaven.\nSince for us the Lamb was slain\nDear Redeemer! Dear Redeemer!\nThou canst not have died in vain.",
        ],
      ),
      Hymn(
        id: 66,
        number: "66",
        title: "Bless The Lord You Works",
        category: "Praise & Worship",
        refrain: "Bless the Lord you works of the Lord: bless the Lord.\nAngels of the Lord bless the Lord, bless the Lord.",
        stanzas: [
          "1. Bless the Lord all you waters,\nwaters up in the sky.\nBless the Lord stars in heaven.\nBless the Lord sun and moon.",
          "2. Shower, dew and wind,\nbless the Lord, bless the Lord.\nFire, heat and cold,\nbless the Lord, bless the Lord.",
          "3. Bless the Lord light and darkness.\nBless the Lord night and day.\nBless the Lord clouds and lightening.\nLet the earth bless the Lord.",
          "4. Ice and rain and frost,\nbless the Lord, bless the Lord.\nDew and rain and chill,\nbless the Lord, bless the Lord.",
          "5. Bless the Lord hills and mountains.\nBless the Lord all that fly,\nBless the Lord seas and rivers,\ncreatures of the sea.",
          "6. Everything that grows,\nbless the Lord, bless the Lord.\nAll beasts wild and tame,\nbless the Lord, bless the Lord.",
          "7. Bless the Lord, priests and servants.\nBless the Lord sons of men,\nBless the Lord souls and spirits.\nBless the Lord holy men.",
        ],
