      Hymn(
        id: 67,
        number: "67",
        title: "Born in Plenty",
        category: "Offertory",
        refrain: "All the earth belongs to all.\nThat's the vision and the call.\nLocal man shall rise again,\nto build the common earth.",
        stanzas: [
          "1. Born in plenty, raised up blind.\nAll turned hollow, something there was wrong.\nHuman suffering over all the world.\nThree billion people die and never live.",
          "2. Joined the rebels, lost the past,\nSaw destruction; nothing really changed.\nHuman suffering over all the world.\nThree billion people die and never live.",
          "3. Then a stranger, loved by none.\nAll was gone, every hope had died.\nHuman suffering over all the world.\nThree billion people die and never live.",
          "4. From the centre, Christ has stood,\nin every nation throughout every land.\nBuilding patterns to release the new,\ndying daily that the new may live.",
          "5. At the centre, awful calm,\nborn of Spirit. Then my life began.\nHuman suffering over all the world.\nThree billion people die and never live.",
