        number: "68",
        title: "Born To Us",
        category: "Advent & Christmas",
        refrain: "Born to us is our Saviour today, Alleluia.\nHe is the Messiah, He's the Lord.",
        stanzas: [
          "1. Jesus Christ is born for us in Bethlehem.\nGreet Him with joy, Alleluia! Noel, Noel.",
          "2. Jesus Christ has come from Heaven for our sake.\nCome now to Him, Alleluia! Noel, Noel.",
          "3. Angels sing and fill the skies with hymns of praise.\nJoin them with songs, Alleluia, Noel, Noel.",
          "4. Mary bids the shepherds watch when Jesus sleeps.\nWhen shepherds come, Noel, Noel.",
          "5. Blessed Mary, Holy Mother of our Lord.\nBlessed are you, Alleluia, Noel, Noel.",
          "6. Glory be to God whose kingdom is on high,\nBlessed are you, Alleluia, Noel, Noel.",
