      Hymn(
        id: 69,
        number: "69",
        title: "Bring a Torch",
        category: "Advent & Christmas",
        stanzas: [
          "1. Bring a torch Jeanette Isabella,\nBring a torch to the cradle run.\nIt is Jesus good folk of the village,\nChrist is born and Mary's calling,\nAh! Ah! Beautiful is the mother,\nAh! Ah! Beautiful is the son.",
          "2. It is wrong when child is sleeping,\nIt is wrong to talk so loud.\nSilence all as you gather round\nlest your noise should waken Jesus,\nhush! Hush! See how fast he slumbers,\nhush! Hush! See how fast he sleeps.",
          "3. Who goes there a knocking loudly,\nWho goes there a knocking so like that?\nOpen your doors, I have here on a plate\nsome very good cakes which I'm bringing,\nToe! Toe! Quickly your doors now open,\nToe! Toe! Come let us make good cheer.",
          "4. Softly to the little stable,\nsoftly for a woman come.\nLook and see how charming is Jesus,\nHow He's white His cheeks are rosy,\nhush! Hush! See how the child is sleeping,\nhush! Hush! See how he smiles in dream.",
        ],
