          "2. Receive our gifts (2x)\nO Lord of love (2x)\nLet it please thee (2x)\nO Lord, please Lord (2x).",
          "3. Almighty God (2x)\nAll thy people (2x)\nGive thee praise (2x)\nAnd sing thy praise (2x).",
