      Hymn(
        id: 71,
        number: "71",
        title: "Bring To The Lord Your Offerings",
        category: "Offertory",
        refrain: "Bring to the Lord your offerings.\nAdore him in his holy place.",
        stanzas: [
          "1. O give the Lord you sons of God.\nGive the Lord glory and power.\nGive the Lord the glory of His name.\nAdore the Lord in His holy court.",
          "2. The Lord's voice resounding on the waters:\nThe Lord on the immensity of waters.\nThe voice of the Lord, full of power.\nThe voice of the Lord, full of splendour.",
          "3. The Lord's voice shattering the cedars.\nThe Lord shatters the cedars of Lebanon.\nHe makes Lebanon leap like a calf.\nAnd Sirion like a young wild ox.",
          "4. The Lord's voice shaking the wilderness,\nThe Lord shakes the wilderness of Kadesh.\nThe Lord's voice rending the oak tree\nand stripping the forest bare.",
          "5. The God of glory thunders.\nIn his temple they all cry glory.\nThe Lord sat enthroned over the flood.\nThe Lord sits as king forever.",
          "6. Give glory to the Father Almighty,\nto His Son, Jesus Christ, The Lord,\nto the Spirit who dwells in our hearts\nboth now and forever.",
        ],
