      Hymn(
        id: 72,
        number: "72",
        title: "Burdens Are Lifted At Calvary",
        category: "Praise & Worship",
        refrain: "Burdens are lifted at Calvary,\nCalvary, Calvary,\nBurdens are lifted at Calvary,\nJesus is very near.",
        stanzas: [
          "1. Days are filled with sorrow and care,\nhearts are lonely and drear;\nBurdens are lifted at Calvary,\nJesus is very near.",
          "2. Cast your cares on Jesus today,\nleave your worry and fear.",
          "3. Troubled soul, the saviour can see,\nevery heartache and tear.",
        ],
      ),
      Hymn(
        id: 73,
        number: "73",
        title: "By The Blood That Flowed",
        category: "Lent & Passion",
        refrain: "Jesus Saviour, hear our cry;\nThou wert suffering once as we;\nNow enthroned in majesty\ncountless angels sing to Thee.",
        stanzas: [
          "1. By the blood that flowed\nfrom Thee in Thy bitter agony;\nBy the traitor's guileful kiss,\nfilling up Thy bitterness.",
          "2. By the cords that round, Thee cast\nBound Thee to the pillar fast\nBy the scourge so meekly borne,\nBy the purple robe of scorn.",
          "3. By the thorns that crowned Thy head\nBy the sceptre of a reed;\nBy the foes on bending knee,\nmocking at Thy royalty.",
          "4. By the peoples' cruel jeers;\nBy the holy women's tears;\nBy the footsteps, faint and slow\nweighed beneath Thy cross of woe.",
          "5. By Thy weeping mother's woe\nBy the sword that pierced her through\nwhen in anguish standing by,\non the cross she saw Thee die.",
        ],
      ),
      Hymn(
        id: 74,
        number: "74",
        title: "By The First Bright Easter",
        category: "Easter & Resurrection",
        stanzas: [
          "1. By the first bright Easter day,\nwhen the stone was rolled away,\nBy the glory round Thee shed,\nAt thy rising from the dead.",
          "2. King of glory, hear our cry,\nMake us soon Thy joys to see,\nHear the loving litany,\nwe Thy children, sing to Thee.",
          "3. By the joys of Magdalen,\nWhen she saw Thee once again\nBy Thy keys of might divine,\nvested in St. Peter's arm.",
        ],
      ),
      Hymn(
        id: 75,
        number: "75",
        title: "Canticle of Zechariah",
        category: "Praise & Worship",
        stanzas: [
          "1. Blessed be the Lord the God of Israel\nthe ever living Lord,\nWho comes in power to save his own,\nHis people Israel.\nFor Israel He raises up salvation's tower on high\nIn David's house who reign as king\nand servant of the Lord.",
          "2. Through holy prophets did He speak\nHis word in days of old.\nThat He will save us from our foes\nand all who bear us ill.\nTo our ancestors did He give\nHis covenant of love;\nSo with us all He keeps His word\nin love that knows no end.",
          "3. Of old He gave His solemn oath\nto father Abraham;\nHis seed a mighty race should be,\nand blest forever more.\nHe vowed to set His people free\nfrom fear of every foe.\nThat we might serve Him all our days\nin goodness, love and peace.",
          "4. O tiny child, your name shall be\nthe prophet of the Lord;\nThe way of God you shall prepare\nto make His coming known.\nYou shall proclaim to Israel\nsalvation's dawning day,\nWhen God shall wipe away our sins\nin His redeeming love.",
          "5. The rising sun shall shine on us\nto bring the light of the day,\nTo all who sit in darkest night\nand shadow of the grave.\nOur footsteps God shall safely guide\nto walk the ways of peace;\nHis name forever more be blest\nwho lives and loves and saves.",
        ],
      ),
      Hymn(
        id: 76,
        number: "76",
        title: "Children of Jerusalem",
        category: "Praise & Worship",
        stanzas: [
          "1. Children of Jerusalem\nsound the Praise of Jesus name.\nChildren too of modern days\njoin to sing the saviour's praise\nHark! hark! hark! While infant voices sing\nHark! hark! hark! while infant voices sing\nLoud Hosanna! loud hosanna!\nloud hosanna to our king!",
          "2. We are taught to love the Lord,\nWe are taught to read the words,\nWe are taught the way to heaven\nPraise for all to God be given.",
          "3. Parents, teachers, old and young\nAll unite to swell the song\nHigher-and yet higher rise\nTill hosanna reach the skies.",
        ],
      ),
      Hymn(
        id: 77,
        number: "77",
        title: "Children of the Lord",
        category: "Offertory",
        refrain: "Children of the Lord-ee\nChildren of the great Father\nBring your gifts to offer him,\nAlleluia Amen\nSing Alleluia eee- Alleluia sing\nAlleluia, Alleluia. Amen,",
        stanzas: [
          "1. Children we are here to worship the Lord.\nSing and glorify Him with your heart\nBring all that you have to offer Him Alleluia. Amen.",
          "2. Mothers we are here to worship the Lord.\nSing and glorify Him with your heart\nBring all that you have to offer Him Alleluia Amen.",
          "3. Fathers we are here to worship the Lord.\nSing and glorify Him with your heart\nBring all that you have to offer Him Alleluia Amen.",
          "4. Christians we are here to worship the Lord\nSing and glorify Him with your heart\nBring all that you have to offer him Alleluia Amen.",
        ],
      ),
      Hymn(
        id: 78,
        number: "78",
        title: "Christ Be Beside Me",
        category: "Recessional",
        stanzas: [
          "1. Christ be beside me, Christ be before.\nChrist be behind me, King of my heart.\nChrist be within me, Christ be below me\nChrist be above me, never to part.",
          "2. Christ on my right hand, Christ on my left hand,\nChrist all round me, shield in the strife.\nChrist in my sleeping, Christ in my sitting.\nChrist in my rising, Light of my life.",
          "3. Christ be in all hearts, thinking about me\nChrist be on all tongues, telling of me.\nChrist be the vision in eyes that see me.\nIn ears that hear-me, Christ ever be.",
        ],
      ),
      Hymn(
        id: 79,
        number: "79",
        title: "Christ Be Near",
        category: "Praise & Worship",
        stanzas: [
          "1. Christ be near at either hand.\nChrist behind before me stand,\nChrist with me wher'er I go\nChrist, around, above, below.",
          "2. Christ be in my heart and mind,\nChrist within my soul-enshrined\nChrist control my wayward heart;\nChrist abide and ne'er depart.",
          "3. Christ my life, and only way,\nChrist my lantern night and day,\nChrist be my unchanging friend.\nGuide and Shepherd to the end.",
          "4. Christ be all my strength and might.\nChrist my captain for the fight,\nChrist fulfill my soul's desire.\nChrist enable and inspire.",
          "5. Christ the King and Lord of all,\nFind me ready at His call,\nChrist receive my service whole.\nHand and body, heart and soul.",
          "6. Christ the King of Kings descend\nand of tyrants make an end;\nChrist on us and all below,\nConcord, love and peace bestow.",
        ],
      ),
      Hymn(
        id: 80,
        number: "80",
        title: "Christ Come Quickly",
        category: "Advent & Christmas",
        stanzas: [
          "1. Christ come quickly,\nthere's danger at the door.\nPoverty aplenty,\nhearts gone wild with war.\nThere's hunger in the city\nand famine on the plain.\nCome Lord Jesus, the light is dying\nThe night keeps crying,\nCome, Lord Jesus,",
          "2. Want demands a hearing\nin far too many lands.\nThe sick go unattended,\ndeath deals a heavy hand.\nThe dreams of men are empty,\ntheir cup of sorrow full.",
          "3. The world awaits in darkness,\na mighty burst of light,\nto set the lame man leaping,\nto give the blind man sight.\nWe have the prophet's promise,\nwe await the Prince of Peace.",
        ],
      ),
      Hymn(
        id: 81,
        number: "81",
        title: "Christ Is Alive",
        category: "Easter & Resurrection",
        refrain: "Christ is alive, with joy we sing,\nWe celebrate our risen Lord,\npraising the glory of His name.\nAlleluia, Alleluia, Alleluia.",
        stanzas: [
          "1. Christ is alive, with joy we sing,\nWe celebrate our risen Lord,\npraising the glory of His name.\nAlleluia, Alleluia, Alleluia.",
          "2. He is the grain of wheat that died\nsown in distress and reaped in joy\nyielding a harvest of new life.",
          "3. He is the sun which brings the dawns;\nHe is the light of all the world\nsetting us free from death and sin.",
        ],
      ),
      Hymn(
        id: 82,
        number: "82",
        title: "Christ Is King of the Earth and Heaven",
        category: "Praise & Worship",
        stanzas: [
          "1. Christ is King of the earth and heaven!\nLet his subjects all proclaim,\nIn the splendour of his temple,\nHonour to his holy name.",
          "2. Christ is King, no soul created,\nCan refuse to bend the Knee,\nTo the God made man who reigneth,\nAs 'twas promised from the tree.",
          "3. Christ is King! Let humble sorrow,\nFor our past neglect atone,\nFor the sake of faithful service,\nTo the master whom we own.\nChrist is King! Let joy and gladness,\nGreet him, let his courts resounds,\nWith the praise of faithful subjects,\nTo his love in honour bound.",
          "4. Christ is King! In health and sickness,\nTill we breathe our latest breath,\nTill we greet in highest heaven,\nChrist the victor over death.",
        ],
      ),
      Hymn(
        id: 83,
        number: "83",
        title: "Christ Is My Rock",
        category: "Praise & Worship",
        refrain: "Christ is my Rock, my Refuge,\nmy Stronghold!\nFirm as the tree's root that clutches the land;\nHe who has faith, builds without worry:\nnot like a man who builds upon sand;\nI set my house on a solid foundation\nChrist is my Rock, the root of my soul's recreation.",
        stanzas: [
          "1. I know a man who loved to live free\nHe pitched his tent by the side of the sea,\nIt stood near the surf and was washed by the spray,\ntill one day a wave came and washed it away.",
          "2. I know a man who loved to live high\nHe built his castle near up to the sky.\nThrough summer and spring, it stood pretty well,\nwinter winds whistled it toppled and fell.",
          "3. I know a man, a cool one to know\nHe built his house out of ice and of snow\nIn chill isolation his night work was done.\nBut it melted away with the warm morning sun.",
          "4. I know a man who built out of straw\nthe flimsiest fellow that I ever saw.\nOne day a spark set it to flame\nAnd nothing was left to remember his name.",
        ],
      ),
      Hymn(
        id: 84,
        number: "84",
        title: "Christ Is Risen",
        category: "Easter & Resurrection",
        refrain: "Christ the Lord is risen,\nJesus is Risen, (Alleluia)\nVictory is here,\nDeath is no more Alleluia\nDeath is no more Alleluia",
        stanzas: [
          "1. When the soldiers were beating My Lord Jesus\nthey thought it was his end\nWhen the soldiers were killing my Lord Jesus -\nthey thought it was his end\nWhen they pierced the side of my Lord Jesus\nthey thought it was his end.",
          "2. Early in the morning, the women Came calling\nTo anoint his body in the tomb Where he lay\nMary do not touch me For I've not been to my father\nWe shall see in Galilee, Jesus said",
          "3. Mary will cry no more\nOh the disciples will weep no more\nYes! Christians will cry no more\nOh the believers will weep no more\nHe is risen Death o where is thy strength\nOh death oh where is thy sting\nYes! Alleluia oh weep no more.\nAlleluia oh weep no more He is risen.",
        ],
      ),
      Hymn(
        id: 85,
        number: "85",
        title: "Christmas Comes To Bless The Earth",
        category: "Advent & Christmas",
        stanzas: [
          "1. Christmas comes to bless the earth\nWith its wondrous heavenly birth\nBright and high the dawning light\nBurneth through the gloom of night",
          "2. God hath come with men to dwell,\nChrist is born in Israel;\nThrilling songs his angels sing,\nWorshiping their infant king.",
          "3. Easter with its flaming crown\nTramples all the darkness down\nTyrant spectres of the gloom\nDie before the open tomb.",
          "4. Christ hath risen from the grave\nChrist hath risen, strong to save\nThrilling song his angels sing\nWorshipping their victor king.",
          "5. Thus he reign beyond the sky\nIn the love that cannot die\nYet the men doth ever dwell,\nInto the midst of Israel.",
          "6. So before is altar now\nAll his radiant angels bow\nThrilling song they ever sing\nWorshipping their hidden king.",
          "7. Comes the shadow of the tomb\nComes the fearful day of doom\nDarkling cloud about us lower\nJesus save us in that hour.",
          "8. By the Christmas frost and snow\nEaster's bright and burning glow\nLight around thy altar shed\nSave us in that hour of dread.",
        ],
      ),
      Hymn(
        id: 86,
        number: "86",
        title: "Christ Our Pasch",
        category: "Easter & Resurrection",
        refrain: "Christ our pasch has been slain, Alleluia\nChrist Himself, Alleluia, Alleluia, Alleluia.",
        stanzas: [
          "1. Pasch of the new law the spirit's holy feast;\nO pasch of Christ the Lord who for us has come to earth.",
          "2. Pasch of the new law, O joy of all mankind;\nThe doors of life are wide, giving life to us once more.",
          "3. Pasch of the new law, the banquet hall is full of guests\nthe Lord has called that all men may share his feast.",
          "4. Pasch of the new law, behold your baptized saints\nin robes of purest white for the marriage of the lamb.",
          "5. Pasch of the new law, Our soul's immortal flame\nshines forth in splendour bright never more to cease its light.",
          "6. Pasch of the new law, O Christ who lives again.\nThe power of death you crushed, you have given us your life.",
          "7. Pasch of the new law, we pray to you O Lord,\nStretch forth your blessed hands on the people you have saved.",
          "8. Pasch of the new law, O Christ, receive our songs;\nTo you be glory, Lord, with all joy and praise. Amen.",
        ],
      ),
      Hymn(
        id: 87,
        number: "87",
        title: "Christ The Lord",
        category: "Easter & Resurrection",
        stanzas: [
          "1. Christ the Lord is risen today, Alleluia.\nChristians haste your vows to pay, Alleluia.\nOffer ye your praises meet Alleluia.\nAt the Paschal's victim's feet, Alleluia",
          "2. For the sheep the lamb hath bled, Alleluia.\nSinless in the sinners' stead, Alleluia.\nChrist the Lord is risen on high. Alleluia,\nNow He lives, no more to die, Alleluia.",
          "3. Christ, the Victim undefiled, Alleluia.\nMan to God hath reconciled, Alleluia.\nWhen in strange and awful strife, Alleluia.\nMet together death and life. Alleluia.",
          "4. Christians on this happy day, Alleluia.\nHaste with joy your vows to pay, Alleluia.\nChrist the Lord is risen on high, Alleluia.\nNow He lives no more to die, Alleluia.",
          "5. Say, O wondering Mary, say, Alleluia.\nWhat thou sawest on the way, Alleluia.\nI beheld where Christ had lain, Alleluia.\nEmpty tomb and angels twain, Alleluia.",
          "6. I beheld the glory bright, Alleluia.\nOf the risen Lord of light, Alleluia.\nChrist my hope is risen again, Alleluia.\nNow he lives and lives to reign, Alleluia.",
          "7. Christ who once for sinners bled, Alleluia.\nNow the first born from the dead Alleluia.\nThroned in endless might and power Alleluia.\nLives and reigns for evermore, Alleluia.",
        ],
      ),
      Hymn(
        id: 88,
        number: "88",
        title: "Colours of Day",
        category: "Praise & Worship",
        refrain: "So light up the fire and let the flame burn.\nOpen the door. Let Jesus return.\nTake seeds of his spirit. Let the fruit grow.\nTell the people of Jesus. Let His love show.",
        stanzas: [
          "1. Colours of day dawn into the mind.\nThe sun has come up. The night is behind.\nGo down in the city into the street.\nAnd let's give the message to the people we meet.",
          "2. Go through the park, on into the town\nThe sun still shines on It never goes down\nThe light of the world is risen again\nThe people of darkness are needing our friend.",
          "3. Open your eyes, look into the sky,\nThe darkness has come, The sun came to die\nThe evening draws on, the sun disappears,\nBut Jesus is living and His Spirit is near.",
        ],
      ),
      Hymn(
        id: 89,
        number: "89",
        title: "Come And Go With Me",
        category: "Praise & Worship",
        refrain: "Happy, happy, happy, we shall be, Alleluia. (2)\nHappy, happy, happy we shall be in my Father's house above.",
        stanzas: [
          "1. Come and go with me to my Father's house;\nto my Father's house, to my Father's house,\nCome and go with me to my Father's house\nwhere there's joy, joy, joy.\nIn my Father's house there are many mansions there,\nin my Father's house, in my Father's house.\nIn my Father's house there are many mansions;\nthere O in my Father's house above,",
          "2. We will dance and sing in my Father's house...",
          "3. We will clap our hands in my Father's house...",
          "4. It's not very far to my Father's house.",
          "5. Jesus is the way to my Father's house.",
        ],
      ),
      Hymn(
        id: 90,
        number: "90",
        title: "Come Away",
        category: "Entrance",
        refrain: "Come away to the land of freedom,\nCome away, come away.\nTo a land where all men are as brothers.\nCome away, come away, come away.",
        stanzas: [
          "1. God made a land to live in;\nCome away, come away.\nIt's not too far if you do want it\nCome away, come away, come away.",
          "2. The land is flowing with all riches.\nCome away, come away.\nHappiness and other such wishes;\nCome away, come away, come away.",
          "3. If you want to find that land now,\ncome away, come away, just take my hand.\nAnd you're half way there now;\nCome away, come away, come away.",
          "4. Side by side we shall walk together\nCome away, come away.\nAnd all the way we shall love each other;\nCome away, come away, come away.",
