        number: "91",
        title: "Come, Children Join To Sing",
        category: "Praise & Worship",
        stanzas: [
          "1. Come, children, join to sing Alleluia.\nLoud praise to Christ our King;\nAlleluia. Amen.\nLet all, with heart and voice before His throne rejoice.\nPraise His gracious choice,\nAlleluia. Amen.",
          "2. Come, lift your hearts on high,\nAlleluia! Amen\nLet praises fill the sky\nAlleluia! Amen\nHe is our guide and friend;\nTo us he'll blessing send;\nHis love shall never end.\nAlleluia. Amen.",
          "3. Praise ye the Lord again:\nAlleluia, Amen.\nLife shall not end the strain:\nAlleluia. Amen.\nOn heaven's blissful shore,\nHis goodness we'll adore.\nSinging for evermore,\nAlleluia. Amen.",
        ],
      ),
      Hymn(
        id: 92,
        number: "92",
        title: "Come Down, Lord",
        category: "Communion",
        stanzas: [
          "1. Come down, Lord my son is ill,\nwracked with fever the life-long day.\nHe is life to me, if you will,\ndrive death away, drive death away.\nLord do not come to my house.\nI'm unworthy speak and promise is sealed.\nFor when Your Word, O God, is spoken.\nHe shall be healed. He shall be healed.",
          "2. Come down, Lord, my soul is ill.\nwracked with anguish the life-long day.\nAll my sorrowing will be still,\nIf You but say, if You but say.\nLord, do not come to my house,\nI'm unworthy. Speak and the promise is sealed.\nFor when Your Word, O God, is spoken,\nI shall be healed, I shall be healed.",
          "3. Come down. Lord, the world is ill,\nwracked with bloodshed the life-long day.\nMan must struggle for peace\nuntil You show the way You show the way.\nLord, do not come to our house,\nWe're unworthy. Speak and the promise is sealed.\nFor when Your Word, O God, is spoken\nWe shall be healed, We shall be healed.",
        ],
      ),
      Hymn(
        id: 93,
        number: "93",
        title: "Come God's Children",
        category: "Offertory",
        stanzas: [
          "1. Come God's children let us sing, Alleluia.\nBringing gifts to praise our King, Alleluia.\nDrawing close in heart and mind, Alleluia.\nThat by His aid and truth we'll find, alleluia.",
          "2. We offer gifts of bread and wine, Alleluia.\nIn Christ our Lord, the Son divine, Alleluia.\nIn joyful song our voices raise, Alleluia.\nTo God above we offer praise. Alleluia.",
          "3. We must love Him with our heart, Alleluia.\nas a whole and not apart, Alleluia.\nCome God's children, let us sing, Alleluia.\nBringing gifts to praise our King, Alleluia.",
