        number: "96",
        title: "Come Let Us Muse Devoutly",
        category: "Advent & Christmas",
        refrain: "Come let us muse devoutly\nFor Jesus born on Christmas day\nTis our Lord's sweetest mystery.\nWhich does His love explain.",
        stanzas: [
          "1. Joseph and Mary who both trace\nTo David their true royal race\nArrive in Bethlehem found no place\nExcept a wretched stable\nWhich by their saviour's blessed birth\nBecomes most honourable\nThe holiest shrine on earth.",
          "2. Night has now spread, all shadows\nStern sad and cold herself, she shows\nJust as if to foretell great woes\nHas she figured but weakly\nThe darkness night of sin and crime\nWhich kept men in obscurity\nFrom earliest age to time.",
