          "2. Come, lets share the ascension of the Lord,\nin the Blessed Sacrament.\nCome lets share our union with the Lord,\nin the Blessed Sacrament.",
          "3. Come, lets share in the life of the Lord,\nin the Blessed Sacrament.\nCome, lets share in the love of the Lord,\nin the Blessed Sacrament.\n(Repeat verse 1)",
        ],
