      Hymn(
        id: 98,
        number: "98",
        title: "Come Lord Jesus, Come",
        category: "Advent & Christmas",
        stanzas: [
          "1. Come Lord Jesus, come.\nCome take my hands.\nTake them for Your work,\ntake them for Your service, Lord.\nTake them for Your glory, Lord\nCome, Lord Jesus come.\nCome, Lord Jesus take my hand.",
          "2. Come, Lord Jesus, come\nCome, take my eyes.\nMay they shine with joy.\nTake them for Your service, Lord.\nTake them for Your glory, Lord.\nCome Lord Jesus, come.\nCome Lord Jesus take my eyes.",
          "3. Come, Lord Jesus, come.\nCome take my lips.\nMay they speak Your truth.\nTake them for Your service Lord.\nCome, Lord Jesus come.\nCome Lord Jesus take my lips.",
          "4. The clouds shall send a Saviour\nlike softly falling rain;\nYet mighty in his power,\nto free us from our chains.\nHis shield will be compassion,\nHis weapon liberty.",
