        number: "100",
        title: "Come My Brothers",
        category: "Praise & Worship",
        stanzas: [
          "1. Come my brothers, praise the Lord Alleluia.\nPraise the Lord, for He is God, Alleluia.",
          "2. Come to Him with songs of praises, Alleluia.\nSongs of praise, rejoice in Him, Alleluia.",
          "3. For the Lord is mighty God, Alleluia.\nHe is the King of all the world, Alleluia.",
          "4. In His hands are valleys deep, Alleluia.\nIn His hands are mountain peaks, Alleluia.",
          "5. In His hands are all the seas, Alleluia,\nAnd all the lands which He has made. Alleluia.",
          "6. Come, my brothers, praise the Lord, Alleluia.\nHe's our God and we are His, Alleluia.",
          "7. Praise the Father, praise the Son, Alleluia.\nPraise the spirit, the Holy One, Alleluia.",
