          "2. Come bless His name,\nyou children of the Lord.\nCome sing His praise and let the trumpet sound,\nAlleluia (4).",
          "3. Rejoice in God,\nHis love descends on us.\nLift up your voice and sound His name afar.\nAlleluia (4).",
