        number: "104",
        title: "Come Sound His Praise Abroad",
        category: "Praise & Worship",
        refrain: "Praise ye the Lord, Alleluia!\nPraise ye the Lord, Alleluia!\nAlleluia (3)\nPraise ye the Lord.",
        stanzas: [
          "1. Come, sound his praise abroad\nand hymns of glory sing.\nYahweh is the sovereign Lord,\nthe universal King.",
          "2. He formed the deeps unknown;\nHe gave the seas their bounds;\nthe watery worlds are all His own,\nAnd all the solid ground.",
          "3. Come, worship at His throne.\nCome, bow before the Lord.\nWe are His work and not our own,\nHe formed us by His Word,",
          "4. Today, attend His voice\nnor dare provoke His rod.\nCome, like the people of His choice.\nAnd own your precious God.",
