      Hymn(
        id: 105,
        number: "105",
        title: "Come Thou Almighty King",
        category: "Praise & Worship",
        stanzas: [
          "1. Come Thou Almighty King\nHelp us your name to sing\nHelp us to praise\nFather all glorious, wholly victorious\nCome and rule over us, Ancient of days.",
          "2. Come Thou incarnate word\nAnd make your message heard\nOur prayer attend;\nCome and your people, bless,\nAnd give your word success,\nAnd let your holiness to us descend.",
          "3. Come, Holy Comforter\nYour sacred witness bear\nIn this glad hour;\nYou who almighty art, enlighten ev'ry heart\nFrom us do not depart Spirit of pow'r.",
          "4. To you great one in three\nEternal praises be, Hence ever more!\nYour sovereign majesty. May we in glory see\nAnd to eternity love and adore.",
