      ),
      Hymn(
        id: 106,
        number: "106",
        title: "Come Together",
        category: "Entrance",
        refrain: "Come together, come together,\ncome together in Jesus Name. (2)\nO let it shine, shine, shine\nCome on and let your light shine. (4)",
        stanzas: [
          "1. Jesus people come together let your light shine.\nShare your love with one another let your light shine.\nLet no difference come between you Let your light shine.\nLet the Spirit flow within you, let your light shine.",
          "2. Jesus people come together let your light shine.\nCome and worship your redeemer let your light shine.\nSing for joy and shout for gladness let your light shine\nCome and praise Him for His goodness Let your light shine.",
          "3. Jesus people come together let your light shine.\nTell the world about your Saviour let your light shine.\nPreach the gospel of salvation let your light shine.\nSpread the news to every nation let your light shine.",
        ],
      ),
      Hymn(
        id: 107,
        number: "107",
        title: "Come To Me Over The Water, Peter",
        category: "Praise & Worship",
        refrain: "Come to me over the water, Peter\nWalk on the waves of the stormy sea.\nI know your boat is frail and fragile.\nBut believe in me.",
        stanzas: [
          "1. I can do anything when faith doesn't weaken.\nSea, the sea sleeps in the palm of my hand.\nMy love's a light that leads like a beacon\nto the promised land.",
          "2. My people called out from the burning desert.\nI turned a rock to a bubbling spring.\nHe who believes will never be wanting for anything.",
        ],
      ),
      Hymn(
