          "2. Come with precious ointment\nto the mountains of the Lord.\nCome with your humble offerings to God\nCome to Him now\nHasten to pay Him your vows.",
          "3. Come with your guitars and cymbals\nto the mountains of the Lord.\nCome with your music, singing to God.\nLift up your voice.\nOurs is the God of Jacob rejoice!",
