      Hymn(
        id: 110,
        number: "110",
        title: "Come To The Water",
        category: "Communion",
        stanzas: [
          "1. O let all who thirst, let them come to The water.\nAnd let all who have Nothing let them come to the Lord\nWithout money, without price,\nwhy Should you pay the price, except for the Lord.",
          "2. And let all who seek, let them come to The water.\nAnd let all who have Nothing, let them come to the Lord\nWithout money, without strife.\nWhy Should you spend your life except for The Lord?",
          "3. And let all who toil, let them come to The water,\nAnd let all who are weary Let them come to the Lord\nall who Labour without rest.\nhow can your soul Find rest, except for the Lord?",
          "4. And let all the poor, let them come To the water\nbring the one who are laden Bring them all to the Lord,\nBring the children without might\nEasy the load and light. Come to the Lord.",
        ],
      ),
      Hymn(
        id: 111,
        number: "111",
        title: "Come Ye Children Of God",
        category: "Offertory",
        refrain: "We offer with pleasure our gifts\nat the altar to God Almighty, Alleluia!",
        stanzas: [
          "1. Come ye children of God, come with your gifts.\nOffer them to God and receive His blessings.",
          "2. Offer from the abundance of your heart.\nThe Lord is the Giver of all that you have.",
          "3. The widow's mite is little on earth.\nYet she made a name, And was great in heaven.",
          "4. Your offering is to God, the Creator.\nLet open your heart and mind to Him.",
