      Hymn(
        id: 113,
        number: "113",
        title: "Crown Him With Many Crowns",
        category: "Praise & Worship",
        stanzas: [
          "1. Crown him with many crowns, the Lamb Upon his throne,\nHark! How the heavenly Anthems drowns all music but its own\nAwake my soul and sing of him who Died for and hail him\nas your Matchless King with worship as his due.",
          "2. Crown him the Lord of peace, whose Power a sceptre sways\nfrom pole to Pole, that wars may cease,\nabsorbed in prayer and praise his reign shall Known no end\nand round his pierced feet Fair flower of paradise extend\ntheir Fragrance ever sweet.",
          "3. Crown him the Lord of life who Triumphed o'er the grave,\nand rose Victorious in strife for those he came To save,\nhis glories now we sing Who died and rose on high,\nwho died Eternal life to bring and lives that Death may die.",
          "4. Crown him the Lord of years, The Potentate of time,\ncreator of the Rolling spheres ineffably sublime\nAll hail, redeemer hail for you have Died for me\nyour praise shall never Never fail throughout eternity. Amen.",
        ],
      ),
      Hymn(
        id: 114,
        number: "114",
        title: "Cry of the Poor",
        category: "Offertory",
        refrain: "The Lord hears the cry of the poor.\nBlessed be the Lord.",
        stanzas: [
          "1. I will bless the Lord at all times\nHis praise ever in my mouth\nLet my soul glory in the Lord\nFor he hears the cry of the poor.",
          "2. Let the lowly hear and be glad\nThe Lord listens to their pleas\nAnd to hearts broken he is near\nFor he hears the cry of the poor.",
          "3. Every Spirit crushed he will save.\nWill be ransom for their lives\nWill be safe shelter for their fears\nFor he hears the cry of the poor.",
          "4. We proclaim the greatness of God\nHis praise ever in our mouth\nEvery face brightened in his light\nFor he hears the cry of the poor.",
        ],
      ),
      Hymn(
        id: 115,
        number: "115",
        title: "Daily Daily Sing To Mary",
        category: "Marian",
        stanzas: [
          "1. Daily, daily, sing to Mary,\nSing, my soul her praises due.\nAll her feasts her actions worship\nwith the heart's devotion true,\nLost in wondering contemplation\nbe her majesty confessed.\nCall her Mother, call her Virgin,\nHappy Mother, Virgin Blest.",
          "2. She is mighty to deliver.\nCall her, trust her lovingly.\nWhen the tempest rages round thee\nshe will calm the troubled sea.\nGifts of heaven she has given noble lady, to our race\nShe, the Queen who decks her subjects\nwith the light of God's own grace.",
          "3. Sing, my tongue the Virgin's trophies\nwho for us her Maker bore,\nfor the curse of old inflicted peace and blessings to restore.\nSing in songs of praise unending.\nSing the world's majestic Queen,\nWeary not nor faint in telling all the gifts she gives to men.",
          "4. All my senses, heart, affections\nstrive to sound her glory forth\nSpread abroad the sweet memorials\nof the Virgin's priceless worth.\nWhere the voice of music thrilling\nwhere the tongues of eloquence,\nthat can utter hymns beseeming all her matchless excellence.",
          "5. All our joys do flow from Mary.\nAll then join her praise to sing.\nTrembling sing the Virgin Mother,\nMother of Our Lord and King.\nWhile we sing her awful glory for above our fancy's reach\nlet our hearts be quick to offer\nlove the heart alone can teach.",
        ],
      ),
      Hymn(
        id: 116,
        number: "116",
        title: "Dance In The Darkness",
        category: "Praise & Worship",
        refrain: "Dance in the darkness, slow be the pace\nSurrender to the rhythm of redeeming grace.",
        stanzas: [
          "1. Although you go forth weeping\nCarrying the seed to sow\nYou shall come back rejoicing\nCarrying your sheaves full grown.",
          "2. A woman in childbirth suffers\nBecause her time has come\nBut when she holds her child in her arms\nHer joy returns again.",
          "3. Jesus Lord of weakness\nWe wait in joyful hope\nSee our weakness, be our strength.",
        ],
      ),
      Hymn(
        id: 117,
        number: "117",
        title: "Day Is Done",
        category: "Recessional",
        stanzas: [
          "1. Day is done but love unending dwells ever here\nShadows fall but hope prevailing calms every fear.\nLoving Father none forsaking\nTake our hearts of love's own making\nWatch our sleeping, guard our waking\nBe always near.",
          "2. Dark descends but light unending shines through the night.\nYou are with us ever lending new strength to sight\nOne in love Your Truth confessing\nOne in hope of heaven's blessing,\nmay we see in love possessing\nLove's endless light.",
          "3. Eyes will close but You unsleeping watch by our side.\nDeath may come: in love's safe keeping still we abide.\nGod of love, all evil quelling\nsin forgiving, fear dispelling.\nStay with us our hearts in dwelling\nthis eventide.",
        ],
      ),
      Hymn(
        id: 118,
        number: "118",
        title: "Dear Maker of the Starry Skies",
        category: "Advent & Christmas",
        stanzas: [
          "1. Dear maker of the starry skies,\nLight never lost by faithful eyes,\nChrist, the salvation sent to all\nBe near thy servants when they call.",
          "2. Thy love that pitied from on high\nA guilty race foredoomed to die,\nWas fain that sentence to repeal,\nfailing energies to heal.",
          "3. So, at the eventide of earth,\nFrom that bride chamber of thy birth\nOur mortal flesh thou didst assume,\nBorn of a spotless Virgin's womb.",
          "4. O thou, at whose August decree,\nOnce heard, creation bends the knee,\nWhile heaven and earth obey thy will,\nTrembling before thee, and are still.",
          "5. Holiest of holy ones, from whom\nEternity receives its doom,\nIn this brief world of time, we pray,\nKeep Satan's treacherous darts at bay.",
          "6. To God the Father, God the Son,\nAnd God the Spirit, three in one.\nGlory and power and majesty\nThrough everlasting ages be.",
        ],
      ),
      Hymn(
        id: 119,
        number: "119",
        title: "Decade of Love",
        category: "Advent & Christmas",
        refrain: "Enter then we implore thee\nEternity's sovereign Lord\nEnkindle our decade of love\nCome O Lord bless this company.",
        stanzas: [
          "1. Our eyes in gladsome welcome\nOur hearts warm to embrace\nOur decade of love enkindle\nLord Thou word that's ten times sent.",
          "2. King by your cradle we stand\nOur salvation gift true\nO naught be our gift which we bring\nChrist Jesus be our word.",
          "3. Stay we here in your presence\nShun not our heart and voice\nThou shelter for young and old alike\nYour glory may we see.",
        ],
      ),
      Hymn(
        id: 120,
        number: "120",
        title: "Deep In The Mountains",
        category: "Entrance",
        refrain: "Deep in the mountains deep in the hills,\nsee how our God is come to meet us.\nHis voice is lifted, His face is joy.\nNow is the season to sing our song on high.",
        stanzas: [
          "1. Come then O Lord of glory.\nShow us your face.\nSpeak, for we know Your words are light.",
          "2. He pastures His flock among the wild flowers,\nAnd leads them to the mountain of His love.",
        ],
      ),
      Hymn(
        id: 121,
        number: "121",
        title: "Ding Dong! Merrily On High",
        category: "Advent & Christmas",
        stanzas: [
          "1. Ding dong merrily on high\nIn heaven the bells are ringing:\nDing dong verily the sky,\nIs riv'n with Angel singing.\nGloria, hosanna in excelsis!",
          "2. E'en so here below, below\nLet steeple bells be swungen\nAnd i-o, i-o, i-o,\nBy priest and people sungen\nGloria hosanna in excelsis!",
          "3. Pray you dutifully prime,\nYour Matin chime ye ringers;\nMay you beautifully rime\nYour evetime song, ye singers:\nGloria hosanna in excelsis!",
        ],
      ),
      Hymn(
        id: 122,
        number: "122",
        title: "Don't Allow",
        category: "Praise & Worship",
        stanzas: [
          "1. Don't allow the cares of this world to overtake you from God's sight.\nJust at last you hear a voice saying:\nI know you not, I know you not.\nJust at last you hear a voice saying:\nI know you not, depart from me.",
          "2. Don't allow the knowledge of this world to overtake you from God's sight.\nJust at last you hear a voice saying:\nI know you not, I know you not.\nJust at last you hear a voice saying:\nI know you not, depart from me.",
          "3. Don't allow the power of this world to overtake you from God's sight.\nJust at last you hear a voice saying:\nI know you not, I know you not.\nJust at last you hear a voice saying:\nI know you not, depart from me.",
          "4. Don't allow the riches of this world to overtake you from God's sight.\nJust at last you hear a voice saying:\nI know you not, I know you not.\nJust at last you hear a voice saying:\nI know you not, depart from me.",
        ],
      ),
      Hymn(
        id: 123,
        number: "123",
        title: "Don't Worry About Food",
        category: "Offertory",
        refrain: "Don't worry about food or What you are to wear\nIs life not more precious by far.\nChrist clothe you in his image,\nAnd feed you with his flesh.,\nAnd loves you as you are.",
        stanzas: [
          "1. Lord hear me I am a hungry man\nI've had a craving since before the World began\nwhere shall find bread\nThat I may eat my fill\nAnd feed my weakening will.",
          "2. Lord I drink I still thirst for more\nI hear your living water goes rushing\nPast my door\nGive me to drink, assuage my burning thirst\nAnd live my soul immersed.",
          "3. Lord, I am a pauper before the throne of God,\nI am in tatters my feet are all unshod,\nI would have virtue, to hide my nakedness\nLord, who will give me dress.",
        ],
      ),
      Hymn(
        id: 124,
        number: "124",
        title: "Do You Know",
        category: "Praise & Worship",
        stanzas: [
          "1. Do you know that the Lord walks on earth?\nDo you know He is living here now?\nHe is waiting for all men to recognize Him here.\nDo you know that the Lord walks on earth?",
          "2. Do you know that He walks in disguise?\nDo you know He's in crowds everywhere?\nevery place that you go you may find that He is there.\nDo you know that He walks in disguise?",
          "3. Do you know that the Lord thirsts so much?\nDo you know that He is sitting in jail?\nEverywhere He is hungry and naked in the cold.\nDo you know He is rejected without care?",
          "4. Do you know He is crucified each day?\nDo you know that He suffers and dies?\nEv'ry where He is lonely and waiting for a call.\nDo you know He is sick and all alone?",
          "5. Do you know that He wants to be free?\nDo you know He wants helps from you and me?\nHe has need of our hands and our Feet and heart to serve.\nDo you know He can only work through men,",
          "6. Do you know that the Lord dwells in men?\nDo you know He resides in their hearts?\nHis face is shining, in every one we meet.\nDo you know He's disguised as every man?",
