          "2. See the stone is rolled away, Alleluia.\nFrom the tomb where once He lay, Alleluia.\nHe has risen as He said, Alleluia.\nGlorious first born from the dead, Alleluia.",
          "3. Mary mother, greet your Son.\nradiant from His triumph won\nBy His cross you shared His pain.\nSo forever share His reign.",
          "4. Magdalen, wipe away your tears.\nHe has come who calms all fears.\nHear the master speak your name.\nTurn to Him with heart aflame.",
          "5. Shepherd seek the sheep that strayed.\nCome to contrite Peter's aid.\nStrengthen Him to be the rock.\nMake him shepherd of your flock.",
          "6. Seek not life within the tomb,\nChrist stands in the upper room!\nRisen glory He conceals,\nRisen body He reveals.",
