      Hymn(
        id: 138,
        number: "138",
        title: "Father I Place Into Your Hands",
        category: "Praise & Worship",
        stanzas: [
          "1. Father I place into your hands\nthe things I cannot do.\nFather I place into your hands the times\nthat I've been through.\nFather, I place into your hands\nthe way that I should go.\nFor I know I always can trust you.",
          "2. Father, I place into my hands\nmy friends and family.\nFather, I place into your hands\nthe things that trouble me\nFather, I place into your hands\nthe person I would be.\nFor I know I always can trust you.",
          "3. Father, we love to see your face,\nwe love to hear your voice.\nFather we love to sing your praise\nand in Your name rejoice.\nFather, we love to walk with you\nand in your presence rest.\nFor we know we always can trust you.",
          "4. Father, I want to be with you\nand do the things you do.\nFather, I want to speak the words\nthat you are speaking too.\nFather, I want to love the ones\nthat You will draw to You.\nFor I know that I am one with You.",
