          "2. Holy God by Your great might\nYou have restored to us our sight.\nBe not far from us we pray, when we're in need\nMay this bread our faith increase\nMake us instruments of peace.\nLet us help each other more by word and deed.",
          "3. Through the gift we bring to You\nwe present our pleading too\nand the homage You deserve from all Your sons.\nHelp us live our Christian call\nServe Christians' need in one and all.\nIn this Eucharist make all Your people one.",
