        number: "146",
        title: "Follow Christ",
        category: "Recessional",
        stanzas: [
          "1. Follow Christ and love the world as He did,\nwhen He walked upon the earth.\nLove each friend and enemy as He did.\nIn God's eyes we have equal worth.",
          "2. Follow Christ and serve the world as He did\nwhen He ministered, to everyone.\nServe each friend and enemy as He did\nso that the Father's will be done.",
          "3. He said love each other as I love you.'\nBy this all men will know you are mine.\nAs I served you so must you do.\nThis new commandment I assign.",
