        number: "148",
        title: "For Christ I Have Accepted",
        category: "Praise & Worship",
        refrain: "For Christ I have accepted,\nThe loss of everything,\nAnd I look on everything as so much Rubbish,\nonly I have Christ.\n(For if only I can have Christ, and be given a place in him) (2)",
        stanzas: [
          "1. I am no longer trying for\nPerfection by my own efforts.\nI want or by the perfection\nThat comes through faith in Christ.",
          "2. All I want is to know Jesus Christ\nAnd the power of the resurrection,\nAnd to share his sufferings reproducing\nThe pattern of his death.",
          "3. Not that I have become perfect yet\nI have not yet won, I'm still running,\nTrying, trying to capture the prize\nFor which Jesus captured me.",
