        number: "149",
        title: "For We Are One",
        category: "Offertory",
        refrain: "For we are one: in the love of Christ.\nIf we die with Him we will rise up to life.",
        stanzas: [
          "1. If in your life love abounds,\nseek no further, God is found.",
          "2. O when your brother cries out tears,\nshare with Him, His hopes and fears.",
          "3. O when great joy fills your heart\nopen up, a smile will start.",
