        stanzas: [
          "1. From the depths we cry to Thee,\nGod of sovereign majesty.\nHear-our chants and hymns of praise.\nBless our lent of forty days.",
          "2. Though our consciences proclaim,\nour transgressions and our shame.\nCleanse us, Lord, we humbly plead,\nfrom our sins of thought and deed.",
          "3. Lord, accept our Lenten fast.\nAnd forgive our sinful past\nthat we may partake with thee,\nin the Easter mystery.",
