        number: "156",
        title: "Give Thanks To Our God",
        category: "Praise & Worship",
        refrain: "Give thanks to our God Creator of Heaven and Earth.\nGive thanks to our God our Loving Father,",
        stanzas: [
          "1. He's King of all Kings, the Lord of the whole world.\nHe's King of all Kings: Emmanuel His Name.",
