        stanzas: [
          "1. God's spirit is in my heart.\nHe has called me and set me apart.\nThis is what I have to do, what I have to do.\nHe sent me to bring the good news to the poor\nTell prisoners that they are prisoners no more.\nTell blind people that they can see\nand set the down-trodden free.\nAnd go tell everyone the news\nthat the kingdom of God has come.\nAnd go tell everyone the news\nthat God's kingdom has come.",
