        number: "191",
        title: "Hail Virgin Most Holy",
        category: "Marian",
        refrain: "Ave, Ave Maria (2)",
        stanzas: [
          "1. Hail Virgin, most holy\nin mercy descending\nto save us poor sinners\nfrom sorrow unending.",
          "2. Our homes and our country\nwe Place in thy keeping\nto love and to serve thee\nGladness and weeping.",
        ],
      ),
      Hymn(
        id: 192,
        number: "192",
        title: "Hail Queen Of The Heavens",
        category: "Marian",
        stanzas: [
          "1. Hail Queen of the Heavens.\nHail mistress of earth,\nHail Virgin most pure.\nOf immaculate birth,\nClear star of the morning.\nIn beauty enshrined,\nO Mary make speed to help mankind,\nClear star of the morning in beauty enshrined.\nO Mary make speed to the help of mankind.",
          "2. Hail Mother most pure,\nHail Virgin renown'd\nHail Queen with the stars.\nAs diadem crown'd\nAbove all the angels, in glory untold,\nStanding next to the King in vesture of gold.\nAbove all the angels in glory untold,\nStanding next to the King in a vesture of gold.",
          "3. Queen of the Rosary.\nbe thou our salvation,\nour refuge in life\nand our true consolation.",
          "4. O Mother of mercy, O star of the sea,\nO hope of the guilty, O light of the grave,\nThro' thee may we come to the Heaven of rest\nAnd see Heaven's King in the courts of the blest.\nThro' thee may we come to the Heaven of rest\nAnd see Heaven's King in the courts of the blest.",
        ],
      ),
      Hymn(
        id: 193,
        number: "193",
        title: "Hallelujah What A Saviour",
        category: "Lent & Passion",
        stanzas: [
          "1. Man of sorrows what a name\nFor the Son of God who come\nRuined sinners to reclaim\nHallelujah what a saviour.",
          "2. Bearing shame and scoffing rude\nIn my place condemned He stood\nSealed my pardon with His blood.\nHallelujah what a saviour.",
          "3. Guilty vile and helpless we\nspotless Lamb of God was He\nFull atonement can it be?\nHallelujah what a saviour.",
          "4. Lifted up was He to die\nIt is finished was his cry\nNow in heav'n exulted high\nHallelujah what a saviour.",
          "5. When He comes our glorious king\nAll his ransomed home to bring\nThen anew this song we'll sing\nHallelujah what a saviour.",
        ],
      ),
      Hymn(
        id: 194,
        number: "194",
        title: "Happiness",
        category: "Praise & Worship",
        stanzas: [
          "1. Happiness is where you are\nand what you want to be.\nIf you look you're sure to find\nthe rainbow of your dreams.\nTomorrow is fuller than a thousand yesterdays,\nwith a vision of a new day in your heart.",
          "2. If the clouds should darken\nyou may turn your hopes on high.\nSorrow isn't meant to shake you\nfrom your way of life.\nJust keep on looking for the answer to it all\nwith a vision of a new day in your heart.",
          "3. Bitter sands may cross\nthe desert of your everyday.\nYour mind can blow away the fears\nthat always will be there.\nIf you can look beyond the neon and the glass\nyou will find a new day in your heart.",
        ],
      ),
      Hymn(
        id: 195,
        number: "195",
        title: "Happy Is The Man",
        category: "Praise & Worship",
        refrain: "Happy is the man who walk in the way of the Lord\nOur God and king\nBlessed is he and happy are they who Put their trust in him\nSing hosanna, alleluia\nYes sing hosanna, alleluia",
        stanzas: [
          "1. Blessed are they who know they are poor\nThe kingdom of the Lord is close at hand\nAnd blessed are the sorrowful, who know not where to go;\nSoon someone will understand.",
          "2. Blessed the gentle in spirit and heart;\nFor all the good of earth is theirs,\nAnd for those who hunger and thirst for what is right:\nSoon they'll have enough to share.",
          "3. Blessed are those who show kindness to all men;\nThe Lord we do the same for them.\nAnd happy is the man whose heart sees only good;\nSurely God will care for him.",
          "4. Blessed the man who strives to spread the peace\nThe peace that begin right here at home\nAnd soon all men who suffer to show us what is right\nWilt find that they are not alone.",
        ],
      ),
      Hymn(
        id: 196,
        number: "196",
        title: "Hark! Hark! My Soul",
        category: "Recessional",
        refrain: "Angels of Jesus, angels of light,\nSinging to welcome the pilgrims of the night.",
        stanzas: [
          "1. Hark! Hark! my soul angelic songs\nAre swelling, o'er earth's green\nFields, and ocean's wave beat shore:\nHow sweet the truth those blessed\nStrains are telling. Of that new life\nWhen sin shall be no more.",
          "2. Onward we go, for still we hear them\nSinging, come weary souls, for Jesus\nBids you come and through the dark\nIts echoes sweetly ringing.\nThe music of the gospel lead us home.",
          "3. Far, far away like bells at evening\nPealing the voice of Jesus sounds\nO'er land and sea, and laden souls, by\nThousand meekly stealing,\nkind Shepherd turn their weary steps to thee.",
          "4. Rest comes at length; though life be\nLong and dreary, the day must dawn and\nDarksome night be past; all journeys\nEnd in welcomes to the weary\nAnd heaven, the heart's true home\nWould come at last.",
          "5. Angels sing on, your faithful watches\nKeeping sing us sweet fragment of the Songs above;\nwhile we toil on, and\nSooth ourselves with weeping,\ntill life's long night shall break in endless love.",
        ],
      ),
      Hymn(
        id: 197,
        number: "197",
        title: "Hark, Hark, The Angels Singing",
        category: "Mass Parts",
        stanzas: [
          "1. Hark, hark, the Angels singing\nThrough all the heavenly coast,\n'Tis Holy, Holy, Holy,\nAnd thou Lord God of Host.\nThe starry skies around us,\nThe shinning earth below,\nThe greatness of thy glory,\nIn bright effulgence shows.",
          "2. Then, children join your voice\nAnd singing with one accord,\nThrice blessed he who cometh,\nIn thy name, mighty Lord,\nHosanna in the highest\nHosanna David's Son.\nThus may we sing in glory,\nForever round his throne.",
        ],
      ),
      Hymn(
        id: 198,
        number: "198",
        title: "Hark, The Herald",
        category: "Advent & Christmas",
        stanzas: [
          "1. Hark, the herald angels sing,\nGlory to the newborn King.\nPeace on earth and mercy mild,\nGod the sinners reconciled.\nJoyful all ye nations rise,\njoin the triumph of the skies\nwith the angelic host proclaim:\nGlory to the newborn King.\nHark the herald angels sing,\nGlory to the new-born king.",
          "2. Christ, by highest heaven adored,\nChrist, the everlasting Lord.\nLate in time behold Him come,\noffspring of a virgin's womb.\nVeiled in flesh the Godhead see,\nHail the incarnate Deity!\nPleased as man with man to dwell,\nJesus, our Emmanuel.",
        ],
      ),
      Hymn(
        id: 199,
        number: "199",
        title: "Hark! The Voice Of Jesus Calling",
        category: "Recessional",
        stanzas: [
          "1. Hark! the voice of Jesus calling\nWho will go and work today?\nFields are white and harvest waiting\nWho will bear the sheaves away?'\nLoud and strong the Master calleth.\nRich reward He offers thee.\nWho will answer gladly saying:\nHere am I, send me, send me.",
          "2. If you cannot speak like angels,\nif you cannot preach like Paul,\nyou can tell the love of Jesus.\nYou can say He died for all.",
          "3. If you cannot rouse the wicked\nwith judgments dread alarms.\nYou can lead the little children\nto the Saviour's waiting arms.",
          "4. If among the older people\nyou may not be apt to teach,\nsaid Christ our Shepherd. 'Feed my lambs',\nPlace the food within their reach.\nLet none hear you idly saying\n'There is nothing I can do.'\nWhile the souls of men are dying,\nand the Master calls for you.",
          "5. Take the task He gives us gladly.\nLet His work you pleasure be.\nAnswer quickly when He calleth.\n'Here am I. Send me, send me.'",
        ],
      ),
      Hymn(
        id: 200,
        number: "200",
        title: "Hark! 'Tis The Shepherd's Voice",
        category: "Praise & Worship",
        refrain: "Bring them in, bring them in.\nBring them in from the fields of sin.\nBring them in, bring them in.\nBring the wandering ones to Jesus.",
        stanzas: [
          "1. Hark 'tis the shepherd's voice\nI hear out in the desert dark and dreary.\nCalling the sheep who've gone astray\nfar from the shepherd's fold away.",
          "2. Who'll go and help this shepherd kind?\nHelp Him the wandering ones to find.\nWho'll bring the lost ones to the fold\nwhere they'll be sheltered from the cold?",
          "3. Out in the desert hear their cry.\nOut in the mountains wild and high\nhark! 'tis the Master speaks to thee.\nGo and find My sheep Where're they be.",
        ],
