      Hymn(
        id: 201,
        number: "201",
        title: "Have You Been To Jesus?",
        category: "Praise & Worship",
        refrain: "Are you washed in the Blood,\nin the soul-cleansing Blood of the Lamb?\nAre your garments spotless?\nAre they white as snow?\nAre you washed in the Blood of the Lamb?",
        stanzas: [
          "1. Have you been to Jesus for the cleansing power?\nAre you washed in the Blood of the Lamb?\nAre you fully trusting in His grace this hour?\nAre you washed in the Blood of the Lamb?",
          "2. Are you walking daily, by the Saviour's side?\nAre you washed in the Blood of the Lamb?\nDo you rest each moment in the Crucified\nAre you washed in the Blood of the Lamb?",
          "3. When the Bridegroom cometh will your robes be white?\nPure and white in the Blood of the Lamb?\nWith your soul be ready for the mansions bright\nand be washed in the blood of the Lamb?",
          "4. Lay aside the garments that are stained with sin\nand be washed in the blood of the Lamb.\nThere's a fountain flowing for the soul unclean\nand be washed in the blood of the Lamb.",
        ],
