        refrain: "Hear our entreaties, Lord\nAnd show Thy mercy.\nFor we are sinners before Thee.",
        stanzas: [
          "1. King high exalted and all the world's Redeemer,\nto Thee Thy children lift their eyes with weeping.\nChrist, we implore Thee, hear our supplication.",
          "2. Right hand of Godhead, Head-stone of the corner.\nPath of Salvation, Gate of Heaven's Kingdom,\ncleanse Thou Thy people Stained with much transgression.",
          "3. We Thy Eternal Majesty, entreating,\nmake lamentation in Thy Holy Hearing.\ngraciously grant Thou to our sins indulgence.",
          "4. Humbly confessing all our sins against Thee,\nall our misdoings hidden now no longer.\nThou our Redeemer, by Thy Love grant pardon.",
