      Hymn(
        id: 208,
        number: "208",
        title: "Help Lord The Souls",
        category: "Lent & Passion",
        stanzas: [
          "1. Help, Lord the souls That thou hast made,\nThe souls to Thee so dear,\nIn prison for the debt Unpaid\nof sin committed here.",
          "2. These holy souls they suffer on,\nresigned in heart and will,\nuntil Thy high behest is done.\nAnd justice has its fill.",
          "3. For daily fails for pardoned crime\nthy joy to undergo\nThe shadow of the Cross sublime,\nthe remnant of Thy woe.",
          "4. O by their patience of delay,\ntheir hope amid their pain,\ntheir sacred zeal to burn away,\ndisfigurement and stain.",
          "5. O by their fire of love,\nin a keenness than not less the flame\nO by their very helplessness,\nO by Thy own great Name.",
          "6. Good Jesus, help! sweet Jesus aid!\nthe souls to Thee most dear\nin prison for the debts unpaid\nof sins committed here\nof sin committed here.",
        ],
      ),
      Hymn(
        id: 209,
        number: "209",
        title: "Here In This Place",
        category: "Entrance",
        stanzas: [
          "1. Here in this place, new light is streaming.\nNow is the darkness vanished away,\nSee, in this place our fears and our dreamings,\nbrought here to you in the light of this day.\nGather us in the lost and forsaken.\nGather us in the blind and the lame.\nCall us now and we shall awaken,\nwe shall arise at the sound of Your name.",
          "2. We are the young - our lives are a mystery\nWe are the old - who yearn for Your face.\nWe have been sung throughout all of history,\ncalled to be tight to the whole human race.\nGather us in the rich and the haughty.\nGather us in the proud and the strong.\nGive us a heart so meek and so lowly.\nGive us the courage to enter the song.",
          "3. Here we will take the wine and the water.\nHere we will take the bread of new birth.\nHere we shall call your sons and your daughters,\ncall us anew to be salt of the earth.\nGive us to drink the wine of compassion.\nGive us to eat the bread that is You.\nNourish us well, and teach us to fashion,\nlives that are holy and hearts that are true.",
          "4. Not in the dark of buildings confine\nnot in some heaven, light years away,\nbut here in this Place, the new light is shining.\nNow is the Kingdom, now is the day.\nGather us in and hold us forever.\nGather us in and make us Your own.\nGather us in all peoples together,\nFire of love in our flesh and our bone.",
        ],
      ),
