        number: "215",
        title: "His Joy Is Bubbling In My Soul",
        category: "Praise & Worship",
        refrain: "Oh! Glory, glory, oh! Hallelujah\nI came to Jesus and He cleansed and Made me whole,\nnow I have found the, Only source of every blessing\nand his joy Is bubbling in my soul,\nsinging praises To the saviour way of life I now extol,\nfor I have found the source of every blessing.\nAnd his joy is bubbling in my soul.",
        stanzas: [
          "1. No time for singing sad old song\nAnd there is use for mourning\nAll earth's writing for I have power and victory,\nJoyous ecstasy that's what\nChrist my saviour gave to me.",
          "2. I know his grace is all I need\nI'm sure that three every trials\nHe will lead his promised grace\nThat's sufficient for the journey here.\nI can Feel the spirit always near.",
