        number: "219",
        title: "Holy! Holy! Holy!",
        category: "Praise & Worship",
        stanzas: [
          "1. Holy, holy, holy, holy, holy, holy Lord God Almighty,\nAnd we lift our hearts before You as a token of our love\nHoly, holy, holy, holy!",
          "2. (Gracious Father, Gracious Father,\nwe're so glad to be Your children\nAnd we lift our hearts before You as a token of our love.\nGracious Father, Gracious Father.",
          "3. Precious Jesus, Precious Jesus,\nwe're so glad that you redeemed us\nAnd we lift our hearts before You as a token of our love\nPrecious Jesus, Precious Jesus.",
