        number: "223",
        title: "Holy Queen We Bend",
        category: "Marian",
        stanzas: [
          "1. Holy Queen! we bend before thee,\nqueen of purity divine.\nMake us love thee, we implore thee.\nMake us truly to be thine.",
          "2. Teach, oh teach us Holy Mother,\nhow to conquer ev'ry sin.\nhow to love and help each other,\nhow the prize of life to win.",
