      Hymn(
        id: 225,
        number: "225",
        title: "How Can I Forget?",
        category: "Lent & Passion",
        refrain: "Giving you My life and love, promised you My heart.\nNearer to My heart, O Israel, why have you pierced my heart?\nWhy have you gone? See your love is melting like the dew drop.\nDried and fallow lies your ground.\nWithered is your heart. How can I forget that I have made you?",
        stanzas: [
          "1. How can I forget and leave my loved ones?\nHow can I forget my love? Wounded is my heart.\nHow can I forget that I'm compassion?\nHow can I depart from her?",
          "2. How can I forget that you do need me?\nEven though you leave me I shall woo your heart\nO Israel, why have you gone so far in search of love?\nCan't you feel the coolness of My shadow? water when you are thirsting?\nO Israel, how can I see rain when you are dry? keep you and make you Mine?\nI will heal the wounds inflicted on you.\nComfort I will bring to you, tender is My heart.",
          "3. I shall call until My heart wilt find you.\nLead you to My wilderness, speaking to your heart.\nI shall give you back your fruit and vineyard.\nI shall give you hope and love as when you were Mine.\nWill you be free? Will you return to Me and be My bride?\nI shall make you Mine, My love forever.\nGive me back your faithful love. Give me back your heart.\nO Israel, will you return to Me and be my bride?",
        ],
      ),
      Hymn(
        id: 226,
        number: "226",
        title: "How Great Is Our God!",
        category: "Praise & Worship",
