          "2. He sent His Son, Jesus, to set us free.\nAnd He said 'I'll never leave you; put your trust in Me'.",
          "3. He gave us His Spirit. And now we can see,\nAnd He said 'I'll never leave you; put your trust in Me'.",
        ],
      ),
      Hymn(
