        number: "227",
        title: "How Great Is Your Name",
        category: "Praise & Worship",
        refrain: "How great is your name, O Lord our God\nThrough all the earth.",
        stanzas: [
          "1. Your majesty is praised above the heavens,\non the lips of children and of babes.\nYou have found praise to foil Your enemy,\nto silence the foe and the rebel.",
