      Hymn(
        id: 230,
        number: "230",
        title: "How Many Times...?",
        category: "Praise & Worship",
        refrain: "The answer, My friend,\nis when you see the truth that I am in the poor and least of all.\nis when you see the truth that I am in the poor and least of all.",
        stanzas: [
          "1. How many times must My people make war\nbefore they know they are one?\nHow many times must their blood be shed\nbefore they know that its time?\nHow many times will they break My bread\nbefore you give Me to eat?",
          "2. How many times must the sick look up\nand find that there's no one to care?\nHow many times must I stumble and fall\nbefore you offer your hand?\nHow many times must I reach through these bars\nbefore you give me the keys?",
        ],
      ),
      Hymn(
        id: 231,
        number: "231",
        title: "Humbly We Adore Thee",
        category: "Adoration & Eucharist",
        stanzas: [
          "1. Humbly we adore Thee, Christ, Redeemer King.\nThou art Lord of heaven, Thou to whom we sing.\nGod, the Mighty, bearing gifts of grace,\nSon of Adam still Thou art Saviour to our race.",
          "2. Jesus Lord, we thank Thee for this wondrous Bread.\nIn our land Thou dwellest. By Thee we are fed.\nWe Who share this mystery in Thee are made one.\nEvery act we offer Thee, in Thy name is done.",
          "3. Thou Who died to save us livest as our Light.\nThough our eyes are blinded yet our faith gives sight.\nChrist do Thou be merciful, Lamb for sinners slain.\nWe in grief confess our guilt. Cleanse our souls of stain.",
          "4. Christ, our God and Brother, hear our humble plea.\nBy this holy banquet keep us joined to Thee.\nMake us one in loving Thee, one in mind and heart\ntill in heaven wear never more to part.",
          "5. Hail, Thou Word Incarnate, born from Mary's womb!\nHail, Thou strength immortal risen from the tomb.\nShare with us Thy victory, Saviour ever blest,\nlive more fully in our hearts.\nBe our constant Guest.",
        ],
      ),
      Hymn(
        id: 232,
        number: "232",
        title: "I Am Coming",
        category: "Entrance",
        stanzas: [
          "1. I am coming to Your altar,\nOh God, my Saviour, my Joy and my Love.",
          "2. How lovely is Your dwelling place,\nLord God of hosts! My soul is longing\nfor the courts of the Lord.",
          "3. How happy are they who dwell in Your house, O Lord!\nForever and ever singing Your praise.",
          "4. Close by Your altar, the sparrow finds a home.\nThe swallow finds here a nest for her brood.",
