        number: "233",
        title: "I Am So Glad",
        category: "Praise & Worship",
        refrain: "I am so glad that Jesus loves me.\nJesus loves me, Jesus loves me.\nI am so glad that Jesus loves me.\nJesus loves you and me.",
        stanzas: [
