      Hymn(
        id: 238,
        number: "238",
        title: "I Cannot Come",
        category: "Offertory",
        refrain: "I cannot come to the banquet. Don't trouble me now.\nI have married a wife\nI have brought a new cow.\nI have fields and commitments that cost a pretty sum.\nPray hold me excused, I cannot come.",
        stanzas: [
          "1. A certain man held a feast on his fine estate in town.\nHe laid a festive table. He wore a wedding gown.\nHe sent out invitations to his neighbours far and wide.\nBut when the meal was ready, each of them replied.",
          "2. The master rose up in anger, called his servants by name.\nSaid 'go into the town, fetch the blind and the lame;\nfetch the peasant and the pauper.\nFor this I have willed: my banquet must be crowded,\nand my table must be filled.'",
          "3. When all the poor had assembled there was still room to spare.\nSo the master demanded: Go search everywhere,\nto the highways and the byways\nand force them to come in.\nMy table must be filled before the banquet can begin.",
        ],
