        number: "240",
        title: "I Danced In The Morning",
        category: "Easter & Resurrection",
        refrain: "Dance then wherever you may be.\nI am the Lord of the dance' said He\nAnd I lead you all wherever you may be.\nand I lead you all in the dance' said He.",
        stanzas: [
          "1. I danced in the morning when the world was begun.\nAnd I danced in the moon and the stars and the sun.\nAnd I came down from heaven and I danced on the earth.\nAt Bethlehem I had My birth.",
          "2. I danced for the Scribe and the Pharisee.\nBut they would not dance and they wouldn't follow me.\nI danced for the fishermen, for James and John.\nThey came with me and the dance went on.",
          "3. I danced on the Sabbath and I cured the lame.\nThe holy people said it was a shame.\nThey whipped and they stripped and they hung Me on high.\nAnd they left Me there on the Cross to die.",
          "4. I danced on a Friday when the sun turned black.\nIt's hard to dance with the devil on your back.\nThey buried My body and they taught I had gone.\nBut I am the dance and I still go on.",
          "5. They cut Me down and I leapt up high.\nI am the life that will never never die.\nI'll live in you if you live in Me.\n'I am the Lord of the dance' said he.",
