      ),
      Hymn(
        id: 246,
        number: "246",
        title: "I Have Carried You",
        category: "Praise & Worship",
        refrain: "I have carried you on eagles' wings\nI will care for you in all your years.",
        stanzas: [
          "1. My heart is full of peace. You have been within my life.\nYour guiding hands have always covered me.\nI am full of confidence in you.",
          "2. My soul is like a child, cradled safe within your arms.\nYou have carried me across all my years\nleading me through sorrows and through joys.",
          "3. Never need I be afraid\nno matter how uncertain things maybe\nSometimes through me, sometimes in spite of me,\nYou seem to find Your purpose in my life.",
          "4. I know failure in my life, the weakness so central to my heart:\nWhen I have strayed or fallen in my life,\nYou gently set me on my feet again.",
          "5. You have bridged the flowing streams.\nAnd moved aside the mountain fails.\nYou have kept me through the streams past:\nI know that You secure and guide me still.",
