      ),
      Hymn(
        id: 248,
        number: "248",
        title: "I'll Sing A Hymn To Mary",
        category: "Marian",
        stanzas: [
          "1. I'll sing a hymn to Mary, the Mother of my God,\nthe virgin of all virgins of David's royal blood,\nO teach me, holy Mary, a loving song to frame.\nWhen wicked men blaspheme thee,\nI'll love and bless Thy name.",
          "2. O noble Tower of David, of gold and ivory,\nthe Ark of God's own promise, the Gate of Heaven to me.\nTo live and not to love thee would fill my soul with shame.\nWhen wicked men blaspheme thee\nI'll love and bless Thy name.",
          "3. The saints are high in glory with golden crowns so bright.\nBut brighter far is Mary upon her throne of light.\nof that which God did give thee let mortal ne'er disclaim.\nWhen wicked men blaspheme thee I'll love and bless, Thy name.",
          "4. But in the crown of Mary, there lies a wondrous gem.\nAs queen of all the angels which Mary shares with them.\nNo sin hath e'er defiled thee\nSo doth our faith proclaim.\nWhen wicked men blaspheme thee I'll love and bless Thy name.",
          "5. We pray for all sinners and souls that now\nstray from Jesus and Mary in heresy's way.",
          "6. In grief and temptation, in joy or in pain,\nwe'll seek thee, our mother, nor seek thee in vain.",
          "7. O bless us, dear lady, with Blessings from heaven.\nAnd to our petitions let answer be given.",
          "8. Now to God be all glory and worship for aye.\nAnd to God's virgin mother an endless Ave.",
        ],
      ),
      Hymn(
        id: 249,
        number: "249",
        title: "Immaculate Mary",
        category: "Marian",
        refrain: "Ave, Ave Maria. Ave, Ave Maria.",
        stanzas: [
          "1. Immaculate Mary! our hearts are on fire.\nThat title so wondrous fills all our desire.",
          "2. We pray for God's glory. May His kingdom come.\nWe pray for His vicar our Father and Rome.",
          "3. We Pray for our mother, the Church upon earth.\nAnd bless, sweetest Lady the end of our birth.",
        ],
      ),
      Hymn(
        id: 250,
        number: "250",
        title: "Immortal Invisible God",
        category: "Praise & Worship",
        stanzas: [
          "1. Immortal invisible God only wise\nIn light in accessible hid from our eyes\nMost blessed, most glorious, the Ancient of days\nAlmighty, victorious, thy great name we praise.",
          "2. Unresting unlasting and silent as light\nNor waiting nor wasting, thou rulest in might\nThy justice like mountain high soaring above\nThy cloud which are fountains of goodness and love.",
          "3. To all life thou givest, to both great and small in all\nlife thou livest, the true life of all\nWe blossom and flourish as leaves on the tree\nand wither and perish but naught changeth thee.",
          "4. Great father of glory, pure father of light\nThine angels adore thee all vailing their sight\nAll loud we would render, O help us to see\nTis only the splendor of light hideth thee.",
        ],
      ),
      Hymn(
        id: 251,
        number: "251",
        title: "I'm Walking On My Way",
        category: "Entrance",
        refrain: "So let's all join hands and praise our God.\nYes, love our Lord, Lord, Lord.\nSo let's all join hands and praise our God.\nYes, love our Lord, Lord, Lord.\nGo to our Lord's house.\nSo let's all join hands and praise our God.\nYes, love our Lord who's waiting patiently.",
        stanzas: [
          "1. I'm walking on my way to the Lord\nto my Lord, Lord, Lord to my Lord's house\nI'm walking on my way to the Lord, to my Lord\nwho's waiting there for me.",
          "2. I'm singing on my way to the Lord\nto my Lord, Lord, Lord to my Lord's house\nI'm singing on my way to the Lord, to my Lord\nwho's waiting there for me.",
          "3. I'm clapping on my way to the Lord\nto my Lord, Lord, Lord to my Lord's house\nI'm clapping on my way to the Lord, to my Lord\nwho's waiting there for me.",
        ],
