      Hymn(
        id: 252,
        number: "252",
        title: "In Bread We Bring You Lord",
        category: "Offertory",
        stanzas: [
          "1. In bread we bring You, Lord, our body's labour.\nIn wine we offer You our spirit's grief.\nWe do not ask You, Lord, who is my neighbour?\nbut stand united now, in one belief.\nOh we have gladly heard Your Word, Your Holy Word.\nAnd now in answer Lord, our gifts we bring.\nOur selfish hearts make true. Our falling faith renew.\nOur lives belong to You. Our Lord and King.",
          "2. The bread we offer You is blessed and broken.\nAnd it becomes for us our spirit's food.\nOver the cup we bring Your Word is spoken.\nMake it Your gift to us, your healing blood.\nTake all that daily toil plants in our hearts poor soil.\nTake all we start and spoil, each hopeful dream,\nthe chances we have missed,\nthe graces we resist,\nLord, in Thy Eucharist, take and redeem.",
        ],
      ),
      Hymn(
        id: 253,
        number: "253",
        title: "In Christ There Is No East Or West",
        category: "Praise & Worship",
        stanzas: [
          "1. In Christ there is no East or West\nIn Him no South or North.\nbut one great fellowship of love\nthroughout the whole wide earth.",
          "2. In Him shall true hearts everywhere\ntheir high communion find.\nHis service is the golden chord\nclose binding all mankind.",
          "3. Join hands then brothers of the faith,\nwhate'er your race may be!\nWho serves My Father as a son\nis surely kin to me.",
          "4. In Christ now meet both East and West.\nin Him meet South and North.\nAll Christly souls are one in\nthroughout the whole wide earth.",
        ],
      ),
      Hymn(
        id: 254,
        number: "254",
        title: "I Need Thee Every Hour",
        category: "Praise & Worship",
        refrain: "I need Thee, oh, I need Thee,\nEvery hour I need Thee.\nOh, bless me now, my Saviour\nI come to Thee.",
        stanzas: [
          "1. I need Thee every hour, most gracious Lord.\nNo tender voice like Thine can peace afford.",
          "2. I need Thee every hour. Stay Thou near me.\nTemptations lose their power When Thou art near.",
          "3. I need Thee every hour in joy or pain.\nCome quickly and abide or live in vain.",
          "4. I need Thee every hour. Teach me Thy will.\nAnd Thy rich promises in me fulfill.",
          "5. I need Thee every hour, Most Holy One.\nOh make me Thine indeed, Thou blessed Son.",
          "6. I'll need Thee, sweetest Jesus\nwhen death's dread hour draws nigh.\nTo hide me in Thy Sacred Heart\ntill wafted safe on high.",
        ],
      ),
      Hymn(
        id: 255,
        number: "255",
        title: "I Need Thee, Precious Jesus",
        category: "Adoration & Eucharist",
        stanzas: [
          "1. I need Thee, precious Jesus,\nI need a friend like Thee,\na friend to soothe and sympathize\na friend to care for me.",
          "2. I need Thy heart, sweet Jesus,\nto still each anxious care,\nI long to tell my every want,\nand all my sorrows share.",
          "3. I need Thee, sweetest Jesus,\nin Thy sacrament of Love\nto nourish this poor soul of mine\nwith the treasures of Thy love.",
          "4. I need Thy Blood, sweet Jesus\nto wash each sinful stain\nto cleanse this sinful soul of mine\nand make it pure again.",
          "5. I need thy wounds, sweet Jesus\nto fly from perils near,\nto shelter in these hallowed clefts,\nfrom every doubt and fear.",
        ],
      ),
      Hymn(
        id: 256,
        number: "256",
        title: "In Thanksgiving And Love",
        category: "Offertory",
        refrain: "O yes in the presence of the Lord\nI will bring my gifts in thanksgiving and love.\nThere is joy in my heart it is flowing like a river\nI will praise the Lord, in thanksgiving and love.",
        stanzas: [
          "1. God our Father, everlasting King\nPlease accept the gifts we offer\nIn thanksgiving and love\nTake the bread upon your altar\nAnd the wine in the Chalice\nIn thanksgiving and love.",
          "2. With thankful hearts and joyful songs\nWe approach your holy altar\nIn thanksgiving and love\nBearing gifts of your creation\nWe return what you have given\nIn thanksgiving and love.",
          "3. To You Father, now we offer\nWith the Host and with the Chalice\nIn thanksgiving and love\nAll we have and all our being\nIn the sacrifice most holy\nIn thanksgiving and love.",
        ],
      ),
      Hymn(
        id: 257,
        number: "257",
        title: "In The Bleak Mid-Winter",
        category: "Advent & Christmas",
        stanzas: [
          "1. In the bleak mid-winter frosty wind made moan,\nEarth stood hard as iron, Water like a stone;\nsnow had fallen, snow on snow\nSnow on snow in the bleak mid winter long ago.",
          "2. Angels and archangels May have gathered there,\nCherubim and Seraphim Thronged the air\nbut his mother only in her maiden bliss\nWorshiped the beloved With a kiss.",
          "3. What can I give him, Poor as I am?\nIf I were a shepherd I would bring a lamb\nIf I were a wise man I would do my part\nYet what I can I give him Give my heart.",
        ],
      ),
      Hymn(
        id: 258,
        number: "258",
        title: "In The Morning",
        category: "Entrance",
        refrain: "it is Your love ever wakens me with visions and with hope.\nIn Your love I am free to live with courage.\nAnd tomorrow will be different because Your loving hand\nwill lead me to a home that is gift, for all I love.",
        stanzas: [
          "1. In the morning as I listen\nto a new day's life within,\nhow I wonder what will carry me beyond!\nAll the fears, the insecurities,\nthe work awaiting me in the journey\nto the evening of my life.",
          "2. I won't listen to those voices\nof the present and the past,\nthat would rather I'd be held in captive fear.\nAs I struggle for a freedom\nand an authenticity with Your\npresence in my life it is to be.",
          "3. As I walk among the faces\nof this earth it's clear to me,\nhow profound the bond of our humanity.\nI have known compassion,\nfriendship and its healing energy.\nLets invite each other to be truly free.",
        ],
      ),
      Hymn(
        id: 259,
        number: "259",
        title: "In The Morning The Sun",
        category: "Entrance",
        refrain: "Arise come sing in the morning\nPraise the Lord every day.\nLive His love every moment of our lives.\nSay 'Yes' in ev'ry way.",
        stanzas: [
          "1. In the morning the sun will rise\nand shed its warmth upon the earth.\nIt is the beginning of a brighter day,\na time for our rebirth.",
          "2. Through the life of Jesus the Son,\nwe learn to live, grow and love;\nto see the goodness in each and every day\nthat comes from God above.",
          "3. In this banquet of love that we share.\nWe affirm the goodness of life.\nWe promise to work For a better world,\nto free it from hate and strife.",
        ],
      ),
      Hymn(
        id: 260,
        number: "260",
        title: "Instrument Of Peace",
        category: "Offertory",
        refrain: "Lord make us instrument your peace\nWhere there is hatred let your love increase\nLord make us instrument, your peace\nWalls of pride shall cease\nWhen we are your instrument of peace.",
        stanzas: [
          "1. Where there is hatred We will show His love\nWhere there is lying We will never judge\nWhere there is striving We will speak His peace\nTo the people crying for release\nWe will be His instrument of peace.",
          "2. Where there is blindness We will pray for sight\nWhere there is darkness we Will shine his light\nWhere there is sadness We will bear his grief\nFor the people sighing for relief,\nWe will be his instrument peace.",
        ],
      ),
      Hymn(
        id: 261,
        number: "261",
        title: "Isn't The Love Of Jesus",
        category: "Praise & Worship",
        stanzas: [
          "1. isn't the love of Jesus simply wonderful,\nwonderful, wonderful?\nIsn't the love of Jesus simply wonderful.\npraise His Holy Name.",
          "2. So high, you can't get over it,\nso low, you can't get under it,\nso wide, you can't get around it,\nlove, wonderful love.",
        ],
      ),
      Hymn(
        id: 262,
        number: "262",
        title: "I Surrender All",
        category: "Offertory",
        refrain: "I surrender all, I surrender all\nAll to Thee my Blessed Saviour,\nI surrender all.",
        stanzas: [
          "1. All to Jesus I surrender.\nAll to Him I freely give\nI will ever love and trust Him.\nIn His Presence daily live.",
          "2. All to Jesus I surrender,\nHumbly at His feet I bow.\nWorldly pleasures all forsaken,\ntake me Jesus, take me now.",
          "3. All to Jesus I surrender\nNow I feel The sacred flame.\nO the joy of full salvation.\nGlory, glory to His Name.",
        ],
      ),
      Hymn(
        id: 263,
        number: "263",
        title: "It Came Upon The Midnight Clear",
        category: "Advent & Christmas",
        stanzas: [
          "1. It came upon the midnight clear\nThat glorious song of old\nFrom angels bending near the earth\nTo touch their harps of gold\nPeace on the earth, Good-will to men.\nFrom heaven's all gracious king!\nThe world in solemn stillness lay\nTo hear the angels sing.",
          "2. Still through the cloven skies they come,\nwith peaceful wings unfurled\nand still their heavenly music flats\no'er all the weary world\nabove its sad and lowly plains\nthey bend on hovering wing\nand ever o'er its babe!\nsounds the blessed angels sing.",
          "3. Yet with the woes of sin and strife\nthe world has suffered long\nbeneath the angels strain have rolled\ntwo thousand years of wrong\nand men at war with men hear not\nthe love-song which they bring\nO hush the noise, ye men of strife\nAnd hear the angels sing!",
          "4. And ye beneath life's crushing load,\nWhose forms are bending low,\nWho toil along the climbing way\nWith painful steps and slow,\nLook now! For glad and golden hours\nCome swiftly on the wing:\nO rest beside the weary road\nAnd hear the angels sing.",
          "5. For lo! The days are hastening on,\nBy prophet bards foretold,\nWhen with the ever-circling years\nComes round the age of gold;\nWhen peace shall over all the earth\nIts ancient splendours fling,\nAnd the whole world give back the song\nWhich now the angels sing.",
        ],
      ),
      Hymn(
        id: 264,
        number: "264",
        title: "I, The Lord Of Sea And Sky",
        category: "Consecration & Dedication",
        refrain: "Here I am, Lord, is it I, Lord?\nI have heard You calling in the night.\nI will go, Lord, if You lead me.\nI will hold Your people in my heart.",
        stanzas: [
          "1. I, the Lord of sea and sky,\nI have heard My people cry.\nAll who dwell in dark and sin\nMy hand will save.\nI who made the stars of night,\nI will make their darkness bright.\nWho will bear My light to them?\nWhom shall I send?",
          "2. I, the Lord of snow and rain,\nI have borne My people's pain.\nI have wept for love of them,\nThey turn away.\nI will break their hearts of stone,\nGive them hearts for love alone.\nI will speak My Word to them,\nWhom shall I send?",
          "3. I, the Lord of wind and flame,\nI will send the poor and lame.\nI will set a feast for them,\nMy hand will save.\nFinest bread I will provide\nTill their hearts be satisfied.\nI will give My life to them.\nWhom shall I send?",
        ],
      ),
      Hymn(
        id: 265,
        number: "265",
        title: "It May Be Your Last Call",
        category: "Lent & Passion",
        refrain: "For it may be, it may be your last call from Him,\nIt may be your own last call,\nYour own last call that comes from Him.",
        stanzas: [
          "1. Jesus is calling you to give Him your heart,\nO come to Him, He is our Saviour,\nO listen to His voice, the voice of redemption,\nO come and give Him your heart.",
          "2. O what will you gain if you win the whole world,\nAnd lose your soul to hell fire;\nO confess your sins and come back to Him,\nO come and give Him your heart.",
          "3. The time is so short, repent from your sins\nFor Jesus is calling that you may come to Him\nO listen to His voice, the voice of redemption,\nO come and give Him your heart.",
        ],
      ),
      Hymn(
        id: 266,
        number: "266",
        title: "It Only Takes A Spark",
        category: "Praise & Worship",
        stanzas: [
          "1. It only takes a spark to get the fire going,\nAnd soon all those around will light up its glowing.\nThat's how it is with God's love,\nOnce you've experienced it\nYou spread His love to everyone,\nYou want to pass it on.",
          "2. What a wondrous time we're in when all the trees are budding!\nThe birds begin to sing, the flowers start their blooming.\nThat's how it is with God's love,\nOnce you have experienced it,\nYou want to laugh, you want to sing,\nYou want to pass it on.",
          "3. I wish for you my friend this happiness that I've found.\nYou can depend on Him, it matters not where you are bound.\nI'll shout it from the mountain top:\n'Praise God!' I want to pass it on.\nWe'll shout it from the mountain top:\n'Praise God!' We want the world to know\nThe Lord of love has come to us,\nWe want to pass it on.",
        ],
      ),
      Hymn(
        id: 267,
        number: "267",
        title: "I Trusted Even When I Said",
        category: "Offertory",
        refrain: "How can I repay the Lord for His goodness to me?\nI will raise the cup of salvation,\nWill call on God's Name.",
        stanzas: [
          "1. I trusted even when I said:\n'I am sorely afflicted,'\nAnd when I said in my alarm:\n'No man can be trusted.'",
          "2. My vows to the Lord I will fulfill\nBefore all His people.\nO precious in the eyes of the Lord\nIs the death of His faithful.",
          "3. Your servant Lord, Your servant am I,\nYou have loosened my bonds.\nA thanksgiving sacrifice I make;\nWill call on the Lord's name.",
          "4. My vows to the Lord I will fulfill\nBefore all His people,\nIn the courts of the house of the Lord,\nIn your midst, O Jerusalem.",
        ],
      ),
      Hymn(
        id: 268,
        number: "268",
        title: "It's A Long Road",
        category: "Recessional",
        refrain: "It's a long road to freedom a winding steep and high.\nBut when you walk in love with the wind on your wing,\nAnd cover the earth with the song you sing:\nThe miles fly by.",
        stanzas: [
          "1. I walked one morning by the sea,\nAnd all the waves reached out to me.\nI took their tears, then let them be.",
          "2. I walked one morning at the dawn\nWhen bits of night still lingered on.\nI sought my star but it was gone.",
          "3. I walked one morning with a friend\nAnd prayed the day would never end.\nThe years have flown so why pretend?",
          "4. I walked one morning with my King\nAnd all my winter turned to spring.\nYet ev'ry moment held its sting.",
        ],
      ),
      Hymn(
        id: 269,
        number: "269",
        title: "It's A World Of Laughter",
        category: "Recessional",
        refrain: "It's a small world after all.\nIt's a small world after all.\nIt's a small world after all.\nIt's a small, small world after all.",
        stanzas: [
          "1. It's a world of laughter, a world of tears,\nIt's a world of hope and a world of fears.\nThere's so much that we share\nThat it's time we're aware\nIt's a small world after all.",
          "2. There is just one moon and one golden sun,\nAnd a smile means friendship to everyone.\nThough the mountains divide\nAnd the oceans are wide,\nIt's a small world after all.",
          "3. Now we thank Our Lord for His goodness to us,\nThe things He made and the life He gave.\nThere's so much that we share\nThat it's time we're aware:\nIt's a small world after all.",
        ],
