      Hymn(
        id: 270,
        number: "270",
        title: "It's Not An Easy Road",
        category: "Praise & Worship",
        refrain: "No, no, it's not an easy road,\nNo, no, it's not an easy road.\nBut Jesus walks beside me and brightens the journey\nAnd lightens every heavy load.",
        stanzas: [
          "1. It's not an easy road, we are travelling to heaven,\nFor many are the thorns on the way.\nIt's not an easy road, but the Saviour is with us,\nHis Presence gives us joy every day.",
          "2. Though we are often lonesome and weary from travel,\nThough we are often bowed down with care,\nA better day is coming when home is the glory,\nWe rest in perfect peace over there.",
          "3. It's not an easy road, there are trials and troubles,\nFor many are the dangers we meet.\nBut Jesus guides and keeps us, that nothing can harm us,\nAnd smoothes the rough path for our own feet.",
        ],
      ),
      Hymn(
        id: 271,
        number: "271",
        title: "It's Pay Back Time",
        category: "Offertory",
        refrain: "Father, to You we offer, (Oh my Jesus)\nTo You these gifts we bring;\nHoly Ghost, accept this offering\nWhich we offer up to You.",
        stanzas: [
          "1. I believe that Jesus died for me,\nA sacrifice beyond my understanding\nOffering Himself in place of me;\nOh how can I repay the Lord?",
          "2. I believe all that the scripture said\nAbout the love beyond my understanding,\nForgiveness beyond comprehension\nOh how can I repay the Lord?",
          "3. Teach me Lord to love You as I ought,\nOh teach me Lord to love You all my life time,\nSpreading love where'er I find myself\nOh how can I repay the Lord?",
