      Hymn(
        id: 272,
        number: "272",
        title: "I Will Never Forget You",
        category: "Communion",
        stanzas: [
          "1. I will never forget you, My people,\nI have carved you on the palm of My hand,\nI will never forget You,\nI will not leave you orphaned,\nI will never forget My own.",
          "2. Does a mother forget her baby?\nOr a woman the child within her womb?\nYet, even if these forget, Yes, even if these forget,\nI will never forget My own.",
        ],
      ),
      Hymn(
        id: 273,
        number: "273",
        title: "Jerusalem, My Happy Home",
        category: "Recessional",
        stanzas: [
          "1. Jerusalem, my happy home,\nWhen shall I come to thee?\nWhen shall my sorrows have an end?\nThy joys when shall I see?",
          "2. O happy harbour of the saints!\nO sweet and pleasant soil!\nIn thee no sorrow may be found,\nNo grief, no care, no toil.",
          "3. In thee no sickness may be seen,\nNo hurt, no ache, no sore!\nIn thee there is no dread of death\nBut life forever more.",
          "4. No dampish mist is seen in thee,\nNo cold nor darksome night.\nThere every soul shines as the sun,\nThere God Himself gives light.",
          "5. There lust and lure cannot dwell,\nThere envy bears no sway.\nThere is no hunger, heat or cold,\nBut pleasure everywhere.",
          "6. Jerusalem, Jerusalem,\nGod grant I once may see\nThy endless joys, and of the same\nPartaker aye may be!",
        ],
      ),
      Hymn(
        id: 274,
        number: "274",
        title: "Jesus Dulcis Memoria",
        category: "Latin Hymns",
        stanzas: [
          "1. Jesus dulcis memoria\nDans vera cordis gaudia\nSed super mel et Omnia\nEjus dulcis praesentia.",
          "2. Nil cogitatur dulcius\nNil auditur jucundius\nNil cogitatur dulcius\nQuam Jesu dei filius.",
          "3. Jesu, spes paenitentibus\nQuam pius et petentibus\nQuam bonus te quaerentibus\nSed quid invenientibus",
          "4. Nec lingua valet dicere\nNec littera exprimere\nExpertus potest credere\nQuid sit Jesum diligere.",
          "5. Sis Jesu, nostrum gaudium\nQui es futurus praemium\nSit nostra in te Gloria\nPer cuncta semper saecula\nAmen.",
        ],
      ),
      Hymn(
        id: 275,
        number: "275",
        title: "Jesus For Me",
        category: "Praise & Worship",
        refrain: "Jesus for me. Jesus for me\nAll the time, everywhere.\nJesus for me.",
        stanzas: [
          "1. Jesus my Saviour, is all things to me.\nO what a wonderful Saviour is He!\nGuiding, protecting o'er life's troubled sea.\nMighty deliverer, Jesus for me.",
          "2. Jesus in sickness, and Jesus in health;\nJesus in poverty, comfort or wealth\nSunshine or tempest, whatever it be.\nHe is my safety, Jesus for me.",
          "3. He is my refuge, my rock and my tower.\nHe is my treasure, my strength and my power.\nLife everlasting, my delight is He\nBlessed Redeemer, Jesus for me.",
          "4. He is my prophet, my priest and my King.\nHe is my bread of life, fountain and spring.\nBright sun of right\nDaystar is He.\nHorn of salvation, Jesus for me.",
        ],
      ),
      Hymn(
        id: 276,
        number: "276",
        title: "Jesus Gentlest Saviour",
        category: "Communion",
        stanzas: [
          "1. Jesus gentlest saviour, God of might and power,\nThou Thyself art dwelling, in us at this hour.",
          "2. Nature cannot hold Thee, Heaven is all too straight\nFor Thine endless glory and Thy royal state.",
          "3. Yet the hearts of children hold what worlds cannot\nAnd the God of wonders loves the lowly spot.",
          "4. Jesus, gentlest Saviour, Thou art in us now\nFill us full of goodness till our hearts o'erflow.",
          "5. Pray the prayer within us that to heaven shall rise\nSing the song that angels sing above the skies.",
          "6. Multiply our graces, chiefly love and fear,\nAnd dear Lord the chiefest, grace to persevere.",
        ],
      ),
      Hymn(
        id: 277,
        number: "277",
        title: "Jesus Is A Friend",
        category: "Praise & Worship",
        stanzas: [
          "1. Jesus is a friend of mine\nPraise Him, (2)\nPraise Him, Praise Him.\nJesus is a friend of mine.\nPraise Him.",
          "2. Jesus died to set me free.\nPraise Him, (2)\nPraise Him, praise Him.\nJesus died to set me free.\nPraise Him.",
          "3. He gave us the victory.\nPraise Him, (2)\nPraise Him, praise Him.\nJesus gave us the victory.\nPraise Him.",
          "4. Jesus is the King of Kings.\nPraise Him, (2)\nPraise Him, praise Him.\nJesus is the King of Kings,\nPraise Him.",
