        ],
      ),
      Hymn(
        id: 279,
        number: "279",
        title: "Jesus Is God",
        category: "Praise & Worship",
        stanzas: [
          "1. Jesus is God!\nJesus is God! The glorious band of golden angels sing,\nSongs of adoring praise to Him\nTheir Master and their King.\nHe was true God in Bethlehem's crib,\nCalvary's cross true God,\nHe who in heaven eternal reigned,\nIn time on earth abode.",
          "2. Jesus is God! Let sorrows come and pain and every ill.\nAll are worthwhile for all are means His glory to fulfill.\nWorthwhile a thousand years of life,\nTo speak one little word,\nIf by our credo we might own,\nThe Godhead of our Lord.",
        ],
      ),
      Hymn(
        id: 280,
        number: "280",
        title: "Jesus Is Passing",
        category: "Praise & Worship",
        refrain: "Jesus is passing this way, this way, this way.\nJesus is passing this way, is passing this way today.",
        stanzas: [
          "1. Is there a heart that's waiting,\nLonging for pardon today?\nHear the glad message proclaiming:\nJesus is passing this way.",
          "2. Is there a heart that's waiting,\nWeary and longing for rest?\nCome to the arms of your Saviour,\nPillow your heart on His breast.",
          "3. Come to your only Redeemer,\nCome to His infinite love,\nCome to the gate that is leading\nHomewards to mansions above.",
          "4. Is there a heart that's waiting,\nLonging for pardon today?\nMercy is tenderly pleading:\nJesus is passing this way.",
        ],
      ),
      Hymn(
        id: 281,
        number: "281",
        title: "Jesus Lord Be Thou My Own",
        category: "Consecration & Dedication",
        stanzas: [
          "1. Jesus, Lord, be Thou my own.\nThee I long for, Thou alone:\nAll myself I give to Thee.\nDo what'er Thou wilt with me.",
          "2. Life without Thy love would be death, O Sovereign God, to me.\nBound and held by Thy dear chains,\nCaptive now my heart remains.",
          "3. Thou, O God, my heart enflame.\nGive that love which Thou dost claim.\nPayment I will ask for none,\nLove demands but love alone.",
          "4. God of Beauty, Lord of Light,\nThy good will is my delight.\nNow henceforth Thy Will Divine ever shall in all be mine.",
        ],
      ),
      Hymn(
        id: 282,
        number: "282",
        title: "Jesus Lord Forever King",
        category: "Praise & Worship",
        stanzas: [
          "1. Jesus Lord Messiah\nGod. With Your blood You redeemed us:\nTo You Lord the thanks is due.",
          "2. We were lost through Adam's sin:\nHelpless man nothing could do.\nLove again to rescue came,\nSaviour blessed was promised man.",
          "3. God prepared a people blessed,\nBut faithless man was all alone.\nFaithful God still love mankind,\nThe promised one did truly come.",
          "4. Jesus Lord we give You thanks,\nTo Thee honour, power and glory\nBoth now and forever,\nKing of Kings and Lord of Lords.",
        ],
      ),
      Hymn(
        id: 283,
        number: "283",
        title: "Jesus Meek And Lowly",
        category: "Lent & Passion",
        stanzas: [
          "1. Jesus meek and lowly, Saviour pure and holy,\nOn Thy love relying, come I to Thee flying.",
          "2. Prince of life and power, my salvation's tower,\nOn the cross I view Thee, calling sinners to Thee.",
          "3. There behold me gazing at the sight amazing,\nBending low before Thee, helpless I adore Thee.",
          "4. See the red wounds streaming with Christ's life blood gleaming,\nBlood for sinners flowing, pardon free bestowing.",
          "5. Fountain rich in blessing, Christ's fond love expressing,\nThou my aching sadness turnest into gladness.",
          "6. Lord in mercy guide me, be Thou e'er beside me,\nIn Thy ways direct me, 'neath Thy wings protect me.",
        ],
      ),
      Hymn(
        id: 284,
        number: "284",
        title: "Jesus My Lord",
        category: "Lent & Passion",
        refrain: "O pardon me, Jesus,\nThy mercy I implore,\nI will never more offend Thee,\nNo, never more.",
        stanzas: [
          "1. Jesus my Lord behold at length the day\nWhen I resolve from sin to turn away.",
          "2. Since my poor soul Thy precious blood has cost,\nSuffer it not to be forever lost.",
          "3. Kneeling in tears, behold me at Thy feet,\nLike Magdalene, forgiveness I entreat.",
        ],
      ),
      Hymn(
        id: 285,
        number: "285",
        title: "Jesus, My Lord Behold At Length The Day",
        category: "Lent & Passion",
        refrain: "O pardon me, Jesus; Thy mercy I implore;\nAnd I will never more offend Thee,\nNo, never more.",
        stanzas: [
          "1. Jesus, my Lord, behold at length the day,\nWhen I resolve from sin to turn away.",
          "2. Since my poor soul Thy precious blood has cost,\nSuffer it not be forever lost.",
          "3. Kneeling in tears, behold me at Thy feet;\nLike Magdalen, forgiveness I entreat.",
        ],
      ),
      Hymn(
        id: 286,
        number: "286",
        title: "Jesus, My Lord, My God",
        category: "Adoration & Eucharist",
        refrain: "Sweet Sacrament, You we adore,\nOh, make us love Thee more and more.",
        stanzas: [
          "1. Jesus, my Lord, my God, my all,\nHow can I love Thee as I ought?\nAnd how revere this wondrous gift\nSo far surpassing hope or thought.",
          "2. Had I but Mary's sinless heart\nTo love You with, my dearest King,\nOh with what bursts of fervent praise\nThy goodness Jesus would I sing.",
          "3. Ah see, within a creature's hand,\nThe vast creator deigns to be\nReposing infant like,\nAs though on Joseph's arm, or Mary's knee.",
          "4. Your body, soul, and Godhead all,\nO mystery of love divine,\nI cannot compass all I have,\nFor all You have and are, are mine.",
          "5. Sound, sound His praises higher still,\nAnd come ye angels to our aid,\n'Tis God, 'tis God, the very God\nWhose power man and angels made.",
        ],
      ),
      Hymn(
        id: 287,
        number: "287",
        title: "Jesus Praised The Widow's Mite",
        category: "Offertory",
        stanzas: [
          "1. Jesus praised the widow's mite\nBecause of the offering she gave,\nThat others gave of their riches,\nBut she gave herself.\nOh my soul, ask thyself what will I give to God?\nSee your brethren, carry their offering,\nProceeding to the altar.",
          "2. A loaf of bread and a cup of wine\nIn commemoration of me.\nReceive O God Thy creature,\nYou are the Lord who owns me.",
          "3. God the Father, the Almighty,\nBy Your mercy bless us,\nBless our homes and country\nAnd the Catholic Church.",
          "4. What I want in my life time is to\nalways do God's will;\nWhether in joy or in suffering\nI will keep His commandments.",
        ],
      ),
      Hymn(
        id: 288,
        number: "288",
        title: "Jesus The Master Key",
        category: "Praise & Worship",
        refrain: "Go up upon the hills, down the valleys,\nEast to West and North to South,\nTell them Jesus is the master key,\nTell them Jesus is the master key.",
        stanzas: [
          "1. Jesus the master key I believe,\nJesus the master key!\nThe key to everlasting life,\nJesus the master key.",
          "2. Our hopes and treasures lie above,\nJesus the master key.\nHe has the key of the treasury home,\nJesus the master key.",
          "3. He brought salvation to all mankind,\nJesus the master key!\nThe Kingdom of Eternity has come,\nJesus the master key!",
          "4. Today in Makurdi we proclaim that Jesus is the master key,\nWe say it to the hearing of all being:\nJesus is the master key.",
        ],
      ),
      Hymn(
        id: 289,
        number: "289",
        title: "Jesus The Sun Of Ransomed Earth",
        category: "Lent & Passion",
        stanzas: [
          "1. Jesus the sun of ransomed earth\nShed in our inmost souls Thy light\nAs in spring days a fairer birth\nHeralds, each morn, the doom of night.",
          "2. This hour of grace Thou dost impart\nTeach us with flowing tears the stain\nTo cleanse from every victim-heart\nThat longs to feel love's welcome pain.",
          "3. The day is come the accepted day\nWhen grace like nature flowers anew\nTrained by the hand the surer way\nRejoice we in our spring time too.",
          "4. Let the whole earth in worship bow\nGreat God before Thy mercy seat\nAs we renewed by grace do now\nWith praises new Thy presence greet.",
        ],
      ),
      Hymn(
        id: 290,
        number: "290",
        title: "Jesus The Very Thought Of Thee",
        category: "Praise & Worship",
        stanzas: [
          "1. Jesus the very thought of Thee\nWith sweetness fills my breast.\nBut sweeter far Thy face to see\nAnd in Thy presence rest.",
          "2. No voice can sing nor heart can frame,\nNor can the memory find\nA sweeter sound than Thy blest name,\nHow good to those who seek!",
          "3. O hope of every contrite heart,\nO joy of all the meek,\nTo those who fall, how kind Thou art,\nO Saviour of all mankind.",
          "4. But what to those who find?\nAh, this no tongue or pen can show,\nThe love of Jesus, what it is\nNone but His lovers know.",
          "5. Jesus, our only joy be Thou,\nAs Thou our prize will be.\nJesus, be Thou our glory now\nAnd through eternity.",
        ],
      ),
      Hymn(
        id: 291,
        number: "291",
        title: "Jesus You're The One I Love",
        category: "Communion",
        stanzas: [
          "1. Jesus, you're the one I love.\nYou're the one I know,\nYou're the one who makes me strong\nSpirit in my soul.\nFrom the clouds of yesterday,\nThrough the night of pain,\nTeach me, Lord, to know Your way,\nKnow it once again.",
          "2. May the bread we break today,\nMay the cup we share\nLift the burdens of our hearts,\nLift them everywhere.\nPassing on to each of us a measure of Your love,\nLove to make us whole again,\nAs we share Your word.",
          "3. Jesus you're the one I love,\nYou're the one I know,\nYou're the one who makes strong,\nSpirit in my soul.",
        ],
      ),
      Hymn(
        id: 292,
        number: "292",
        title: "Joy To The World",
        category: "Advent & Christmas",
        stanzas: [
          "1. Joy to the world, the Lord is come!\nLet earth receive her King,\nLet every heart prepare Him room,\nAnd heaven and nature sing, (2)\nAnd heaven, and heaven and nature sing.",
          "2. Joy to the world, the Saviour reigns!\nLet men their songs employ,\nWhile fields and floods,\nRocks, hills and plains repeat the sounding joy, (2)\nRepeat, repeat the sounding joy.",
          "3. He rules the world with truth and grace,\nAnd makes the nations prove\nThe glories of His righteousness\nAnd wonders of His love, (2)\nAnd wonders, and wonders of His love.",
        ],
      ),
      Hymn(
        id: 293,
        number: "293",
        title: "Just A Closer Walk With Thee",
        category: "Praise & Worship",
        refrain: "Just a closer walk with Thee,\nGrant it, Jesus is my plea.\nDaily walking close to Thee,\nLet it be, dear Lord, let it be.",
        stanzas: [
          "1. I am weak but Thou art strong,\nJesus, keep me from all wrong.\nI'll be satisfied as long\nAs I walk let me walk close to Thee.",
          "2. Thru this world of toil and snare:\nIf I falter, Lord, who cares?\nWho with me my burden shares?\nNone but Thee, dear Lord, none but Thee.",
        ],
      ),
      Hymn(
        id: 294,
        number: "294",
        title: "Just As I Am",
        category: "Lent & Passion",
        stanzas: [
          "1. Just as I am, without one plea,\nBut that Thy blood was shed for me,\nAnd that Thou bidst me come to Thee,\nO Lamb of God, I come, I come.",
          "2. Just as I am, and waiting not,\nTo rid my soul of one dark blot,\nTo Thee whose blood can cleanse each spot,\nO Lamb of God, I come, I come.",
          "3. Just as I am, poor, wretched, blind;\nSight, riches, healing of the mind,\nYea, all I need in Thee to find,\nO Lamb of God, I come, I come.",
          "4. Just as I am, Thou wilt receive,\nWilt welcome, pardon, cleanse, relieve;\nBecause Thy promise I believe,\nO Lamb of God, I come, I come.",
          "5. Just as I am, Thy love unknown\nHath broken every barrier down;\nNow, to be Thine, yea Thine alone,\nO Lamb of God, I come, I come.",
        ],
      ),
      Hymn(
        id: 295,
        number: "295",
        title: "Keep In Mind",
        category: "Easter & Resurrection",
        refrain: "Keep in mind that Jesus Christ has died for us and is risen from the dead.\nHe is our saving Lord, He is joy for all ages.",
        stanzas: [
          "1. If we die with the Lord,\nWe shall live with the Lord.",
          "2. If we endure with the Lord,\nWe shall reign with the Lord.",
          "3. In Him all our sorrow,\nIn Him all our joy.",
          "4. In Him hope of glory,\nIn Him all our love.",
          "5. In Him our redemption,\nIn Him all our grace.",
          "6. In Him our salvation,\nIn Him all our peace.",
        ],
      ),
      Hymn(
        id: 296,
        number: "296",
        title: "King Of Glory, King Of Peace",
        category: "Praise & Worship",
        stanzas: [
          "1. King of glory, King of peace,\nI will love You.\nAnd that love may never cease,\nI will love You.\nThou hast granted my request,\nThou hast heard me.\nThou didst note my working breast,\nThou hast spared me.",
          "2. Wherefore with my utmost heart,\nI will sing You.\nAnd the dream of all my heart,\nI will sing you.\nThough my sins against me cried,\nThou didst clear me,\nAnd alone when they replied\nYou did hear me.",
          "3. Seven whole days, not one in seven,\nI will praise You.\nIn my heart though not in heaven,\nI can praise You.\nSmall it is in this poor sort, to enclose You.\nEven eternity too short to extol You.",
        ],
      ),
      Hymn(
        id: 297,
        number: "297",
        title: "Kum Ba Yah, My Lord",
        category: "Praise & Worship",
        stanzas: [
          "1. Kum ba yah, my Lord,\nKum ba yah: (3)\nO Lord, kum ba yah.",
          "2. Someone's crying, Lord...\nKum ba yah: (3)\nO Lord, kum ba yah.",
          "3. Someone's singing, Lord...\nKum ba yah: (3)\nO Lord, kum ba yah.",
          "4. Someone's praying, Lord...\nKum ba yah: (3)\nO Lord, kum ba yah.",
        ],
      ),
      Hymn(
        id: 298,
        number: "298",
        title: "Lay Your Hands",
        category: "Communion",
        refrain: "Lay your hands gently upon us,\nLet their touch render your peace.\nLet them bring your forgiveness and healing,\nLay Your hands gently,\nLay Your hands.",
        stanzas: [
          "1. You were sent to free the broken hearted,\nYou were sent to give sight to the blind.\nYou desired to heal all our illnesses.\nLay Your hands, gently lay Your hands.",
          "2. Lord, we come to you in all our need,\nLord, we come to You, seeking wholeness.\nLay your hands, gently lay Your hands.",
        ],
      ),
      Hymn(
        id: 299,
        number: "299",
        title: "Lead Me Guide Me",
        category: "Praise & Worship",
        refrain: "Lead me guide me along the way\nFor if you lead me, I cannot stray\nLord, let me walk each day with thee\nLead me, Oh Lord lead me.",
        stanzas: [
          "1. I am weak and I need thy strength and power\nTo help me over my weakest hour\nHelp through the darkness thy face to see\nLead me, oh Lord lead me.",
          "2. Help me tread in the paths of righteousness\nBe my aid when Satan and sin oppress\nI am putting all my trust in thee\nLead me, oh Lord lead me.",
          "3. I am lost if you take your hand from me\nI am blind without thy sight to see\nLord, just always let me thy servant be",
        ],
      ),
      Hymn(
        id: 300,
        number: "300",
        title: "Let All That Is Within Me Cry",
        category: "Praise & Worship",
        stanzas: [
          "1. Let all that is within me cry 'holy'.\nLet all that is within me cry 'holy'.\nHoly, holy, holy is the Lamb that was slain.",
          "2. Let all that is within me cry 'mighty'.\nLet all that is within me cry 'mighty'.\nMighty, mighty, mighty is the Lamb that was slain.",
          "3. Let all that is within me cry 'worthy'.\nLet all that is within me cry 'worthy'.\nWorthy, worthy, worthy is the Lamb that was slain.",
          "4. Let all that is within me cry 'blessed'.\nLet all that is within me cry 'blessed'.\nBlessed, blessed, blessed is the Lamb that was slain.",
          "5. Let all that is within me cry 'Jesus'.\nLet all that is within me cry 'Jesus'.\nJesus, Jesus, Jesus is the Lamb that was slain.",
        ],
      ),
      Hymn(
        id: 301,
        number: "301",
        title: "Let's All Join Together",
        category: "Praise & Worship",
        refrain: "Walk in the light, (3)\nWalk in the light of God.",
        stanzas: [
          "1. Let's all join together in communion sweet,\nWalk, walk in the light.\nAnd love one another till the Saviour we meet,\nWalk, walk in the light.",
          "2. Jesus died on Calvary,\nWalk, walk in the light;\nTo save the lost like you and me,\nWalk, walk in the light.",
          "3. But then again that's not the end,\nWalk, walk in the light.\nHe lives today, He'll be your friend,\nWalk, walk in the light.",
          "4. Jesus did just what He said,\nWalk, walk in the light.\nHe healed the sick and He raised the dead,\nWalk, walk in the light.",
        ],
      ),
      Hymn(
        id: 302,
        number: "302",
        title: "Let The Trumpet Blast",
        category: "Praise & Worship",
        refrain: "Let the trumpet blast, let the cymbals crash,\nLet the dancing begin!\nLet everything that breathes proclaim:\nJesus is life! Jesus is life!",
        stanzas: [
          "1. Praise Him with blasts of the trumpet,\nPraise Him with lyre and harp.\nPraise Him with drums and dancing,\nJesus is life! Jesus is life!",
          "2. Praise Him with clashing cymbals,\nPraise Him with strings and reeds.\nPraise Him with clanging cymbals,\nJesus is life! Jesus is life!",
          "3. Orchards and forests, mountains and hills,\nBirds and living creatures,\nDance and praise His name!",
          "4. Praise Him, the Sun of Justice,\nPraise Him, the King of Kings,\nPraise Him, the risen Lord,\nJesus is life! Jesus is life!",
          "5. He has been kind to His people,\nGiving victory to us who are weak.\nWe rejoice and exult in Him!\nJesus our Life.",
        ],
      ),
      Hymn(
        id: 303,
        number: "303",
        title: "Let Us Break Bread",
        category: "Offertory",
        stanzas: [
          "1. Let us break bread together at the altar.\nBreak bread together, we are one,\nFor when we are together, Christ is with us.\nBreak bread together, for we are one.",
          "2. Let us drink wine together at the altar.\nDrink wine together we are one,\nFor when we are together Christ is with us.\nDrink wine together, for we are one.",
          "3. Let us offer together gifts at the altar.\nOffer together, we are one,\nFor when we are together Christ is with us.\nOffer together, we are one.",
          "4. Let us join hands together at the altar.\nJoin hands together, we are one,\nFor when we are together Christ is with us.\nJoin hands together, for we are one.",
          "5. Let us love one another at the altar.\nLove one another, we are one,\nFor when we are together Christ is with us.\nLove one another, for we are one.",
        ],
      ),
      Hymn(
        id: 304,
        number: "304",
        title: "Let Us Break Bread Together On Our Knees",
        category: "Communion",
        stanzas: [
          "1. Let us break bread together on our knees,\nLet us break bread together on our knees;\nWhen I fall on my knees with my face to the rising sun,\nO Lord have mercy on me.",
          "2. Let us drink wine together on our knees,\nLet us drink wine together on our knees;\nWhen I fall on my knees with my face to the rising sun,\nO Lord have mercy on me.",
          "3. Let us praise God together on our knees,\nLet us praise God together on our knees;\nWhen I fall on my knees with my face to the rising sun,\nO Lord have mercy on me.",
        ],
      ),
      Hymn(
        id: 305,
        number: "305",
        title: "Let Us Come",
        category: "Entrance",
        refrain: "Let us come before the Lord,\nLet us praise His name with joy. (2x)",
        stanzas: [
          "1. The Lord is good all the time\nAnd His mercy is forever. (2x)",
          "2. The Lord is kind and full of compassion,\nSlow to anger, abounding in love. (2x)",
          "3. With the Lord there is mercy\nAnd fullness of redemption. (2x)",
        ],
      ),
      Hymn(
        id: 306,
        number: "306",
        title: "Lift Jesus Higher",
        category: "Praise & Worship",
        stanzas: [
          "1. Lift Jesus higher\n(Higher, higher)! A little higher\n(Higher, higher)!\nLift Him up for the world to see.\nHe said 'If I be lifted up for the world,\nWill draw all men unto me'.\nLift Him higher.",
        ],
      ),
      Hymn(
        id: 307,
        number: "307",
        title: "Light Of Christ (Psalm 27)",
        category: "Praise & Worship",
        refrain: "Light of Christ, light our way,\nLight our way as we go.",
        stanzas: [
          "1. The Lord is my light and my salvation,\nWhom shall I fear?",
          "2. The Lord is the stronghold of my life,\nOf whom shall I be afraid?",
          "3. He will hide me under the cover of His wings,\nHe will set me high on a rock.",
          "4. And I shall dwell in the house of the Lord\nAll the days of my life.",
          "5. The Lord is a lamp unto my feet,\nHe is a light to my path.",
          "6. His light shall break forth like the dawn,\nArise for the light has come.",
        ],
      ),
      Hymn(
        id: 308,
        number: "308",
        title: "Like A Sunflower",
        category: "Consecration & Dedication",
        refrain: "Like a sunflower, that follows every movement of the sun,\nSo I turn towards You, to follow You, my God.",
        stanzas: [
          "1. In simplicity, honesty I follow. (2)",
          "2. In simplicity, charity I follow. (2)",
          "3. In simplicity, integrity I follow. (2)",
          "4. In simplicity, fidelity I follow. (2)",
        ],
      ),
      Hymn(
        id: 309,
        number: "309",
        title: "Like Olive Branches",
        category: "Entrance",
        refrain: "Like olive branches around the table of the Lord,\nSo God's children in the Church.",
        stanzas: [
          "1. Blessed those who fear the Lord, who seek His path,\nFor they shall find favour in His sight.",
          "2. Blessed be the toil of hands, they shall bear fruit.\nIn joy and in gladness shall you work.",
          "3. With good fortune in your home shall you be blessed.\nYour wife shall be like a fruitful vine.",
          "4. Blessed shall your children be around your board,\nLike strong olive branches shall they stand.",
          "5. Blessed indeed, shall be the man who serves the Lord.",
          "6. May the Lord who dwells on high, give joy to you,\nAnd may He protect you in your life.",
          "7. May the sight of many sons delight your heart.\nMay God grant His peace to Israel,\nFor he shall prevail throughout his life.",
        ],
      ),
      Hymn(
        id: 310,
        number: "310",
        title: "Like The Deer That Yearns",
        category: "Entrance",
        stanzas: [
          "1. Like the deer that yearns for running steams,\nSo my soul is yearning for You, my God.",
          "2. My soul is thirsting for the Lord.\nWhen shall I see Him face to face?\nI shall go to the house of God with songs of joy.",
          "3. My tears have become my bread, by night and by day,\nAs I hear it said all day long, where is your God?",
          "4. Why are you cast down, my soul? Why groan within me?\nHope in God, I will praise Him still,\nMy Saviour and my God.",
          "5. Praise the Father, the Son and Holy Spirit,\nBoth now and forever,\nThe God who is, who was and who will be\nWorld without end.",
        ],
      ),
      Hymn(
        id: 311,
        number: "311",
        title: "Little Donkey",
        category: "Advent & Christmas",
        stanzas: [
          "1. Little donkey, little donkey on the dusty road,\nAs your feet come plodding onwards with your precious load.",
          "2. Been a long time little donkey through the winter's night,\nWon't be long now little donkey Bethlehem's in sight.\nRing out those bells tonight, Bethlehem, Bethlehem. (2)",
          "3. Little donkey, little donkey, journey's end is near,\nThere are wise men waiting for her as you bring Him near.",
          "4. Do not falter, little donkey, there's a star ahead,\nIt will guide you, little donkey, to a cattle shed.",
        ],
      ),
      Hymn(
        id: 312,
        number: "312",
        title: "Living Water",
        category: "Holy Spirit",
        refrain: "Father, Father, Father,\nJesus, Jesus, Jesus,\nSpirit, Spirit, Spirit.",
        stanzas: [
          "1. Let the living water flow over my soul,\nLet the Holy Spirit come and take control\nIn every situation that may burden my mind,\nAll my fears and worries unto Thee I bring.",
        ],
      ),
      Hymn(
        id: 313,
        number: "313",
        title: "Lo He Comes With Cloud Descending",
        category: "Advent & Christmas",
        stanzas: [
          "1. Lo He comes with cloud descending\nOnce for favoured sinners slain;\nThousand thousand saints ascending\nSwear the triumph of His train:\nAlleluia, alleluia, alleluia,\nJesus comes and comes to reign.",
          "2. Every eye shall now behold Him,\nRobed in dreadful majesty;\nThose who set at naught and sold Him,\nPierced and nailed Him to the tree,\nDeeply wailing, deeply wailing, deeply wailing,\nShall the true Messiah see.",
          "3. When the solemn trump has sounded,\nHeaven and earth shall flee away;\nAll who hate Him must confounded,\nHear the summons of that day:\nCome to judgment, come to judgment, come to judgment,\nCome to judgment, come away.",
          "4. Now redemption long expected\nSee in solemn pomp appear;\nAll His saints by men rejected\nNow shall meet Him in the air:\nHallelujah, hallelujah, hallelujah,\nSee the day of God appear.",
          "5. Yea, amen, let all adore Thee,\nHigh on Thine eternal throne;\nSaviour, take the power and glory,\nClaim the kingdom for Thine own:\nOh, come quickly, come quickly, come quickly,\nHallelujah! Come, Lord come!",
        ],
      ),
      Hymn(
        id: 314,
        number: "314",
        title: "Long Live The Lord",
        category: "Praise & Worship",
        refrain: "Long live the Lord.\nFor He is my Saviour.\nFor He is my Saviour.",
        stanzas: [
          "1. For He is my light, for He is my Saviour.\nFor He is my stronghold, for He is my Saviour.\nFor He is my Shepherd,\nAnd to Him I sing all my praise,\nTo Him I pledge my love.",
          "2. For He is my Rock, for He is my Saviour.\nFor He is my rampart, for He is my Saviour.\nFor He is my Shepherd.",
          "3. For He is my Life, for He is my Saviour.\nFor He is my Refuge, for He is my Saviour.\nFor He is my Shepherd.",
          "4. For He is my love...\nIn Him joy forever.",
          "5. For He is my Way...\nWith Him I am walking.",
        ],
      ),
      Hymn(
        id: 315,
        number: "315",
        title: "Long Time Ago",
        category: "Advent & Christmas",
        refrain: "Hark now hear the angels sing,\nA new King born today,\nAnd men will live forever more\nBecause of Christmas day.\nTrumpets sound and angels sing,\nListen to what they say\nThat men will live forever more\nBecause of Christmas day.",
        stanzas: [
          "1. Long time ago in Bethlehem,\nSo the Holy Bible says,\nMary's Boy Child Jesus Christ,\nWas born on Christmas Day.",
          "2. While shepherds watched their flock by night,\nThey saw a bright new shining star.\nThey heard a choir sing a song,\nThe music seemed to come from afar.",
          "3. Now Joseph and his wife Mary\nCame to Bethlehem that night.\nShe found no place to bear her child,\nNot a single room was in sight.",
          "4. By and by they found a little nook\nIn a stable all forlorn.\nAnd in a manger cold and dark,\nMary's little boy was born.",
        ],
      ),
      Hymn(
        id: 316,
        number: "316",
        title: "Look Beyond",
        category: "Communion",
        refrain: "Look beyond the bread you eat,\nSee your Saviour and your Lord.\nLook beyond the cup you drink,\nSee His love poured out as blood.",
        stanzas: [
          "1. Give us a sign that we might believe in You.\nOur Fathers brought us manna from the sky.",
          "2. I am the Bread which from heaven came.\nHe who eats this Bread will never die.",
          "3. The Bread I give you will be My very Flesh.\nMy Blood will truly be your drink.",
          "4. This man speaks harshly. Who can listen to His word?\nWe shall no longer follow Him.",
          "5. You my disciples, will you also leave?\nLord to whom can we go?",
        ],
      ),
      Hymn(
        id: 317,
        number: "317",
        title: "Looking At The Sunrise",
        category: "Praise & Worship",
        stanzas: [
          "1. Looking at the sunrise, heralding the dawn.\nList'ning to the birds sing, hearing every sound.\nI'm at peace with nature,\nAll my cares and troubles are resting with the Lord.",
          "2. Children playing round me: Laughter in my heart,\nPeople toiling sadly, comfort I impart.\nJoy is with me daily and it's all I know,\nBecause Jesus loves me, for He told me so.",
          "3. Listen to me, brothers, heed to what I now say.\nPlace your trust in Jesus, let Him guide your way.\nHe will not forsake or from you turn away.\nPeace is yours, my brothers, Jesus is the Way.",
        ],
      ),
      Hymn(
        id: 318,
        number: "318",
        title: "Lord Accept The Gifts",
        category: "Offertory",
        stanzas: [
          "1. Lord, accept the gifts we offer at this Eucharistic Feast.\nBread and wine to be transformed now through the action of Thy priest.\nTake us, too, O Lord, transform us, be Thy grace in us increased.",
          "2. May our souls be pure and spotless as the Host of wheat so fine.\nMay all stain of sin be crushed out, like the grape that forms the wine\nAs we too become partakers in this Sacrifice Divine.",
          "3. Take our gifts, Almighty Father, living God, eternal true,\nWhich we give through Jesus Christ, our Saviour, pleading here for us anew.\nGrant salvation to all present, and our faith and love renew.",
        ],
      ),
      Hymn(
        id: 319,
        number: "319",
        title: "Lord Dismiss Us",
        category: "Recessional",
        stanzas: [
          "1. Lord, dismiss us with Your blessing,\nFill our hearts with joy and peace;\nLet us each, Your love possessing,\nTriumph in redeeming grace.\nO refresh us, O refresh us,\nAs we work to keep apace.",
          "2. Thanks we give and adoration\nFor the gospel's joyful mould:\nMay the fruits of this Communion\nIn our hearts and lives abound;\nEver faithful, ever faithful to the\nTruth may we be found.",
          "3. So that when Your love shall call us, Saviour, from the world away,\nLet no fear of death upset us, glad Your summons to obey.\nMay we ever, may we ever in Your loving presence stay.\nAmen.",
        ],
      ),
      Hymn(
        id: 320,
        number: "320",
        title: "Lord For Tomorrow",
        category: "Praise & Worship",
        stanzas: [
          "1. Lord for tomorrow and its needs, I do not pray.\nKeep me, my God, from stain of sin, just for today.",
          "2. Let me be slow to do my will, prompt to obey.\nHelp me to mortify my flesh, just for today.",
          "3. Let me both diligently work, and duly pray.\nLet me be kind in word and deed, just for today.",
          "4. Let me no wrong or idle word, unthinking say.\nSet Thou a seal upon my lips, just for today.",
          "5. Let me in season Lord be grave, in season Lord gay.\nLet me be faithful to Thy grace, just for today.",
          "6. So for tomorrow and its needs, I do not pray.\nBut keep me, guide me, love me, Lord just for today.",
        ],
      ),
      Hymn(
        id: 321,
        number: "321",
        title: "Lord God Of Isaac",
        category: "Praise & Worship",
        refrain: "Oh Lord my Saviour (3)\nOh my Saviour.",
        stanzas: [
          "1. Lord God of Isaac, Abraham, Solomon.\nThou only art my Creator. (2)",
          "2. Lord God of Israel, and Aaron and Joseph,\nThou only art my Creator. (2)",
          "3. Lord God of Daniel, and Jacob and Thomas,\nThou only art my Creator. (2)",
          "4. Lord God of heaven, who by His Word made all things,\nThou only art my Creator.",
          "5. Through Your only Son, who is Jesus Christ,\nWho is alone my Saviour. (2)",
          "6. Glory to the Father, the Son and Holy Ghost,\nThe Mystery of the Trinity. (2)",
        ],
      ),
      Hymn(
        id: 322,
        number: "322",
        title: "Lord, I Am Not Worthy",
        category: "Communion",
        refrain: "Lord I am not worthy (3)\nTo receive You under my roof.",
        stanzas: [
          "1. A Roman came to Jesus his servant was paralyzed.\nWhen Jesus said 'I will come to Him', the Roman was very surprised.",
          "2. The Roman trusted Jesus to heal the man by His power.\nSo Jesus said 'let it be done'. And the servant was healed from that hour.",
          "3. Each time we come to Jesus, although we are far from good,\nHe will heal us and He will help us, if only we trust as we should.",
        ],
      ),
      Hymn(
        id: 323,
        number: "323",
        title: "Lord, I Believe In Thee",
        category: "Praise & Worship",
        stanzas: [
          "1. Lord I believe in Thee. Lord, I believe.\nGreat is my need of Thee, great is my need.\nGive me the strength to be holy and close to Thee.\nGrant me the light to see. Lord, increase my faith.",
          "2. In Thee I hope, O Lord. In Thee, I hope.\nStrengthen my hope, O Lord. Strengthen my hope,\nFirmly I'll cling to Thee; trusting your love for me,\nKnowing that safe I'll be, Lord, increase my hope.",
          "3. Thou art my love, O Lord, Thou art my love,\nStrengthen this love, O Lord, strengthen this love,\nLord, take this heart of mine, take it now and make it Thine.\nI, the branch and Thou the Vine. Lord, increase my love.",
        ],
      ),
      Hymn(
        id: 324,
        number: "324",
        title: "Lord Jesus Think On Me",
        category: "Lent & Passion",
        stanzas: [
          "1. Lord Jesus think on me, and purge away my sins.\nFrom earth born passions set me free, and make me pure within.",
          "2. Lord Jesus think on me, with care and woe oppressed.\nLet me Thy loving servant be and taste Thy promised rest.",
          "3. Lord Jesus think on me, amid the battle's strife,\nIn all my pain and misery, be Thou my health and life.",
          "4. Lord Jesus, think on me nor let me go astray.\nThrough darkness and perplexity point Thou the heavenly way.",
        ],
      ),
      Hymn(
        id: 325,
        number: "325",
        title: "Lord Let Us Know Your Holy Way",
        category: "Offertory",
        stanzas: [
          "1. Lord, let us know Your Holy Way. Let us follow Your Holy Path.\nO Lord, receive our hearts. O Lord, receive our gifts.\nO Lord, receive our bread. O Lord, receive our wine.",
          "2. All that we have, all that we own\nAll come from You, our Blessed Lord.",
          "3. Teach us to be humble and true.\nTeach us to be generous, Lord.",
          "4. We thank You for all the blessings\nThat we receive from You, O Lord.",
          "5. Then let us give with open mind,\nWhat we receive from You, O Lord.",
        ],
      ),
      Hymn(
        id: 326,
        number: "326",
        title: "Lord Of All Hopefulness",
        category: "Praise & Worship",
        stanzas: [
          "1. Lord of all hopefulness, Lord of all joy,\nWhose trust, ever child-like, no cares could destroy.\nBe there at our waking and give us we pray\nYour bliss in our hearts, Lord, at the break of the day.",
          "2. Lord of all eagerness, Lord of all faith,\nWhose strong hands were skilled at the plane and the lathe,\nBe there at our labours and give us, we pray,\nYour strength in our hearts, Lord, at the break of the day.",
          "3. Lord of all kindliness, Lord of all grace,\nYour hands swift to welcome, Your arms to embrace.\nBe there at our homing and give us, we pray,\nYour love in our hearts, Lord, at the eve of the day.",
          "4. Lord of all gentleness, Lord of all calm,\nWhose voice is contentment, whose presence is balm,\nBe there at our sleeping and give us, we pray,\nYour peace in our hearts, Lord, at the break of the day.",
        ],
      ),
      Hymn(
        id: 327,
        number: "327",
        title: "Lord Send Out Your Spirit",
        category: "Holy Spirit",
        refrain: "Lord, send out Your Spirit and renew the face of the earth. (2)",
        stanzas: [
          "1. Bless the Lord, oh my soul. Oh Lord, my God,\nYou are great indeed: How manifold are Your works, O Lord,\nThe earth is full of Your creatures.",
          "2. If You take away their breath, O Lord, they die and return to the dust.\nWhen You send out Your Spirit, they live;\nYou renew the face of the earth.",
        ],
      ),
      Hymn(
        id: 328,
        number: "328",
        title: "Lord We Pray For Golden Peace",
        category: "Praise & Worship",
        stanzas: [
          "1. Lord, we pray for golden peace, peace all over and land.\nMay all men dwell in liberty, walking hand in hand.\nBanish fear and ignorance, hunger, thirst and pain.\nBanish hate and poverty, let no man live in vain. (2)",
          "2. Keep all men forever one, one in love and one in grace.\nAnd wipe away all war and strife, give freedom to each race.",
          "3. Let your justice reign supreme, righteousness always.\nLet goodness rule the hearts of men and evil overcome.",
        ],
      ),
      Hymn(
        id: 329,
        number: "329",
        title: "Lord We Touch You Today",
        category: "Praise & Worship",
        refrain: "To live is to die is to laugh, is to cry.\nTo live is to love with all your heart.\nTo live is to hope, is to talk in the Lord,\nAnd to live is to sing in His love.",
        stanzas: [
          "1. Lord, we touch You today. Lord, we touch You today.\nYou gave us Your life. Lord, we touch You today.",
          "2. Lord, we give You our hearts. Lord, we give You our hearts.\nYou gave us Your life. Lord, we give You our love.\nLord, we give You our hearts.",
          "3. Lord, we've touched You today. Lord, we've touched You today.\nYou gave us Your Death. Lord, we've touched You today.",
          "4. Lord, we sing in Your love, Lord, we sing in Your love.\nWe share in Your life, we share in Your love.\nLord, we sing in Your love.",
        ],
      ),
      Hymn(
        id: 330,
        number: "330",
        title: "Lose Yourself In Me",
        category: "Consecration & Dedication",
        stanzas: [
          "1. Lose yourself in Me, and you will find yourself.\nLose yourself in Me and you will find new life.\nLose yourself in Me and you will find yourself,\nAnd you will live, and you will live in My Love.",
          "2. Unless a grain of wheat falls into the ground,\nIt still remains but a grain of wheat.\nBut if it falls and dies, then it bears much fruit.\nSo it is with those who love themselves in Me.",
        ],
      ),
      Hymn(
        id: 331,
        number: "331",
        title: "Lourdes Magnificat",
        category: "Marian Hymns",
        refrain: "God fills me with joy, Alleluia,\nHis holy presence is my robe, Alleluia.",
        stanzas: [
          "1. My soul now glorify the Lord who is my Saviour.\nRejoice for who am I that God has shown me favour.",
          "2. The world shall call me blest and ponder on my story,\nIn me is manifest God's greatness and His glory.",
          "3. For those who are His friends and keep His laws as holy,\nHis mercy never ends and He exalts the lowly.",
          "4. But by His power the great, the proud, the self-conceited,\nThe Kings who sit in state are humbled and defeated.",
          "5. He feeds the starving poor, He guards His holy nation,\nFulfilling what He swore long since in revelation.",
          "6. Then glorify with me the Lord who is my Saviour,\nOne Holy Trinity, forever and forever.",
        ],
      ),
      Hymn(
        id: 332,
        number: "332",
        title: "Love Is His Word",
        category: "Communion",
        refrain: "Richer than gold is the love of my Lord.\nBetter than splendour and wealth.",
        stanzas: [
          "1. Love is His Word, Love is His way,\nFeasting with men, fasting alone.\nLiving and dying, rising again,\nLove, only love, in His way.",
          "2. Love is His way, love is His mark,\nSharing His last Passover feast.\nChrist at His table, Host to the twelve,\nLove, only love, is His mark.",
          "3. Love is His mark, love is His sign,\nBread for our strength, wine for our joy.\n'This is My Body, this is My Blood.'\nLove, only love, is His sign.",
          "4. Love is His sign, love is His news.\n'Do this', He said, 'lest you forget\nAll My deep sorrow, all My dear blood.'\nLove, only love, is His news.",
          "5. Love is His news, Love is His Name.\nWe are His own, chosen and called:\nFamily, brethren, cousins and kin,\nLove, only Love is His Name.",
          "6. Love is His Name, Love is His Law.\nHear His Command, all who are His:\n'Love one another, I have loved you.'\nLove, only love is His Law.",
          "7. Love is His Law, Love is His Word,\nLove of the Lord, Father and Word,\nLove of the Spirit, God ever One.\nLove, only Love is His Word.",
        ],
      ),
      Hymn(
        id: 333,
        number: "333",
        title: "Loving Shepherd",
        category: "Praise & Worship",
        stanzas: [
          "1. Loving Shepherd of Thy sheep, keep me, Lord, in safety keep.\nNothing can Thy power withstand, none can pluck me from Thy hand.",
          "2. Loving Shepherd, Thou didst give Thine own life that I might live.\nMay I love Thee day by day, gladly Thy sweet will obey.",
          "3. Loving Shepherd, ever near, teach me still Thy voice to hear.\nSuffer not my step to stray from the straight and narrow way.",
          "4. Where Thou leadest may I go, walking in Thy steps below.\nThen before Thy Father's Throne Jesus claim me for Thine own.",
        ],
      ),
      Hymn(
        id: 334,
        number: "334",
        title: "Low In The Grave He Lay",
        category: "Easter & Resurrection",
        refrain: "Up from the grave He arose with a mighty triumph o'er His foes.\nHe arose a victor from the dark domain,\nAnd He lives forever with the saints to reign.\nHe arose! He arose! Alleluia! Christ arose!",
        stanzas: [
          "1. Low in the grave He lay, Jesus my Saviour,\nWaiting the coming day: Jesus my Lord.",
          "2. Vainly they watch Him bleed, Jesus my Saviour,\nVainly they seal the dead: Jesus my Lord.",
          "3. Death cannot keep his prey: Jesus my Saviour.\nHe tore the bars away: Jesus my Lord.",
        ],
      ),
      Hymn(
        id: 335,
        number: "335",
        title: "Magnificat Glorify The Lord",
        category: "Marian Hymns",
        refrain: "Glorify the Lord, my soul glorifies the Lord\nAnd my God, my spirit is glad in Him, amen.",
        stanzas: [
          "1. He looks on me, alleluia, He lifts me up;\nHis gladness fills all my days,\nAll the peoples will share my joy, alleluia.",
          "2. His gifts He has outpoured on me, His little ones;\nHe has made great, magnify the Lord with me, alleluia.",
          "3. For those who love His holy name,\nHis mercy will not die, His strong right arm\nPut down the proud and He lifts the lowly high, alleluia.",
          "4. He fills the hungry with many good things\nAnd all the rich He sends away;\nThe promise made to Abraham is soon fulfilled\nTo endless days, alleluia.",
        ],
      ),
      Hymn(
        id: 336,
        number: "336",
        title: "Make Me A Channel",
        category: "Consecration & Dedication",
        refrain: "Oh Master, grant that I may never seek so much\nTo be consoled as to console,\nTo be understood as to understand,\nTo be loved as to love with all my soul.",
        stanzas: [
          "1. Make me a channel of Your peace.\nWhere there is hatred, let me bring Your love.\nWhere there is injury, Your pardon, Lord.\nAnd where there's doubt, true faith in You.",
          "2. Make me a channel of Your peace.\nWhere there's despair in life let me bring hope,\nWhere there is darkness, only light,\nAnd where there's sadness ever joy.",
          "3. Make me a channel of Your peace.\nIt is in pardoning that we are pardoned,\nIn giving to all men that we receive,\nAnd in dying that we're born to eternal life.",
        ],
      ),
      Hymn(
        id: 337,
        number: "337",
        title: "Man Is Lonely By Birth",
        category: "Praise & Worship",
        stanzas: [
          "1. Man is lonely by birth, man is only a pilgrim on earth.\nBorn to be king, time is but a temporary thing,\nOnly on loan while on earth.",
          "2. Like the wind in the tree man has been rather reckless and free.\nThrown far and wide, He longs to settle down beside\nThe stream flowing through eternity.",
          "3. Like the grass on the lawn, He will pass by the way and be gone.\nA lesson to learn, we walk but once, there's no return.\nTime is always moving on.",
          "4. Man is longing for one, for a song and a place in the sun,\nFor home up above, where ev'ry day is lived in love,\nFor rest when the journey is done.",
        ],
      ),
      Hymn(
        id: 338,
        number: "338",
        title: "Man Of Sorrows, Wrapt In Grief",
        category: "Lent & Passion",
        stanzas: [
          "1. Man of sorrows, wrapt in grief, bow Thine ear to our relief;\nThou for us the path hast trod of the dreadful wrath of God;\nThou the cup of fire hast drained till its light alone remained.\nLamb of love! We look to Thee: Hear our mournful litany.",
          "2. By the garden, fraught with woe, whither Thou full oft wouldst go;\nBy Thine agony of prayer in the desolation there;\nBy the dire and deep distress of that mystery fathomless,\nLord, our tears in mercy see: Hearken to our litany.",
          "3. By the chalice brimming o'er with disgrace and torment sore;\nBy those lips which fain would pray that it might but pass away;\nBy the heart which drank it dry, lest a rebel race should die,\nBe Thy pity, Lord, our plea: Hear our solemn litany.",
          "4. Man of sorrows! Let Thy grief purchase for us our relief;\nLord of mercy! Bow Thine ear, slow to anger, swift to hear;\nLead us to the throne of God by the cross' royal road,\nThere for aye to sing to Thee Heaven's triumphant litany.",
        ],
      ),
      Hymn(
        id: 339,
        number: "339",
        title: "Man Oh Man",
        category: "Praise & Worship",
        stanzas: [
          "1. Man, Oh man, look up and say:\nWhy am I here? What's my job? What's my goal?\nYou are from God, not only clay.\nYou are a person with body and soul.\nYou are never forsaken like the sparrows all over the sky.\nYou may be badly bed-ridden, Oh man,\nYet trust and you'll never die.",
          "2. If pride you'd have, God you'd forget,\nWhen you do strive to be great, aim too high greatness will fade,\nYou'll soon regret. Sooner or later you're going to cry.",
          "3. You may be blind begging all day.\nMission each one, got a job to be done.\nYou are a man, get up and pray.\nDon't you forget, you're a part of God's plan.",
          "4. Born with no feet, born with no hands,\nPeople would stare, 'Look he's useless', they'd say.\nYou'd always sit, you'd have no friends,\n'God in His mercy, My son', He would say.",
          "5. A cripple you'd be from this day on,\nKeep this in mind you don't suffer alone.\nFamine and war, sickness and death,\nSuffer we all, every person on earth.",
        ],
      ),
      Hymn(
        id: 340,
        number: "340",
        title: "Maranatha",
        category: "Advent & Christmas",
        refrain: "Maranatha! Come, O Christ the Lord!",
        stanzas: [
          "1. I am the Root of Jesse and David's Son,\nThe radiant Star of morning and God's own light.",
          "2. The Spirit and the Bride, say 'Come.'\nLet him who hears their voices say 'Come'.",
          "3. He who has thirst, let him come.\nAnd he who has desire let him drink the waters of everlasting life.",
          "4. 'Yes, I come very soon!'\nCome, O Lord Jesus.",
        ],
      ),
      Hymn(
        id: 341,
        number: "341",
        title: "Mary Had A Baby",
        category: "Advent & Christmas",
        stanzas: [
          "1. Mary had a baby, yes, my Lord,\nMary had a baby, Lord.\nMary had a baby, yes, my Lord,\nAnd the angels in the heavens are singing.",
          "2. What did she name him, yes, my Lord?\nWhat did she name him, Lord?\nWhat did she name him, yes, my Lord?\nAnd the angels in the heavens are singing.",
          "3. Named him King Jesus, yes, my Lord,\nNamed him King Jesus, Lord,\nNamed him King Jesus, yes, my Lord,\nAnd the angels in the heavens are singing.",
          "4. Where was he born, yes my Lord?\nWhere was he born, Lord?\nWhere was he born, yes my Lord?\nAnd the angels in the heavens are singing.",
          "5. Born in a manger, yes, my Lord,\nBorn in a manger, Lord,\nBorn in a manger, yes, my Lord,\nAnd the angels in the heavens are singing.",
        ],
      ),
      Hymn(
        id: 342,
        number: "342",
        title: "Master Speak Thy Servant Heareth",
        category: "Consecration & Dedication",
        stanzas: [
          "1. Master, speak! Thy servant heareth,\nWaiting for Thy gracious word,\nLonging for Thy voice that cheereth;\nMaster, let it now be heard.\nI am listening, Lord, for Thee;\nWhat hast Thou to say to me?",
          "2. Speak to me by name, O Master,\nLet me know it is to me;\nSpeak, that I may follow faster,\nWith a step more firm and free,\nWhere the Shepherd leads the flock,\nIn the shadow of the rock.",
          "3. Master, speak! Though least and lowest,\nLet me not unheard depart;\nMaster, speak! For O, Thou knowest\nAll the yearning of my heart,\nKnowest all its truest need:\nSpeak! And make me blest indeed.",
          "4. Master, speak! And make me ready,\nWhen Thy voice is truly heard,\nWith obedience glad and steady\nStill to follow every word.\nI am listening, Lord, for Thee:\nMaster, speak! O, speak to me.",
        ],
      ),
      Hymn(
        id: 343,
        number: "343",
        title: "May The Peace Of The Lord",
        category: "Recessional",
        refrain: "May the peace of the Lord be with you,\nWith your friends and your family too,\nLet it be, let it grow, and everywhere you go,\nMay the peace of the Lord follow you.",
        stanzas: [
          "1. I leave you peace now,\nIt's My peace I give to you;\nNot as the world gives do I give to you.",
          "2. Don't be afraid, let your hearts be untroubled,\nHave faith in Me, and have faith in God.",
        ],
      ),
      Hymn(
        id: 344,
        number: "344",
        title: "More And More",
        category: "Praise & Worship",
        refrain: "More and more, more and more,\nOh to love Thee, Saviour, more and more;\nMore and more, more and more,\nOh to love Thee, Saviour, more and more.",
        stanzas: [
          "1. For Thy goodness, O my Saviour,\nI would praise Thee o'er and o'er;\nMay the Holy Spirit teach me\nHow to love Thee more and more.",
          "2. For the blessings that surround me,\nLord, Thy mercy I adore;\nFor Thy care so deep and tender,\nI would love Thee more and more.",
          "3. Raging tempest, rolling billow,\nThou hast brought me safely o'er;\nThou hast led me, safely led me,\nAnd I long to love Thee more.",
          "4. Till my journey here is ended,\nTill I reach the heavenly shore,\nThis my earnest supplication:\nThat my soul may love Thee more.",
        ],
      ),
      Hymn(
        id: 345,
        number: "345",
        title: "Morning Has Broken",
        category: "Praise & Worship",
        stanzas: [
          "1. Morning has broken like the first morning,\nBlackbird has spoken like the first bird.\nPraise for the singing! Praise for the morning!\nPraise for them, springing fresh from the Word!",
          "2. Sweet the rain's new fall sunlit from heaven,\nLike the first dewfall on the first grass.\nPraise for the sweetness of the wet garden,\nSprung in completeness where His feet pass.",
          "3. Mine is the sunlight! Mine is the morning\nBorn of the one light Eden saw play!\nPraise with elation, praise every morning,\nGod's recreation of the new day!",
        ],
      ),
      Hymn(
        id: 346,
        number: "346",
        title: "Must I Go And Empty Handed?",
        category: "Consecration & Dedication",
        refrain: "Must I go, and empty-handed?\nMust I meet my Saviour so?\nNot one soul with which to greet Him?\nMust I empty-handed go?",
        stanzas: [
          "1. Must I go and empty-handed,\nThus my dear Redeemer meet?\nNot one day of service give Him,\nLay no trophy at His feet.",
          "2. Not at death I shrink or falter,\nFor my Saviour saves me now;\nBut to meet Him empty-handed,\nThought of that now clouds my brow.",
          "3. Oh, the years of sinning wasted,\nCould I but recall them now,\nI would give them to my Saviour,\nTo His will I'd gladly bow.",
          "4. Up, ye saints, arouse, be earnest,\nUp and work while yet 'tis day;\nEre the night of death o'ertake you,\nStrive for souls while yet you may.",
        ],
      ),
      Hymn(
        id: 347,
        number: "347",
        title: "My God Loves Me",
        category: "Praise & Worship",
        stanzas: [
          "1. My God loves me, His love will never end.\nHe rests within my heart, for my God loves me.",
          "2. His gentle hand He stretches over me.\nThough storm-clouds threaten the day, He will set me free.",
          "3. He comes to me in sharing bread and wine.\nHe brings me life that will reach past the end of time.",
          "4. My God loves me, His faithful love endures.\nAnd I will live like a child held in love secure.",
          "5. The joys of love, as offerings now we bring.\nThe pains of love will be lost in the praise we sing.",
        ],
      ),
      Hymn(
        id: 348,
        number: "348",
        title: "My God, My Father, While I Stray",
        category: "Lent & Passion",
        stanzas: [
          "1. My God, my Father, while I stray\nFar from my home, on life's rough way,\nO teach me from my heart to say:\n'Thy will be done.'",
          "2. Though dark my path, and sad my lot,\nLet me be still and murmur not,\nO breathe the prayer divinely taught:\n'Thy will be done.'",
          "3. What though in lonely grief I sigh\nFor friends beloved no longer nigh,\nSubmissive would I still reply:\n'Thy will be done!'",
          "4. If Thou shouldst call me to resign\nWhat most I prize, it ne'er was mine;\nI only yield Thee what is Thine:\n'Thy will be done.'",
          "5. Let but my fainting heart be blest\nWith Thy sweet Spirit for its guest;\nMy God, to Thee I leave the rest:\n'Thy will be done.'",
        ],
      ),
      Hymn(
        id: 349,
        number: "349",
        title: "My Heart Is Full Of Joy",
        category: "Praise & Worship",
        refrain: "Praise to the Lord for I am saved,\nPraise to the Lord for saving me.\nMy heart is full of joy for in despair\nHe lifted me and gave to me\nThe joy that ever makes me whole.",
        stanzas: [
          "1. Some years gone by I've been yearning,\nIn great darkness roaming the path;\nI know not but my Saviour lifted me up.",
          "2. Out of nowhere He received me\nAnd gave to me the joy I have never seen,\nThe fairest joy that makes me whole.",
          "3. I am so glad, I am so glad,\nFor salvation has been brought down.",
        ],
      ),
      Hymn(
        id: 350,
        number: "350",
        title: "My Lord He Died",
        category: "Easter & Resurrection",
        refrain: "He has risen from His sleep,\nHe lives again, Alleluia.\nSing Alleluia, the Lord is risen,\nHe is risen, indeed, Alleluia.",
        stanzas: [
          "1. My Lord, He died for a Kingdom\nTo redeem the hearts of men.\nNow my people, don't you weep.",
          "2. My Lord came forth like the morning\nWith the splendour of the sun.\nCome triumphant from the womb,\nFrom the darkness of the tomb,\nThe vict'ry won, Alleluia.",
          "3. My Lord united our mountains\nWith the everlasting hills.\nNow the seasons and the sea\nSing His song of victory, rocks and hills, Alleluia.",
          "4. My Lord renewed all creation\nThat had waited late and long,\nNow we all with one accord\nLive and love the Risen Lord.\nThis is our song. Alleluia.",
        ],
      ),
      Hymn(
        id: 351,
        number: "351",
        title: "My People, My People",
        category: "Lent & Passion",
        refrain: "My people, my people, what have I done to you?\nOr in what way have I offended you?\nAnswer me.",
        stanzas: [
          "1. I led you, my people, out of Egypt:\nAnd for your Saviour you have a cross.",
          "2. I opened the sea before you;\nWith a lance you have opened my side.",
          "3. I fed you with manna in the desert\nAnd you have given me gall to drink.",
          "4. I gave you a royal sceptre,\nAnd you have giv'n me a crown of thorns.",
          "5. With great power I have lifted you up,\nAnd you have raised me up on this tree.\nAgios, O Theos Sanctus Deus.\nAgios Ischyros Sanctus fortis.\nAgios athanatos Sanctus immortalis\nEleison imas, miserere nobis.",
        ],
      ),
      Hymn(
        id: 352,
        number: "352",
        title: "My Prayer For You",
        category: "Praise & Worship",
        refrain: "That they may see their children's children,\nThat they may love one another,\nWe pray O Lord that they may live in peace and harmony,\nAnd (Bride's name) and (Groom's name).",
        stanzas: [
          "1. That you may see Christ Jesus as the head of your home,\nThat in your home peace will reign within,\nThat in your home the helpless may find help,\n(Bride's name) and (Groom's name).",
          "2. That the joy which we share today with you\nMay abide today and forever,\nMay it be shared with the needy around you,\n(Bride's name) and (Groom's name).",
          "3. That you may find happiness as you love yourselves;\nMay your children love you and your friends bless you,\nThat those you helped may meet you in your time of need,\n(Bride's name) and (Groom's name).",
        ],
      ),
      Hymn(
        id: 353,
        number: "353",
        title: "My Shepherd Is The Lord",
        category: "Praise & Worship",
        refrain: "My Shepherd is the Lord, nothing indeed shall I want.\nHis goodness shall follow me always to the end of my days.",
        stanzas: [
          "1. The Lord is my Shepherd, there is nothing I shall want.\nFresh and green are the pastures where He gives me repose.\nNear restful waters He leads me to revive my drooping spirit.",
          "2. He guides me along the right path, He is true to His name.\nIf I should walk in the valley of darkness, no evil would I fear;\nYou are there with Your crook and Your staff, with these You give me comfort.",
          "3. You have prepared a banquet for me in the sight of my foes.\nMy head You have anointed with oil, my cup is overflowing.",
          "4. Surely goodness and kindness shall follow me, all the days of my life.\nIn the Lord's own house shall I dwell forever and ever.",
        ],
      ),
      Hymn(
        id: 354,
        number: "354",
        title: "My Soul Doth Magnify The Lord",
        category: "Marian Hymns",
        stanzas: [
          "1. My soul doth magnify the Lord,\nAnd my spirit hath rejoiced in God, my Saviour.\nFor He that is mighty has done great things\nAnd holy is His Name.",
          "2. My soul doth magnify the Lord.\nMy soul doth magnify the Lord.",
          "3. I proclaim the power of God, He does marvels for His servants,\nThough He scatters the proud-hearted, and destroys the might of princes.",
          "4. To the hungry He gives food, sends the rich away empty.\nIn His mercy He is mindful of the people He has chosen.",
          "5. In His love He now fulfills what He promised to our Fathers.\nI will praise the Lord, my Saviour; everlasting is His Mercy.",
        ],
      ),
      Hymn(
        id: 355,
        number: "355",
        title: "My Soul Is Filled With Joy",
        category: "Marian Hymns",
        refrain: "And holy is His Name, through all generations.\nEverlasting is His mercy to the people He has chosen.\nAnd holy is His Name.",
        stanzas: [
          "1. My soul is filled with joy, as I sing to God my Saviour.\nHe has looked upon His servant, He has visited His people.",
          "2. I am lowly as a child, and I know from this day forward\nThat my name will be remembered, for all men will call me blessed.",
          "3. The world shall call me blessed, and ponder on my story.\nIn me is manifest, God's greatness and His glory.",
          "4. For those who are His friends, and keep His laws as holy,\nHis mercy never ends, and He exalts the lowly.",
          "5. But by His power the great, the proud and self-conceited,\nThe kings who sit in state are humbled and defeated.",
          "6. He feeds the starving poor, He guards His holy nation,\nFulfilling what He swore, long since in revelation.",
          "7. Then glorify with me, the Lord Who is my Saviour,\nOne Holy Trinity, forever and ever.",
        ],
      ),
      Hymn(
        id: 356,
        number: "356",
        title: "My Soul Is Longing",
        category: "Praise & Worship",
        refrain: "My soul is longing for Your peace,\nNear to You, my God.",
        stanzas: [
          "1. Lord, You know that my heart is not proud,\nAnd my eyes are not lifted from the earth.",
          "2. Lofty thoughts have never filled my mind,\nFar beyond my sight all ambitious deeds.",
          "3. In Your peace, I have maintained my soul;\nI have kept my heart in Your quiet peace.",
          "4. As a child rests on his mother's knee,\nSo I place my soul in Your loving care.",
          "5. Israel, put all your hope in God;\nPlace your trust in Him, now and evermore.",
        ],
      ),
      Hymn(
        id: 357,
        number: "357",
        title: "My Soul Now Glorify",
        category: "Marian Hymns",
        stanzas: [
          "1. My soul now glorify, the Lord Who is my Saviour.\nRejoice for who am I, that God has shown me favour.",
        ],
      ),
      Hymn(
        id: 358,
        number: "358",
        title: "My Sufferings Jesus",
        category: "Lent & Passion",
        refrain: "O Jesus Christ You suffered on the cross,\nCrucified to save a sinner me;\nO see Him bleeding, dying for me,\nO! I love You, dear Jesus mine.",
        stanzas: [
          "1. O! See the soldiers mocking Lord Jesus,\nO see the soldiers scourging Lord Jesus;\nPontius Pilate condemned Jesus to die,\nTo die a shameful death on the cross.",
          "2. Please don't tell me how you felt Mother Mary,\nYour dearest Son Jesus to behold;\nWhat bruises and pains He endureth,\nO! Mother you were so heartbroken.",
          "3. See how ruthlessly they nailed Him hands and feet,\nSee how wickedly they left Jesus to die;\nSee Him calling, weeping, sighing and dying\nOn the cross of Calvary.",
        ],
      ),
      Hymn(
        id: 359,
        number: "359",
        title: "My Times Are In Thy Hand",
        category: "Praise & Worship",
        stanzas: [
          "1. My times are in Thy hands, my God, I wish them there;\nMy life, my friends, my soul I leave entirely to Thy care.",
          "2. My times are in Thy hand, whatever they may be,\nPleasing or painful, dark or bright, as best may seem to Thee.",
          "3. My times are in Thy hand, why should I doubt or fear?\nA Father's hand will never cause His child a needless tear.",
          "4. My times are in Thy hand, Jesus the crucified;\nThe hand my cruel sins have pierced, is now my guard and guide.",
        ],
      ),
      Hymn(
        id: 360,
        number: "360",
        title: "Nearer My God To Thee",
        category: "Praise & Worship",
        stanzas: [
          "1. Nearer, my God, to Thee, nearer to Thee!\nE'en though it be a cross that raiseth me;\nStill all my song shall be: Nearer, my God, to Thee,\nNearer, my God, to Thee, nearer to Thee!",
          "2. Deep in Thy Sacred Heart, let me abide,\nThou who hast bled for me, sorrowed and died.\nSweet shall my weeping be, grief surely leading me:\nNearer, my God, to Thee, nearer to Thee!",
        ],
      ),
      Hymn(
        id: 361,
        number: "361",
        title: "New Praises Be Given",
        category: "Easter & Resurrection",
        stanzas: [
          "1. New praises be given to Christ newly crowned,\nWho back to His heaven a new way hath found.\nGod's blessedness sharing before us He goes,\nWhat mansions preparing, what endless repose!",
          "2. His glory still praising on thrice holy ground\nThe apostles stood gazing, His mother around;\nWith hearts that beat faster, with eyes full of love,\nThey watched while their Master ascended above.",
          "3. 'No star can disclose Him' the bright angels said,\n'Eternity knows Him, your conquering Head.\nThose high habitations He leaves not again, till,\nJudging all nations, on earth He shall reign.'",
          "4. Grant, Lord, that our longing may follow Thee there,\nOn earth who are thronging Thy temples with prayer.\nAnd unto Thee gather, Redeemer, Thine own,\nWhere Thou with Thy Father dost sit on the Throne.",
        ],
      ),
      Hymn(
        id: 362,
        number: "362",
        title: "No, Not One",
        category: "Praise & Worship",
        refrain: "Jesus knows all about our struggles,\nHe will guide till the day is done;\nThere's not a friend like the lowly Jesus,\nNo, not one! No, not one!",
        stanzas: [
          "1. There's not a friend like the lowly Jesus,\nNo, not one! No, not one!\nNone else could heal all our soul's diseases,\nNo, not one! No, not one!",
          "2. No friend like Him is so high and holy,\nNo, not one! No, not one!\nAnd yet no friend is so meek and lowly,\nNo, not one! No, not one!",
          "3. There's not an hour that He is not near us,\nNo, not one! No, not one!\nNo night so dark but His love can cheer us,\nNo, not one! No, not one!",
          "4. Did ever saint find this friend forsake him?\nNo, not one! No, not one!\nOr sinner find that He would not take him?\nNo, not one! No, not one!",
          "5. Was e'er a gift like the Saviour given?\nNo, not one! No, not one!\nWill He refuse us a home in heaven?\nNo, not one! No, not one!",
        ],
      ),
      Hymn(
        id: 363,
        number: "363",
        title: "No Other Plea",
        category: "Praise & Worship",
        refrain: "I need no other argument, I need no other plea,\nIt is enough that Jesus died, and that He died for me.",
        stanzas: [
          "1. My faith has found a resting place, not in device nor creed;\nI trust the ever-living One, His wounds for me shall plead.",
          "2. Enough for me that Jesus saves, this ends my fear and doubt;\nA sinful soul I come to Him, He'll never cast me out.",
          "3. My heart is leaning on the Word, the written Word of God;\nSalvation by my Saviour's Name, salvation through His blood.",
          "4. My great Physician heals the sick, the lost He came to save;\nFor me His precious blood He shed, for me His life He gave.",
        ],
      ),
      Hymn(
        id: 364,
        number: "364",
        title: "Now Thank We All Our God",
        category: "Praise & Worship",
        stanzas: [
          "1. Now thank we all our God with heart and hands and voices,\nWho wondrous things has done, in Whom His world rejoices;\nWho from our mother's arms hath blessed us on our way\nWith countless gifts of love, and still is ours today.",
          "2. O may this bounteous God through all our life be near us,\nWith ever joyful hearts and blessed peace to cheer us;\nAnd keep us in His grace, and guide us when perplexed,\nAnd free us from all ills in this world and the next.",
          "3. All praise and thanks to God the Father now be given,\nThe Son and Him who reigns with Them in highest heaven,\nThe one eternal God, Whom earth and heaven adore;\nFor thus it was, is now, and shall be evermore.",
        ],
      ),
      Hymn(
        id: 365,
        number: "365",
        title: "O Come All Ye Faithful",
        category: "Advent & Christmas",
        refrain: "O come, let us adore Him,\nO come, let us adore Him,\nO come, let us adore Him,\nChrist the Lord.",
        stanzas: [
          "1. O come all ye faithful, joyful and triumphant,\nO come ye, O come ye to Bethlehem;\nCome and behold Him, born the King of Angels.",
          "2. O virgin His mother, Son of God she beareth,\nBeareth the light who from light proceeds,\nTrue, uncreated, from all time begotten.",
          "3. Their flocks left behind them, to His lowly cradle,\nThe shepherds obedient with haste repair;\nThither with joyful footsteps we would follow.",
          "4. Star, lead the Magi, Christ their King adoring,\nGold, myrrh and incense at His feet bestow;\nWe on His birthday bring our hearts oblation.",
          "5. Sing Alleluia, all ye choirs of angels,\nSing all ye citizens of heaven above,\nAbove chanting glory in the highest.",
          "6. Yes, Lord, we greet Thee, born this happy morning,\nTo Thee O Jesus, be the glory given;\nWord of the Father, now in flesh appearing.",
        ],
      ),
      Hymn(
        id: 366,
        number: "366",
        title: "O Come And Mourn",
        category: "Lent & Passion",
        refrain: "Jesus, our Love is crucified.",
        stanzas: [
          "1. O come and mourn with me awhile;\nSee, Mary calls us to her side;\nO come and let us mourn with her.",
          "2. Have we no tears to shed for Him,\nWhile soldiers scoff and Jews deride?\nAh, look how patiently He hangs.",
          "3. How fast His feet and hands are nailed;\nHis blessed tongue with thirst is tied;\nHis failing eyes are blind with blood.",
          "4. Seven times He spoke, seven words of love;\nAnd all three hours His silence cried\nFor mercy on the souls of men.",
          "5. O break, O break, hard heart of mine;\nThe weak self-love and guilty pride;\nHis Pilate and His Judas were.",
          "6. A broken heart, a fount of tears,\nAsk, and they will not be denied;\nA broken heart love's cradle is.",
          "7. O love of God! O sin of man!\nIn this dread act your strength is tried\nAnd victory remains with love.",
        ],
      ),
      Hymn(
        id: 367,
        number: "367",
        title: "O Come, O Come Emmanuel",
        category: "Advent & Christmas",
        refrain: "Rejoice, rejoice, the child Emmanuel\nShall soon be born to save thee, Israel.",
        stanzas: [
          "1. O come, O come, Thou child Emmanuel\nTo free Thy people, captive Israel!\nFrom exile lead them home, Thou promised One so long awaited,\nGod's beloved Son.",
          "2. O come, O come, Thou shoot of Jesse's tree!\nThy downcast people from bonds set free!\nThy loved ones rescue from their deadly foe:\nSave them from evil and from every woe.",
          "3. O come and rise, Thou Dayspring in the sky!\nCome shine on us who deep in shadow lie!\nCome radiant dawn, to end sin's weary night;\nThe clouds of doom forever put to flight!",
          "4. O come, O come, Who art the Lord most high,\nWho didst of old come down on Sinai\nTo give Thy law in sight of Israel\nIn wondrous splendour, come Emmanuel.",
        ],
      ),
      Hymn(
        id: 368,
        number: "368",
        title: "O Come To The Throne",
        category: "Marian Hymns",
        refrain: "O Lady of Fatima, Hail,\nImmaculate Mother of Grace.\nO pray for us, help us today,\nThou hope of the human race.",
        stanzas: [
          "1. O come to the throne of grace,\nO come to the heart most pure,\nTo Mary our hope of life in whom salvation is sure.",
          "2. Immaculate Heart we kneel to consecrate all to thee,\nThe present, its pain and joy, the future, all it may be.",
          "3. The Rosary white and gold, we take from Thy virgin hand,\nA pledge of the power of God to heal and strengthen the land.",
        ],
      ),
      Hymn(
        id: 369,
        number: "369",
        title: "O For A Thousand Tongues",
        category: "Praise & Worship",
        stanzas: [
          "1. O for a thousand tongues to sing\nMy great Redeemer's praise,\nThe glories of my God and King,\nThe triumph of His grace. (2x)",
          "2. My gracious Master and my God,\nAssist me to proclaim,\nTo spread through all the earth abroad\nThe honours of Thy name. (2x)",
          "3. Jesus! The name that charms our fears,\nThat bids our sorrows cease;\n'Tis music in the sinner's ears,\n'Tis life and health and peace. (2x)",
          "4. He speaks and listening to His voice,\nNew life the dead receive,\nThe mournful broken hearts rejoice,\nThe humble poor believe. (2x)",
          "5. He breaks the power of cancelled sin,\nHe sets the prisoner free;\nHis blood can make the foulest clean,\nHis blood availed me. (2x)",
          "6. See all your sins on Jesus laid;\nThe Lamb of God was slain,\nHis soul was once an offering made\nFor every soul of man. (2x)",
        ],
      ),
      Hymn(
        id: 370,
        number: "370",
        title: "Offer Something To God",
        category: "Offertory",
        stanzas: [
          "1. Heavenly Father, offer something to God, offer something good to God.",
          "2. Offer Him good things.",
          "3. Offer with clear mind.",
          "4. Offer bread and wine.",
          "5. Body and Blood of Christ.",
          "6. Brother and Sister of Christ.",
          "7. He will bless us all.",
          "8. Let Him bless us all.",
          "9. Glory be to God.",
          "10. And to His Son.",
          "11. And the Spirit.",
          "12. World without end.",
        ],
      ),
      Hymn(
        id: 371,
        number: "371",
        title: "O God Almighty Father",
        category: "Praise & Worship",
        stanzas: [
          "1. O God Almighty Father, Creator of all things,\nThe heavens stand in wonder, while earth Your glory sings.\nO Most High Trinity, Undivided Unity,\nHoly God, Mighty God, God immortal be adored.",
          "2. O Jesus, Word Incarnate, Redeemer and most adored,\nAll glory, praise and honour, be Yours, our sovereign Lord.",
          "3. O God the Holy Spirit, Who lives within our soul,\nSend forth Your light and lead us to our eternal goal.",
        ],
      ),
      Hymn(
        id: 372,
        number: "372",
        title: "O God Our Help In Ages Past",
        category: "Praise & Worship",
        stanzas: [
          "1. O God our help in ages past,\nOur Hope for years to come,\nOur Shelter from the stormy blast,\nAnd our Eternal Home.",
          "2. Beneath the shadow of Thy throne\nThy saints have dwelt secure;\nSufficient is Thine arm alone,\nAnd our defence is sure.",
          "3. Before the hills in order stood,\nOr earth received her frame,\nFrom everlasting Thou art God,\nTo endless years the same.",
          "4. A thousand ages in Thy sight\nAre like an evening gone;\nShort as the watch that ends the night\nBefore the rising sun.",
          "5. Time like an ever-rolling stream,\nBears all its sons away;\nThey fly forgotten as a dream\nDies at the opening day.",
          "6. O God our Help in ages past,\nOur Hope for years to come,\nBe Thou our guard while troubles last,\nAnd our eternal home.",
        ],
      ),
      Hymn(
        id: 373,
        number: "373",
        title: "O Happy Day",
        category: "Praise & Worship",
        refrain: "Happy day, happy day, when Jesus washed my sins away!\nHe taught me how to watch and pray, and live rejoicing everyday:\nHappy day, happy day, when Jesus washed my sins away!",
        stanzas: [
          "1. O happy day that fixed my choice\nOn Thee, my Saviour and my God!\nWell may this glowing heart rejoice,\nAnd tell its raptures all abroad.",
          "2. 'Tis done, the great transaction's done:\nI am my Lord's and He is mine;\nHe drew me and I followed on,\nCharmed to confess the Voice Divine.",
          "3. Now rest my long-divided heart,\nFixed on this blissful centre rest;\nNor ever from Thy Lord depart,\nWith Him of every good possessed.",
          "4. High Heaven that heard the solemn vow,\nThat vow renewed shall daily hear;\nTill in life's latest hour I bow,\nAnd bless in death a bond so dear.",
        ],
      ),
      Hymn(
        id: 374,
        number: "374",
        title: "Oh, How Good, How Wonderful",
        category: "Entrance",
        refrain: "Oh, how good, how wonderful it is,\nWhen brothers and sisters live as one;\nOh, how good, how wonderful it is,\nWhen brothers and sisters live as one.",
        stanzas: [
          "1. It is as fragrant as pure oil, the ointment of the Lord,\nFlowing down as on Aaron of old, anointing everyone.",
          "2. It is as refreshing as the dew upon the mountain of the Lord,\nFor there the favour of the Lord remains, the blessing of everlasting life.",
        ],
      ),
      Hymn(
        id: 375,
        number: "375",
        title: "Oh King Of Might And Splendour",
        category: "Offertory",
        stanzas: [
          "1. Oh King of might and splendour, Creator most adored!\nThis sacrifice we render to Thee as sovereign Lord.\nMay these, our gifts, be pleasing unto Thy majesty,\nMankind from sin releasing who have offended Thee.",
          "2. Thy body Thou hast given, Thy blood Thou hast outpoured\nThat sin might be forgiven, O Jesus, loving Lord.\nAs now with love most tender, Thy death we celebrate,\nOur lives in self-surrender to Thee we consecrate.",
          "3. We come to bow down to Thy Eucharistic Child;\nWe come to salute Thee, the Lord's undefiled.",
          "4. We plead for relief from our burdens of pain;\nNone kneels to thee, Mother of Mercy, in vain.",
          "5. A well-spring of life to thy children afford;\nOf grace thou art full, and with thee is the Lord.",
        ],
      ),
      Hymn(
        id: 376,
        number: "376",
        title: "Oh Lady Of Lourdes",
        category: "Marian Hymns",
        refrain: "Ave, Ave, Ave Maria.\nAve, Ave, Ave Maria.",
        stanzas: [
          "1. Oh Lady of Lourdes, hark, we call upon thee,\nFrom the lands of the earth and the isles of the sea.",
          "2. The saint and the sinner, the sick and the strong,\nImmaculate Mary, to hail thee we throng.",
          "3. Clear day-star illumine our pilgrimage way,\nAnd lead us all homeward, who love thine Ave.",
        ],
      ),
      Hymn(
        id: 377,
        number: "377",
        title: "Oh, Oh, Oh, How Good Is The Lord",
        category: "Praise & Worship",
        refrain: "Oh, oh, oh, how good is the Lord!\nOh, oh, oh, how good is the Lord!\nOh, oh, oh, how good is the Lord!\nI never will forget what He has done for me.",
        stanzas: [
          "1. He gives me salvation, I never will forget what He has done for me.",
          "2. He gives me His blessing, I never will forget what He has done for me.",
          "3. He gives me His Spirit, I never will forget what He has done for me.",
          "4. He gives me His healing, I never will forget what He has done for me.",
          "5. He gives me His glory, I never will forget what He has done for me.",
        ],
      ),
      Hymn(
        id: 378,
        number: "378",
        title: "Oh When The Saints Go Marching In",
        category: "Praise & Worship",
        refrain: "Oh when the saints go marching in,\nOh when the saints go marching in,\nLord I want to be in that number,\nWhen the saints go marching in.",
        stanzas: [
          "1. Oh when the sun refuses to shine, (2)\nLord I want to be in that number,\nWhen the sun refuses to shine.",
          "2. Oh when the drums begin to bang, (2)\nLord I want to be in that number,\nWhen the drums begin to bang.",
          "3. Oh when the stars fall from the sky, (2)\nLord I want to be in that number,\nWhen the stars fall from the sky.",
          "4. Oh when the moon turns into blood, (2)\nLord I want to be in that number,\nWhen the moon turns into blood.",
          "5. Oh when the sun turns into fire, (2)\nLord I want to be in that number,\nWhen the sun turns into fire.",
          "6. Oh when the fires begin to blaze, (2)\nLord I want to be in that number,\nWhen the fires begin to blaze.",
          "7. Oh when the Lord calls out the names, (2)\nLord I want to be in that number,\nWhen the Lord calls out the names.",
        ],
      ),
      Hymn(
        id: 379,
        number: "379",
        title: "O! I Often Sit And Ponder",
        category: "Praise & Worship",
        stanzas: [
          "1. O! I often sit and ponder when the sun is sinking low.\nWhere shall yonder future find me? None but God in Heaven know.\nShall I be among the living? Shall I mingle with the free?\nWheresoever my path be leading, Saviour keep my heart with Thee.\nOh, the future lies before me, and I know not where I'll be,\nBut where'er my path be leading, Saviour keep my heart with Thee. (2)",
          "2. Shall I be at work with Jesus, whilst He leads me by the hand,\nAnd to those around be saying: Come and join this happy band,\nCome for all things now are ready, come His faithful followers be;\nOh, where'er my path be leading, Saviour keep my heart with Thee.",
          "3. But perhaps my work for Jesus soon in future may be done,\nAll my earthly trials ended, and my crown in heaven won.\nThen forever with the ransomed thro' eternity I'd be,\nChanting hymns to Him who bought me with His bloodshed on the tree.",
        ],
      ),
      Hymn(
        id: 380,
        number: "380",
        title: "O Jesus Christ Remember",
        category: "Adoration & Eucharist",
        stanzas: [
          "1. O Jesus Christ remember, when Thou shalt come again,\nUpon the clouds of heaven, with all Thy shining train.\nWhen every eye shall see Thee in deity revealed,\nWho now upon this altar in silence art concealed.",
          "2. Remember then, O Saviour I supplicate of Thee,\nThat here I bowed before Thee upon my bended knee.\nThat here I owned Thy presence, and did not Thee deny,\nAnd glorified Thy greatness though hid from human eye.",
          "3. Accept, divine Redeemer, the homage of my praise.\nBe Thou the light and honour and glory of my days.\nBe Thou my consolation when death is drawing nigh;\nBe Thou my only treasure through all eternity.",
        ],
      ),
      Hymn(
        id: 381,
        number: "381",
        title: "O Jesus We Adore Thee",
        category: "Adoration & Eucharist",
        refrain: "O Sacrament, most Holy,\nO Sacrament divine!\nAll praise and all thanksgiving\nBe every moment Thine.",
        stanzas: [
          "1. O Jesus, we adore Thee, who in Thy love divine\nConceal Thy mighty Godhead in forms of bread and wine.",
          "2. O Jesus, we adore Thee, our Victim and our Priest,\nWhose precious blood and body, become our Sacred Feast.",
          "3. O Jesus, we adore Thee, our Saviour and our King!\nAnd with the saints and angels a humble homage bring.",
          "4. O Jesus, we adore Thee, come live in us, we pray,\nThat all our thoughts and actions be Thine alone today.",
          "5. O come all you who labour, in sorrow and in pain,\nCome eat this bread from heaven, your peace and strength regain.",
        ],
      ),
      Hymn(
        id: 382,
        number: "382",
        title: "O Lady Full Of God's Own Grace",
        category: "Marian Hymns",
        refrain: "Oh virgin fair, star of the sea!\nMy dearest mother, pray for me.",
        stanzas: [
          "1. O Lady full of God's own grace whose caring hands the child embraced,\nWho listened to the Spirit's word, believed and trusted in the Lord.",
          "2. O Lady who felt daily joy in caring for the Holy Boy,\nWhose home was plain and shorn of wealth, yet was enriched by God's own breath.",
          "3. O Lady who bore living pain but still believed that love would reign,\nWho on a hill watched Jesus die as on the Cross they raised Him high.",
          "4. O Lady who on Easter day had all your sorrow wiped away,\nAs God the Father's will was done, when from death's hold He freed your Son.",
        ],
      ),
      Hymn(
        id: 383,
        number: "383",
        title: "Old Rugged Cross",
        category: "Lent & Passion",
        refrain: "So I'll cherish the Old Rugged Cross,\nTill my trophies at last I lay down;\nI will cling to the Old Rugged Cross,\nAnd exchange it someday for a crown.",
        stanzas: [
          "1. On a hill far away, stood an old rugged Cross,\nThe emblem of suffering and shame;\nAnd I love that Old Cross, where the dearest and best,\nFor a world of lost sinners was slain.",
          "2. In that Old Rugged Cross, so despised by the world,\nHas a wondrous attraction for me;\nFor the dear Lamb of God left His glory above,\nTo bear it to dark Calvary.",
          "3. In the Old Rugged Cross, stained with blood so divine,\nA wondrous beauty I see;\nFor 'twas on that Old Cross, Jesus suffered and died,\nTo pardon and sanctify me.",
          "4. To the Old Rugged Cross, I will ever be true,\nIts shame and reproach gladly bear;\nThen He'll call me someday to my home far away,\nWhere His glory forever I'll share.",
        ],
      ),
      Hymn(
        id: 384,
        number: "384",
        title: "O Little Town Of Bethlehem",
        category: "Advent & Christmas",
        stanzas: [
          "1. O little town of Bethlehem, how still we see thee lie!\nAbove thy deep and dreamless sleep the silent stars go by;\nYet in the dark street shineth the everlasting light;\nThe hopes and fears of all the years are met in thee tonight.",
          "2. For Christ is born of Mary, and gathered all above,\nWhile mortals sleep, the angels keep their watch of wondering love.\nO morning stars, together proclaim the holy birth,\nAnd praises sing to God the King, and peace to men on earth.",
          "3. How silently, how silently the wondrous gift is given!\nSo God imparts to human hearts the blessing of His heaven.\nNo ear may hear His coming, but in this world of sin,\nWhere meek souls will receive Him, still the dear Christ enters in.",
        ],
      ),
      Hymn(
        id: 385,
        number: "385",
        title: "Lord, I Am Not Worthy",
        category: "Communion",
        stanzas: [
          "1. O Lord, I am not worthy, that You should come to me.\nBut speak the words of comfort, my spirit healed shall be.",
          "2. O come all you who labour, in sorrow and in pain,\nCome, eat this bread from heaven, your peace and strength regain.",
          "3. O Sacrament most holy! O Sacrament divine!\nAll praise and all thanksgiving be every moment Thine.",
        ],
      ),
      Hymn(
        id: 386,
        number: "386",
        title: "O Lord My God (How Great Thou Art)",
        category: "Praise & Worship",
        refrain: "Then sings my soul, my Saviour God to Thee:\nHow great Thou art! How great Thou art!\nThen sings my soul, my Saviour God to Thee:\nHow great Thou art! How great Thou art!",
        stanzas: [
          "1. O Lord my God, when I in awesome wonder,\nConsider all the works Thy hand hath made;\nI see the stars, I hear the mighty thunder,\nThy power throughout the universe displayed.",
          "2. When through the woods and forest glades I wander,\nAnd hear the birds sing sweetly in the trees;\nWhen I look down from lofty mountain grandeur,\nAnd hear the brook and feel the gentle breeze.",
          "3. When Christ shall come with shouts of acclamation,\nAnd take me home, what joy will fill my heart!\nThen I shall bow in humble adoration,\nAnd there proclaim: My God how great Thou art!",
          "4. When burdens press and seem beyond endurance,\nBowed with grief, to Him I lift my face;\nAnd then in love He brings me sweet assurance:\n'My child for thee sufficient is my grace.'",
        ],
      ),
      Hymn(
        id: 387,
        number: "387",
        title: "O Lord Our God",
        category: "Praise & Worship",
        refrain: "O Lord our God, we lift up our hearts to You,\nO Lord our God, Your people rejoice in You.",
        stanzas: [
          "1. Stone of this age, Father and Maker,\nFather of mercy, we lift up our hearts to You.",
          "2. God of the living, God of all people,\nFather of life, we lift up our hearts to You.",
          "3. Lord of creation, Lord of the universe,\nFather of man, we lift up our hearts to You.",
          "4. God of the hopeless, God of the least,\nFather of love, we lift up our hearts to You.",
        ],
      ),
      Hymn(
        id: 388,
        number: "388",
        title: "My People What Have I Done To You?",
        category: "Lent & Passion",
        refrain: "O My people, what have I done to you?\nHave I hurt you? Answer Me.",
        stanzas: [
          "1. I led you out of Egypt from slavery, I set you free;\nI brought you into a land of promise,\nYou have prepared a cross for Me.",
          "2. I led you as a shepherd, I brought you safely through the sea;\nFed you with manna in the desert,\nYou have prepared a cross for Me.",
          "3. I fought for you in battles, I won you strength and victory;\nGave you a royal crown and sceptre,\nYou have prepared a cross for Me.",
          "4. I planted you, My vineyard, and cared for you most tenderly;\nLooked for abundant fruit, and found none,\nOnly the cross you made for Me.",
          "5. Then listen to My pleading, and do not turn away from Me;\nYou are My people, will you reject Me?\nFor you I suffer bitterly.",
        ],
      ),
      Hymn(
        id: 389,
        number: "389",
        title: "Once In Royal David's City",
        category: "Advent & Christmas",
        stanzas: [
          "1. Once in royal David's city, stood a lowly cattle shed,\nWhere a mother laid her baby in a manger for His bed.\nMary was that mother mild, Jesus Christ her little child.",
          "2. He came down to earth from heaven who is God and Lord of all,\nAnd His shelter was a stable, and His cradle was a stall.\nWith the poor and mean and lowly, lived on earth our Saviour holy.",
          "3. And through all His wondrous childhood, He would honour and obey,\nLove and watch the lowly maiden in whose gentle arms He lay.\nChristian children all must be mild, obedient, good as He.",
          "4. For He is our childhood's pattern, day by day like us He grew,\nHe was little, weak and helpless, tears and smiles like us He knew.\nAnd He feeleth for our sadness, and He shareth in our gladness.",
          "5. And our eyes at last shall see Him through His own redeeming love,\nFor that child so dear and gentle, is our Lord in heaven above.\nAnd He leads His children on to the place where He is gone.",
          "6. Not in that poor lowly stable, with the oxen standing by,\nWe shall see Him, but in heaven, set at God's right hand on high;\nWhen like stars His children crowned, all in white shall wait around.",
        ],
      ),
      Hymn(
        id: 390,
        number: "390",
        title: "Once More My Soul",
        category: "Consecration & Dedication",
        refrain: "I will (3) God helping me, I will, O Lord, be Thine;\nThy precious blood was shed to purchase me, I will be wholly Thine.",
        stanzas: [
          "1. Once more my soul, thy Saviour through Thy word, is offered full and free.\nAnd now, O Lord, I must, I must decide: Shall I accept of Thee?",
          "2. By grace I will Thy mercy now receive, Thy love my heart hath won.\nIn Thee, O Christ, I will, I will believe and trust in Thee alone.",
          "3. Thou knowest, Lord, how very weak I am, and how I fear to stray;\nFor strength to serve, I look to Thee alone, that strength You must supply.",
        ],
      ),
      Hymn(
        id: 391,
        number: "391",
        title: "On Jordan's Bank",
        category: "Advent & Christmas",
        stanzas: [
          "1. On Jordan's bank the Baptist's cry\nannounces that the Lord is nigh.\nCome then and hearken, for he brings\nglad tidings from the King of Kings.",
          "2. Then cleansed be every Christian breast\nand furnished for so great a guest\nYea! let us each our hearts prepare\nfor Christ to come and enter there.",
          "3. For Thou art our salvation, Lord,\nour refuge and our great reward\nWithout Thy grace our souls must fade,\nand wither like a flower decayed.",
        ],
      ),
      Hymn(
        id: 392,
        number: "392",
        title: "Open Up Your Hearts",
        category: "Entrance & Gathering",
        stanzas: [
          "1. Open up your hearts and let the Lord come in. (3)\nOffer yourself to the Lord.",
          "2. God is our Father so come on in. (3)\nOffer yourself to the Lord.",
          "3. Sing His praises, come on in. (3)\nOffer yourself to the Lord.",
        ],
      ),
      Hymn(
        id: 393,
        number: "393",
        title: "Open Your Ears",
        category: "Praise & Worship",
        refrain: "God has spoken to His people, alleluia!\nAnd His words are words of wisdom, alleluia.",
        stanzas: [
          "1. Open your ears, O Christian people!\nOpen your ears and hear Good News!\nOpen your hearts, O royal priesthood!\nGod has come to you.",
          "2. Israel comes to greet the Saviour\nJudah is glad to see his day.\nFrom east and west the peoples travel.\nHe will show the way.",
          "3. He who has ears to hear His message,\nHe who has ears, then let him hear.\nHe who would learn the way of wisdom,\nlet him hear God's words.",
        ],
      ),
      Hymn(
        id: 394,
        number: "394",
        title: "O Purest Of Creatures",
        category: "Marian Hymns",
        stanzas: [
          "1. O purest of creatures! Sweet mother, sweet maid!\nthe one spotless womb wherein Jesus was laid.\nDark night hath come down on us Mother and we\nlook out for thy shining, sweet star of the sea.",
          "2. Deep night hath come down on this rough spoken world\nand the banners of darkness are boldly unfurled.\nAnd the tempest-tossed Church all her eyes are on thee.\nThey look to thy shining, sweet star of the sea.",
          "3. He gazed on thy soul. It was spotless and fair.\nFor the empire of sin it had never been there.\nNone ever had owned thee, dear mother, but He,\nAnd He blessed thy clear shining, sweet star of the sea.",
          "4. Hail Juda's virgin daughter hail!\nthou masterpiece of grace.\nO help us in this wretched vale,\nwhere combat never cease.",
          "5. Thou art all fair and beautiful.\nThere is no spot in thee.\nO make thy children dutiful\nlovers of purity.",
          "6. And when our exile here is o'er\nand pain and sorrow cease.\nWith Mary we shall overcome,\nrejoice in endless peace.",
        ],
      ),
      Hymn(
        id: 395,
        number: "395",
        title: "O That A Seraph's Voice",
        category: "Marian Hymns",
        stanzas: [
          "1. O that a seraph's voice divine\ncould speak to us thy Holy praise.\nAnd tell what glory in thee shine\nthrough all thy saintly wondrous ways.",
        ],
      ),
      Hymn(
        id: 396,
        number: "396",
        title: "O The Love Of My Lord",
        category: "Communion & Eucharist",
        stanzas: [
          "1. Oh, the love of my Lord is the essence of all that I love here on earth.\nAll the beauty I see He has given to me.\nAnd His giving is gentle as silence.",
          "2. Everyday, every hour, every moment, have been blessed by the strength of His love.\nAt the turn of each tide He is there at my side.\nAnd His touch is as gentle as silence.",
          "3. There've been times when I've turned from His presence.\nAnd I've walked other paths, other ways.\nBut I've called on His name in the dark of my shame.\nAnd His mercy was gentle as silence.",
          "4. Meet Him here everybody at this banquet\nwhich His loving heart makes for His friends.\nHere He gives all He has, body, blood, strength to serve.\nAnd His love is as gentle as silence.",
        ],
      ),
      Hymn(
        id: 397,
        number: "397",
        title: "O The Word Of My Lord",
        category: "Word of God & Guidance",
        refrain: "Oh, the word of my Lord, deep within my being.\nOh, the word of my Lord.",
        stanzas: [
          "1. Before I formed you in the womb, I knew you through and through\nI chose you to be Mine. Before you left your mother's side\nI called to you, My child, to be My sign.",
          "2. I know that you are very young, but I will make you strong.\nI'll fill you with my words.\nAnd you will travel through the land,\nfulfilling my command, which you have heard.",
          "3. And everywhere you are to go, My hand will follow you.\nYou will not be alone, In all the danger that you fear\nyou'll find me very near, your words my own.",
          "4. With all my strength you will be filled.\nYou will destroy and build. For that is My design.\nYou will create and overthrow. Reap harvest I will sow.\nYour word is Mine.",
        ],
      ),
      Hymn(
        id: 398,
        number: "398",
        title: "Our God Is A God Of Love",
        category: "Praise & Worship",
        refrain: "Joy, joy is all around us.\nJoy, joy is everywhere.\nJoy, joy is all around us.\nJoy, joy is everywhere.",
        stanzas: [
          "1. Our God is a God of love. (2)\nOur God is a God of peace. (2)\nOur God is a God of mercy. (2)\nCome, let us praise God. (2)",
          "2. Jesus is the Son of God. (2)\nJesus is the prince of peace. (2)\nJesus is the Lord of Lords. (2)\nCome, let us praise God. (2)",
          "3. We rejoice in the Holy Spirit. (2)\nGod in us and we in God. (2)\nWe rejoice in the Holy Spirit. (2)\nCome, let us praise God. (2)",
        ],
      ),
      Hymn(
        id: 399,
        number: "399",
        title: "Out Of My Bondage",
        category: "Penitential & Lent",
        stanzas: [
          "1. Out of my bondage sorrow and night,\nJesus I come, Jesus I come,\ninto Thy freedom gladness and light,\nJesus I come to Thee.\nOut of my sickness into Thy health,\nout of my want and to Thy wealth,\nOut of my sin and into Thyself,\nJesus I come to Thee.",
          "2. Out of my shameful failure and loss,\nJesus I come, Jesus I come\nInto Thy glorious gain of the cross,\nJesus I come to Thee.\nOut of Earth's sorrow into Thy balm,\nOut of life's storms and into Thy calm,\nOut of distress to Jubilant psalm,\nJesus I come to Thee.",
          "3. Out of un-rest and arrogant pride,\nJesus I come (2x)\nInto Thy blessed will to abide,\nJesus I come to Thee.\nOut of myself to dwell in Thy love,\nUpward for aye on wings like a dove,\nJesus I come to Thee.",
          "4. Out of the fear and dread of the tomb,\nJesus I come (2x)\nInto the joy I come to Thee.\nOut of the depths of ruin untold,\nEver Thy glorious face to behold,\nJesus I come to Thee.",
        ],
      ),
      Hymn(
        id: 400,
        number: "400",
        title: "O What More",
        category: "Communion & Eucharist",
        stanzas: [
          "1. O what could my Jesus do more! could my Jesus do more!\nO what greater blessing impart!\nO silence my soul and adore, and praise Him still nearer Thy heart.\n'Tis here from my labours I'll rest, since it makes my heart His abode\nTo Him all my care I'll address and speak to the heart of my God. (2)",
          "2. In life and in death Thou art mine My Saviour,\nI am sealed with Thy blood, till eternity on me doth shine.\nI'll live on the flesh of my God.\nIn Jesus' triumph I'll live, In Jesus' triumph I'll die\nThe terror of death calmly brave, in His bosom breathe out my last sigh. (2)",
        ],
      ),
      Hymn(
        id: 401,
        number: "401",
        title: "O Worship The King",
        category: "Praise & Worship",
        stanzas: [
          "1. O worship the King, all glorious above,\nO gratefully sing His power and His love;\nOur shield and defender, the Ancient of Days,\npavilioned in splendour, and girded with praise.",
          "2. O tell of His might! O sing of His grace\nWhose robe is the light, Whose canopy space.\nHis chariots of wrath the deep thunder-clouds form,\nAnd dark is His path on the wings of the storm.",
          "3. This earth, with its store of wonders untold,\nAlmighty Thy power hath founded of old;\nHath 'stablished it fast by a changeless decree,\nAnd round it hath cast, like a mantle, the sea.",
          "4. Thy bountiful care what tongue can recite?\nIt breathes in the air, It shines in the light;\nIt streams from the hills, It descends to the plain,\nIt sweetly distills in the dew and the rain.",
          "5. Frail children of dust, and feeble as frail,\nIn Thee do we trust, nor find Thee to fail;\nThy mercies, how tender! How firm to the end!\nOur Maker, Defender, Redeemer, and Friend.",
        ],
      ),
      Hymn(
        id: 402,
        number: "402",
        title: "O Yes Jesus Lives",
        category: "Easter & Resurrection",
        refrain: "Oh yes, Lord Jesus lives. Oh yes, Lord Jesus lives. Alle, Alle, Alleluia. (2)",
        stanzas: [
          "1. Mary ran to tell the good news:\nThe Lord is risen. The Lord is risen. Alle, Alle, Alleluia.\nPeter and John ran to the tomb:\nThe Lord is risen. The Lord is risen. Alle, Alle, Alleluia.",
          "2. The earth sings out in praise:\nThe Lord is risen. The Lord is risen. Alle, Alle, Alleluia.\nGlad songs fill our days:\nThe Lord is risen. The Lord is risen. Alle, Alle, Alleluia.",
        ],
      ),
      Hymn(
        id: 403,
        number: "403",
        title: "Pass Me Not",
        category: "Penitential & Lent",
        refrain: "Saviour, Saviour, Saviour,\nhear my humble cry.\nAnd while others Thou art calling,\ndo not pass me by.",
        stanzas: [
          "1. Pass me not, O gentle Saviour,\nHear my humble cry.\nWhile on others Thou art calling,\ndo not pass me by.",
          "2. Let me at the throne of mercy\nfind a sweet relief.\nKneeling there in deep contrition,\nhelp my unbelief.",
          "3. Trusting only in Thy merit,\nwould I seek Thy face.\nHeal my wounded, broken spirit.\nSave me by Thy grace.",
          "4. Thou the spring of all my comfort,\nmore than life to me!\nWhom have I on earth beside Thee?\nWhom in heaven but Thee?",
        ],
      ),
      Hymn(
        id: 404,
        number: "404",
        title: "Peace I Leave With You",
        category: "Peace & Unity",
        refrain: "Peace I leave with you My friends.\nPeace the world cannot give.\nPeace I leave with you My friends,\nso that your joy be ever full.",
        stanzas: [
          "1. If you remain in Me,\nMy words remain in you.",
          "2. As the Father has loved Me so\nI love you.",
          "3. A man can have no greater love\nthan to lay down his life for his friends.",
          "4. You are My friends if you do\nwhat I command you.",
          "5. I call you friends because I have made known to you\neverything I have learned from the Father.",
        ],
      ),
      Hymn(
        id: 405,
        number: "405",
        title: "Peace Is Flowing Like A River",
        category: "Peace & Unity",
        stanzas: [
          "1. Peace is flowing like a river,\nflowing out from you and me,\nflowing out into the desert,\nsetting all the captives free.",
          "2. Joy is flowing like a river,\nflowing out from you and me,\nflowing out into the desert,\nsetting all the captives free.",
          "3. Love is flowing like a river,\nflowing out from you and me,\nflowing out into the desert,\nsetting all the captives free.",
          "4. Christ is flowing like a river,\nflowing out from you and me,\nflowing out into the desert,\nsetting all the captives free.",
        ],
      ),
      Hymn(
        id: 406,
        number: "406",
        title: "Peace Perfect Peace",
        category: "Peace & Unity",
        stanzas: [
          "1. Peace perfect peace\nis the gift of Christ, Our Lord. (2)\nThus says the Lord will the world know My friends.\nPeace perfect peace\nis the gift of Christ our Lord.",
          "2. Love perfect love\nis the gift of Christ, Our Lord. (2)\nThus says the Lord will the world know My friends.\nLove perfect love\nis the gift of Christ our Lord.",
          "3. Faith perfect faith\nis the gift of Christ, Our Lord. (2)\nThus says the Lord will the world know My friends.\nFaith perfect faith\nis the gift of Christ our Lord.",
          "4. Hope perfect hope\nis the gift of Christ, Our Lord. (2)\nThus says the Lord will the world know My friends.\nHope perfect hope\nis the gift of Christ our Lord.",
          "5. Joy perfect joy\nis the gift of Christ, Our Lord. (2)\nThus says the Lord will the world know My friends.\nJoy perfect joy\nis the gift of Christ our Lord.",
        ],
      ),
      Hymn(
        id: 407,
        number: "407",
        title: "Peacetime",
        category: "Peace & Unity",
        refrain: "Peace time, peace time, time for making peace.\nPeace time, peace time, Time for saying I forgive.\nTime for saying I love you.\nTime to live as friends.",
        stanzas: [
          "1. Happy are they who are makers of peace.\nHappy are they who forgive.\nHappy are they who know how to love.\nThey are sons and daughters of God.",
          "2. Happy are they who are gentle of heart.\nHappy are all those who care.\nHappy are those who seek the good of all.\nThey are close to God's heart.",
        ],
      ),
      Hymn(
        id: 408,
        number: "408",
        title: "Praise The Lord",
        category: "Praise & Worship",
        refrain: "Praise the Lord (3) for His kindness.\nPraise the Lord for His good works.\nPraise the Lord for His mercy, and with a true heart believe,\nwhatever conditions be, Jesus will save His people.\nPraise the Lord.",
        stanzas: [
          "1. In sorrow or in great joy, praise the Lord.\nIn sorrow or great pain, praise the Lord.\nIn poverty or richness, praise the Lord.\nGod is calling you to come: praise the Lord.",
          "2. For your riches and your wealth, praise the Lord.\nFor plenty or scarcity, praise the Lord.\nFor giving children to you, praise the Lord.\nFor ever our childless homes, praise the Lord.",
          "3. For homely dwelling places, praise the Lord.\nWhere childhood's visions linger, praise the Lord.\nFor friends and kindly voices, praise the Lord.\nFor bread to stay our hunger, praise the Lord.",
          "4. For sleep to bring us ease, praise the Lord.\nFor zeal and cost of living, praise the Lord.\nFor faith and understanding, praise the Lord.\nFor hope of peace unending, praise the Lord.",
        ],
      ),
      Hymn(
        id: 409,
        number: "409",
        title: "Praise The Lord And Sing",
        category: "Praise & Worship",
        refrain: "Praise the Lord and sing,\nalleluia, alleluia, alleluia. (2)",
        stanzas: [
          "1. Praise Him in the morning,\nPraise Him in the night.\nAlleluia, alleluia -a -a.\nPraise Him in the evening.\nPraise Him in the noon.\nAlleluia, alleluia.",
          "2. Praise Him for the moon and for the stars above.\nAlleluia, alleluia.\nPraise Him for the sun and praise Him for the sky.\nAlleluia, alleluia.",
          "3. Praise Him for His goodness.\nPraise Him for His gifts.\nAlleluia, alleluia.\nPraise Him for His mercy.\nPraise Him for His love.\nAlleluia, alleluia.",
          "4. Praise Him when you're happy.\nPraise Him when You're sad.\nAlleluia, alleluia.\nHe's the God Who made us and His message makes us glad.\nAlleluia, alleluia.",
        ],
      ),
      Hymn(
        id: 410,
        number: "410",
        title: "Praise The Trinity",
        category: "Trinity",
        refrain: "Praise the Trinity, glorious Trinity.\nCome in God's presence rejoicing with singing,\nextolling His glorious name. (2)",
        stanzas: [
          "1. Come all ye people: This is the day of the Lord.\nGreat and mighty is Yahweh, greatly and mightily praised.",
          "2. Praise to the Father. He dwells in Israel's praise,\nbringing deliverance and freedom to all who delight in His ways.",
          "3. Praise be to Jesus, Who loved not His life unto death\nBy His blood He redeemed us. His love we will never forget.",
          "4. Praise-to the Spirit, the gift of the Father above,\nHe has filled us with boldness, power and victory and love.",
          "5. We are the family of Yahweh. We are His very own.\nEnter the Holy of Holies in worship before His throne.",
        ],
      ),
      Hymn(
        id: 411,
        number: "411",
        title: "Praise To The Holiest",
        category: "Praise & Worship",
        stanzas: [
          "1. Praise to the holiest in the height.\nAnd in the depth be praised.\nIn all His works most wonderful,\nmost sure in all His ways.\n\nO loving wisdom of our God,\nwhen all was sin and shame,\na second Adam to the fight,\nand to the rescue came.",
          "2. O wisest love, that flesh and blood\nwhich did in Adam fail,\nshould strive afresh against their foe.\nShould strive and should prevail.",
          "3. And that a higher gift than grace\nshould flesh and blood refine,\nGod's presence and His very Self,\nand essence all divine.",
          "4. O generous love that He who smote\nin man for man the foe\nThe double agony in man for man\nshould undergo.",
          "5. And in the garden secretly,\nand on the cross on high,\nshould teach His brethren and\ninspire to suffer and to die.",
        ],
      ),
      Hymn(
        id: 412,
        number: "412",
        title: "Praise To The Lord",
        category: "Praise & Worship",
        refrain: "Praise to the Lord. Praise to the Lord, Praise Him for His wonderful work.\nPraise to the Lord. Praise to the Lord. Praise His surpassing greatness.\nPraise to the Lord, Praise Him always now, forever more.",
        stanzas: [
          "1. Praise Him all ye sons of men.\nPraise Him all ye fruits in the fields.\nPraise Him all ye birds in the sky\nPraise Him now and forever more.",
          "2. Praise Him all ye animals.\nPraise Him all fish in water.\nPraise Him all ye crawling things.",
          "3. Praise Him all ye living things\nPraise Him all ye stars in the sky.\nPraise Him all ye planets. Praise Him now and forever more.",
          "4. Praise Him all ye earthly things.\nPraise Him all things in heaven.\nPraise Him all firmaments.\nPraise Him now and forever more.",
        ],
      ),
      Hymn(
        id: 413,
        number: "413",
        title: "Praise To The Lord (2)",
        category: "Praise & Worship",
        stanzas: [
          "1. Praise to the Lord the Almighty the king of creation,\nOh my soul praise him for he is our help and salvation.\nAll you who hear, now to his, temple draw near\nJoin in profound adoration.",
          "2. Praise to the Lord let us offer our gifts at the Altar,\nLet not our sins and our offences now cause us to falter\nChrist the high priest bids us all join in his feast,\nvictims with him at the altar.",
          "3. Praise to the Lord Oh let all that is in us adore him\nall that has life and breath come now rejoicing before him\nlet the amen sound from his people again,\nas we here worship before him.",
        ],
      ),
      Hymn(
        id: 414,
        number: "414",
        title: "Precious Lord",
        category: "Prayer & Petition",
        stanzas: [
          "1. Precious Lord, take my hand lead me on.\nLet me stand, I am tired.\nI am weak, I am worn.\nThru the storm, thru the night\nlead me on to the bright light:\nTake my hand, precious Lord, lead me home.",
          "2. When my way grows drear precious Lord linger near.\nWhen my life is almost gone, hear my cry, hear my call.\nHold my hand lest I fall.\nTake my hand, precious Lord, Lead me home.",
          "3. When the darkness appears and the night draws near,\nand the day is past and gone, at the river I stand.\nGuide my feet, hold my hand.\nTake my hand, precious Lord. Lead me home.",
        ],
      ),
      Hymn(
        id: 415,
        number: "415",
        title: "Prepare Me",
        category: "Penitential & Lent",
        refrain: "Prepare me, prepare me, my Lord, prepare me, Lord, O God:\nPrepare me, O Lord, may You set me free.",
        stanzas: [
          "1. From the snare of the devil I beg You, O Lord,\nO Lord may You set me free.\nFrom the willful sin, I ask You, O Lord,\nO Lord may You set me free.",
          "2. And here I stand before You, O Lord,\nO Lord, may You set me free.\nRedeemed outright from sin and strife,\nO Lord, may You set me free.",
        ],
      ),
      Hymn(
        id: 416,
        number: "416",
        title: "Priestly People",
        category: "Praise & Worship",
        refrain: "Priestly people, kingly people, holy people, God's chosen people, give praise to the Lord.",
        stanzas: [
          "1. We sing to You, O Christ, beloved Son of the Father.\nWe give you praise, O wisdom everlasting and Word of God.",
          "2. We sing to You, O Son, born of Mary the Virgin.\nWe give you praise, Our Brother born to heal us, our Saving Lord.",
          "3. We sing to You, O brightness of splendour and glory.\nWe give You praise, O Morning Star announcing the coming day.",
          "4. We sing to You, O Light, bringing men out of darkness.\nWe give You praise, O guiding Light Who shows us the way to heaven.",
          "5. We sing to You, O Messiah, foretold by the prophet.\nWe give You praise, O Son of David and Son of Abraham.",
          "6. We sing to You, O Messiah, the Hope of the people.\nWe give You praise, O Christ our Lord and King, humble, meek of heart.",
          "7. We sing to you, the Way to the Father in heaven.\nWe give you praise, the Way of Truth, and Way of all grace and light.",
        ],
      ),
      Hymn(
        id: 417,
        number: "417",
        title: "Reach Out",
        category: "Love & Charity",
        refrain: "Reach out (2), My brothers and sisters reach out in giving and sharing.\nBelieving and caring.\nReach out together, reach out.",
        stanzas: [
          "1. Reach out to God in Your life.\nLet Jesus come into your lives.\nHe lives; He is risen.\nHis Spirit is with us.\nReach out together, reach out.",
          "2. Reach out to others in need.\nReach out to all others in need.\nSo many are hurting.\nSo many are lonely.\nReach out together.\nReach out.",
          "3. Let us reach out to ourselves.\nCome, let us reach out to ourselves.\nIn praying and sharing in trusting and caring,\nreach out together, reach out.",
        ],
      ),
      Hymn(
        id: 418,
        number: "418",
        title: "Reap Me The Earth",
        category: "Offertory & Gifts",
        refrain: "Bring bread, bring wine.\nGive glory to the Lord,\nWhose is the earth but God's Whose is the praise but His?",
        stanzas: [
          "1. Reap me the earth as a harvest to God.\nGather and bring it again.\nAll that is His, to the Maker of all,\nlift it and offer it high.",
          "2. Go with your song and your music with joy.\nGo to the altar of God.\nCarry your offering, fruits from the earth,\nwork of your labouring hands.",
          "3. Gladness and pity and passion and pain\nall that is mortal to man\nLay all before Him, return from His gift,\nGod, to whom all shall go home.",
        ],
      ),
      Hymn(
        id: 419,
        number: "419",
        title: "Receive O Father",
        category: "Offertory & Gifts",
        stanzas: [
          "1. Receive, O Father, God of Might\nthis host unblemished in Your sight.\nUnworthy servants though we be,\nwe come before You trustingly.",
          "2. This saving chalice too, we bring,\nReceive it graciously, O King.\nWith fragrant odour may it rise\nto Your high throne above the skies.",
          "3. For all the living and the dead,\nfor our poor lives so badly led,\nwe raise these gifts to You above,\nand join to them ourselves in love.",
          "4. And being pleased Your gift bestow\nthe life of grace in us below,\nnot just to us this blessing send,\nto all the world let it extend.",
        ],
      ),
      Hymn(
        id: 420,
        number: "420",
        title: "Receive, O Holy Father",
        category: "Offertory & Gifts",
        stanzas: [
          "1. Receive, O Holy Father. Receive, O God Almighty,\nthe bread we offer, we who have failed,\nwe who have fallen, we who have sinned,\noffer the pure unblemished bread.\nReceive our offerings (3)\nwe bring to Thee,",
          "2. Receive, O Holy Father, Receive, O God Almighty,\nthe cup we offer, we who have failed,\nwe who have fallen, we who have sinned,\noffer the cup of salvation.\nAccept, O Lord, the gifts from our heart.\nReceive the little we can bring.\nWe pray for more of Your power. Grant us O Lord eternity. Receive them.",
          "3. May we, O Holy Father. May we, O God Almighty,\nthe starved, the thirsty, share in the Christ life, share in the Christ life, death of the cross and the mighty resurrection.",
        ],
      ),
      Hymn(
        id: 421,
        number: "421",
        title: "Receive Our Gifts",
        category: "Offertory & Gifts",
        stanzas: [
          "1. Receive our gifts we bring to Thee, O Lord.\nReceive them from Thy children's hands\nIt's by Thy power we have made them.\nWe offer them to Thee, O Lord. Receive them.",
        ],
      ),
      Hymn(
        id: 422,
        number: "422",
        title: "Rejoice In The Lord",
        category: "Praise & Worship",
        refrain: "Rejoice in the Lord, alleluia. (4)",
        stanzas: [
          "1. Our Father, Who art in heaven,\nhallowed be Thy name, Thy kingdom come.",
          "2. Thy will be done on earth as it is in heaven.\nGive us this day our daily bread.",
          "3. And forgive us our trespasses\nas we forgive those who sin against us.",
          "4. And lead us not into temptation\nbut deliver us from all evil.",
          "5. For the kingdom, the power and glory are\nYours now and for ever.",
        ],
      ),
      Hymn(
        id: 423,
        number: "423",
        title: "Remain In My Love",
        category: "Love & Charity",
        refrain: "Remain in My love and you will have joy.\nRemain in My love and my own joy will be yours.",
        stanzas: [
          "1. I am the True Vine.\nMake your home in Me.\nAnd you will have life and share it all abundantly.",
          "2. You did not choose Me No,\nI chose you to go out and to give life\nand have love in all that you do.",
          "3. No one can have greater love\nthan to lay down his life for his friends.\nYou are my friends.\nYou will never be strangers again.",
        ],
      ),
      Hymn(
        id: 424,
        number: "424",
        title: "Ride On",
        category: "Holy Week & Palm Sunday",
        stanzas: [
          "1. Ride on, ride on in majesty. Hark,\nall the tribes hosanna cry.\nThine humble beast pursued his road\nwith palms and scattered garments strewn.",
          "2. Ride on, ride on in majesty.\nIn lowly pomp ride on to die.\nO Christ Thy triumph now begin\no'er captive death and conquered sin.",
          "3. Ride on, ride on in majesty.\nThe winged squadrons of the sky\nlook down with sad and wondering eyes\nto see the approaching sacrifice.",
          "4. Ride on, ride on in majesty\nThe last and fiercest strife is nigh.\nThe Father, on His sapphire throne,\nexpects His Own Anointed Son.",
          "5. Ride on, ride on in majesty.\nIn lowly pomp, ride on to die.\nBow Thy meek head to mortal pain.\nThen take, O God, Thy power and reign.",
        ],
      ),
      Hymn(
        id: 425,
        number: "425",
        title: "Ring Out The Bells",
        category: "Advent & Christmas",
        refrain: "Ring out the bells, The joyful news is breaking\nRing out the bells for Jesus Christ is born",
        stanzas: [
          "1. Angels in wonder sing of his glory\nShepherds returning tell us the story",
          "2. Let all creation worship before him\nEarth bring him homage, heaven adore him",
          "3. Prophet have spoken hark to their, Warning\nShadows are passing soon come the morning.",
        ],
      ),
      Hymn(
        id: 426,
        number: "426",
        title: "Ring Out Your Joy",
        category: "Praise & Worship",
        refrain: "Ring out your joy to the Lord, O you just!\nFor praise is fitting for loyal hearts.",
        stanzas: [
          "1. Give thanks to the Lord upon the harp,\nwith a ten-stringed lute sing Him songs.\nO sing Him a song that is new.\nPlay loudly, with all your skill.",
          "2. For the word of the Lord is faithful,\nand all of His works to be trusted.\nThe Lord loves justice and right,\nand fills the earth with His love.",
          "3. By His word the heavens were made;\nby the breath of His mouth all the stars.\nHe collects the waves of the ocean.\nHe stirs up the depths of the sea.",
          "4. Let all the earth fear the Lord,\nand all who live in the world revere Him.\nHe spoke and it came to be.\nHe commanded: it sprang into being.",
          "5. He frustrates the designs of the nations,\nHe defeats the plans of the peoples.\nHis own designs shall stand forever,\nthe plans of His heart from age to age.",
          "6. They are happy, whose God is the Lord,\nthe people He has chosen as His own.\nFrom the heavens the Lord looks forth,\nHe sees all the children of men.",
        ],
      ),
      Hymn(
        id: 427,
        number: "427",
        title: "Rock Of Ages",
        category: "Penitential & Lent",
        stanzas: [
          "1. Rock of ages, cleft for me,\nlet me hide myself in Thee.\nLet the water and the blood,\nfrom the river side which flowed,\nbe of sin the double cure,\ncleanse me from my guilt and power.",
          "2. Not the labour of my hands\ncan fulfill Thy laws' demands.\nCould my zeal no respite know,\nCould my tears forever flow,\nall the sin could not atone\nThou must save and Thou alone.",
          "3. Nothing in My hand I bring,\nsimply to the cross I cling,\nnaked, come to Thee for dress;\nhelpless, look to Thee for grace.\nFoul, I to the fountain fly,\nwash me Saviour or I die.",
          "4. While I draw this fleeting breath,\nwhen my eyelids close in death,\nWhen I roam through tracts unknown\nsee Thee on Thy judgement throne;\nRock of ages cleft for me,\nLet me hide myself in Thee.",
        ],
      ),
      Hymn(
        id: 428,
        number: "428",
        title: "Salve Regina",
        category: "Marian Hymns",
        stanzas: [
          "1. Salve, Regina, mater misericordiae;\nVita, dulcedo, et spes nostra, salve.\nAd te clamamus, exsules, filii Hevae.\nAd te suspiramus, gementes et flentes in hac lacrimarum valle.\nEia ergo, advocate nostra, illos tuos misericordes oculos ad nos converte.\nEt Jesum, benedictum fructum ventris tui, nobis post hoc exsilium ostende.\nO Clemens, o pia, O dulcis Virgo Maria.",
        ],
      ),
      Hymn(
        id: 429,
        number: "429",
        title: "See Amid The Winter's Snow",
        category: "Advent & Christmas",
        stanzas: [
          "1. See amid the winter's snow,\nBorn for us on earth below\nSee, the tender lamb appears,\nPromised from eternal years\nHail thou ever-blessed morn\nHail redemption's happy dawn\nSing through all Jerusalem\nChrist is born in Bethlehem (2x)",
          "2. Lo, within a manger lies,\nHe who built the starry skies,\nHe, who throned in the heights sublime,\nSits amid the Cherubim.",
          "3. Say, ye holy shepherds, say\nWhat your joyful news today\nWherefore have ye left your sheep?\nOn the lonely mountain steep.",
          "4. \"As we watched at dead of night\nLo, we saw a wondrous light,\nAngels singing 'peace on earth;\nTold us of the Saviour's birth\"",
          "5. Sacred infant all divine,\nWhat a tender love was thine,\nThus to come from highest bliss,\nDown to such a world as this.",
        ],
      ),
      Hymn(
        id: 430,
        number: "430",
        title: "See How The Rose Of Judah",
        category: "Marian Hymns",
        stanzas: [
          "1. See how the rose of Judah\nfrom tender branch has sprung,\na rose from root of Jesse as prophets long and sung.\nWe sing that hymn again: to God on high be glory,\nand peace on earth to men.",
          "2. This rose of royal beauty of which Isaiah sings,\nis Mary, maiden mother, and Christ the flower she brings.\nBy God's unique design, remaining still a virgin,\nshe bore a child divine.",
          "3. We pray Thee, virgin mother, the Queen of heaven and earth.\nObtain for us from Jesus the blessings of His birth.\nBy His humility, may we live as God's children in peace and unity.",
        ],
      ),
      Hymn(
        id: 431,
        number: "431",
        title: "Seek First The Kingdom Of Heaven",
        category: "Word of God & Guidance",
        refrain: "Seek first the Kingdom of Heaven and all the rest will fall in line.\nGive God His due and God will give back to you.\nTurn your water into wine.",
        stanzas: [
          "1. Men are money mad, go about richly clad, seeking the rainbow's end.\nI tell you, God He will surely ditch all those among the rich,\nwho have no poor man friend.\nTurn your water into wine.",
          "2. Some men are barely fed, begging their crust of bread, from dawn to setting sun.\nI tell you God will give liberty to those in poverty and peace to everyone.\nTurn your water into wine.",
          "3. Some men are neither-nor, life rushes by their door, leaving them far behind.\nI tell you: jump in and join the fight.\nStand up for what is right. Serve God in all mankind.\nTurn your water into wine.",
        ],
      ),
      Hymn(
        id: 432,
        number: "432",
        title: "Seek Ye First The Kingdom",
        category: "Word of God & Guidance",
        refrain: "Alleluia, alleluia. Alleluia, alleluia, alleluia.",
        stanzas: [
          "1. Seek ye first the kingdom of God, and His righteousness.\nAnd all these things will be added unto you.\nAlleluia, alleluia.",
          "2. Ask and it shall be given unto you.\nSeek and you shall find.\nKnock and it shall be opened unto you,\nAlleluia, alleluia.",
          "3. Man does not live by bread alone,\nBut by every word, that proceeds from the mouth of God.\nAlleluia, Alleluia.",
          "4. Let your light so shine before men,\nthat they may see your good works and glorify your Father in heaven.\nAlleluia, Alleluia.",
        ],
      ),
      Hymn(
        id: 433,
        number: "433",
        title: "See The Church",
        category: "Entrance & Gathering",
        stanzas: [
          "1. See the Church assembled here!\nSee the Church in common prayer!\nSee the Church with loving care!\nCelebrate today. See the Church a Sacrament!\nSee the Church a Mystery!\nCome let us praise our God. Come let us praise Him.",
          "2. Christ the Lord, our offering!\nChrist the Lord, our sacrifice!\nChrist the Lord, our common meal!\nPresent here today.\nChrist Our Lord, our celebrant!\nChrist the Lord, our neighbor!\nCome let us praise our God. Come let us praise Him.",
          "3. Praise to God the Father be, praise the Son eternally;\npraise to God the Spirit be; All three in One;\nSo it has forever been, so it shall forever be.\nCome let us praise our God, Come let us praise him.",
        ],
      ),
      Hymn(
        id: 434,
        number: "434",
        title: "See The Loving Shepherd",
        category: "Communion & Eucharist",
        stanzas: [
          "1. See the loving shepherd of Thy sheep,\nthe holy, the holy bread of angels from heaven,\nfrom heaven He came to earth.\nLet us adore Him.",
          "2. He is our true Father all the time the shepherd,\nthe shepherd of Thy sheep.\nIn Him, in Him we place our hope of redemption\nGod full of grace.",
          "3. We are children of the wretchedness, O Lord,\nO Lord, our Saviour, have mercy,\nhave mercy on all of us,\ncause of Thy love for us.",
          "4. Stay with us, stay with us in this world,\nO, O, O, good Jesus! so that we,\nso that we may be with You in heaven for ever more.",
        ],
      ),
      Hymn(
        id: 435,
        number: "435",
        title: "See The Paraclete",
        category: "Holy Spirit & Pentecost",
        refrain: "Let us alleluia singing\nOffer Him our graceful days\nHe all heavenly graces bringing\nmerits everlasting praise.",
        stanzas: [
          "1. See the Paraclete descending,\nburning with celestial fire,\ngrace and truth on Him attending\nman with heavenly love inspire.",
          "2. Timid souls no longer fearing,\nnow the greatest danger scorn\nmidst their sorrows persevering\nshow themselves in Christ newborn.",
        ],
      ),
      Hymn(
        id: 436,
        number: "436",
        title: "See This Child",
        category: "Baptism & Confirmation",
        stanzas: [
          "1. See this child before you. Lord,\nYou Who give her life. Keep her in Your side O Lord, now and all her days.",
          "2. She is born, born again in the side of her Son,\nwith great joy and glad for her joy as one we pray.",
          "3. Child of love, child of pain,\nchild of sorrow and joy,\nchild of two who live as one,\nborn again today.",
        ],
      ),
      Hymn(
        id: 437,
        number: "437",
        title: "Send Forth Your Spirit O Lord",
        category: "Holy Spirit & Pentecost",
        refrain: "Send forth your spirit O Lord.\nThat the face of the earth be renewed.",
        stanzas: [
          "1. O my soul, arise and bless the Lord God,\nO Lord in majesty enrobed\nWith pow'r and eternal might.",
          "2. You are clothed with splendor and with beauty;\nO God, and heavenly light,\nIs like a cloud that conceals your face.",
          "3. You have built your palace on the waters;\nOn wings of wind and fire, You reign in heaven, rule supreme on earth.",
          "4. Like the winds your angels fly before you;\nAs fire and flaming light, Your ministers stand before your throne.",
          "5. For the earth you fixed on its foundation;\nIndeed, it shall stand firm, And not be moved in unending years.",
          "6. While I live, I sing the praise of Yahweh,\nO Lord, your glorious praise\nMy lips proclaim; blessed be the Lord.",
          "7. Praise God, the author of these marvels\nTo God the mighty one Who made the earth, glory to his name?",
          "8. Praise God, the Father, Son and Spirit\nTo God who gives us life, Our thanks return now and evermore.",
        ],
      ),
      Hymn(
        id: 438,
        number: "438",
        title: "Sent Forth",
        category: "Recessional & Dismissal",
        stanzas: [
          "1. Sent forth by God's blessing, our true faith confessing,\nthe people of God, from His dwelling take leave.\nGod's sacrifice ended, O now be extended,\nthe fruits of this Mass in all hearts who believe.\nThe seed of His teaching our inner souls reaching\nshall blossom in action for God and for man.\nHis grace shall incite us. His love shall unite us\nto further His kingdom by God's holy plan.",
          "2. With praise and thanksgiving, to God who is living,\nthe tasks of our ev'ry day life we embrace.\nOur faith ever sharing, our love ever caring,\nwe claim as our brothers all men of each race.\nOne bread that has fed us, one light that has led us,\nunite us as one in His life that we share:\nThen may all the living, with praise and thanksgiving,\ngive honour to Christ and His name that we bear.",
        ],
      ),
      Hymn(
        id: 439,
        number: "439",
        title: "Shepherds Rejoice",
        category: "Advent & Christmas",
        stanzas: [
          "1. Shepherds rejoice, your Saviour is born.\nSing o'er His cradle this glad Christmas morn.\nGloria, gloria, gloria, gloria. Sing and rejoice.\nYour Saviour is born.",
          "2. Jesus is born to set us free.\nJesus is born our Saviour to be.\nGloria, gloria, gloria, gloria.\nJesus is born our Saviour to be.",
          "3. Hark how the angels carol and sing\nGlory to God our newborn King.\nGloria, gloria, gloria, gloria,\nGlory to God, praise to our King.",
        ],
      ),
      Hymn(
        id: 440,
        number: "440",
        title: "Silent Night",
        category: "Advent & Christmas",
        stanzas: [
          "1. Silent night, holy night.\nAll is calm, all is bright.\nRound yon virgin mother and child.\nHoly infant, so tender and mild.\nSleep in heavenly peace.\nSleep in heavenly peace.",
          "2. Silent night, holy night\nshepherds quake at the sight.\nGlories stream from heaven afar.\nHeavenly hosts sing, alleluia.\nChrist the Saviour is born.\nChrist the Saviour is born.",
          "3. Silent night, holy night.\nSon of God love's pure light.\nRadiant beams from your holy face,\nwith the dawn of redeeming grace,\nJesus, Lord at Your birth.\nJesus, Lord at Your birth.",
        ],
      ),
      Hymn(
        id: 441,
        number: "441",
        title: "Sing A New Song",
        category: "Praise & Worship",
        refrain: "Sing a new song unto the Lord,\nLet your song be sung from mountains high\nSing a new song unto the Lord, singing alleluia.",
        stanzas: [
          "1. Yaweh's people dance for joy.\nO come before the Lord And play for Him on glad tambourines.\nAnd let your trumpet sound.",
          "2. Rise, O children, from your sleep.\nYour Saviour now has come.\nHe has turned your sorrow to joy,\nand filled your soul with song.",
          "3. Glad my soul for I have seen the glory of the Lord.\nThe trumpet sounds.\nThe dead shall be raised.\nI know my Saviour lives.",
        ],
      ),
      Hymn(
        id: 442,
        number: "442",
        title: "Sing, My Tongue The Saviour's Glory",
        category: "Communion & Eucharist",
        stanzas: [
          "1. Sing, my tongue, the Saviour's glory,\nOf his flesh the myst'ry sing,\nOf the blood, all price exceeding,\nShed by our immortal King,\nDestined for the world's redemption,\nFrom a noble womb to spring.",
          "2. Of a pure and spotless Virgin,\nBorn for us, his love to show,\nHe, as man, with man conversing,\nStayed the seeds of truth to sow;\nThen he closed in wondrous fashion,\nThis his life on earth below.",
          "3. On the night of that last supper,\nSeated with his chosen band,\nHe, the paschal victim, eating,\nFirst fulfils the law's command;\nThen as food to all his brethren,\nGives himself with his own hand.",
          "4. Christ the Word made flesh, by speaking,\nEarthly bread to flesh he turns;\nWine becomes his blood so precious,\nUnconceived in human terms.\nHearts sincere perceive this marvel;\nFaith its lesson quickly learns.",
          "5. Down in adoration falling,\nThis great sacrament we hail;\nOver ancient forms of worship,\nNewer rites of grace prevail;\nFaith tells us that Christ is present\nWhen our human senses fail.",
          "6. To the everlasting Father,\nAnd the Son who made us free,\nAnd the Spirit, God proceeding,\nFrom them each eternally,\nBe salvation, honor, blessing,\nMight and endless majesty.\nAmen.",
        ],
      ),
      Hymn(
        id: 443,
        number: "443",
        title: "Sing Of Mary",
        category: "Marian Hymns",
        stanzas: [
          "1. Sing of Mary, pure and lowly,\nvirgin mother undefiled.\nSing of God's own Son most holy,\nwho became her little child.\nFairest child of fairest mother,\nGod, the Lord who came to earth,\nWord made flesh, our very brother,\ntakes our nature by His birth.",
          "2. Sing of Jesus, Son of Mary in the home at Nazareth.\nToil and labour cannot weary love enduring unto death.\nConstant was the love He gave her though He went forth from her side\nForth to preach and heal and suffer, till on Calvary he died.",
          "3. Glory be to God the Father.\nGlory be to God the Son.\nGlory be to God the Spirit.\nGlory to the Three in One.\nFrom the heart of blessed Mary.\nFrom all saints the song ascends.\nAnd the Church the strain re-echoes unto earth's remotest ends.",
        ],
      ),
      Hymn(
        id: 444,
        number: "444",
        title: "Sing Of The Lord's Goodness",
        category: "Praise & Worship",
        refrain: "Come then all you nations, sing of your Lord's goodness,\nmelodies of praise and thanks to God.\nRing out the Lord's glory, praise Him with your music,\nworship him and bless His name.",
        stanzas: [
          "1. Sing of the Lord's goodness, Father of all wisdom,\ncome to Him and bless His name.\nMercy He has shown us, His love is forever,\nfaithful to the end of days.",
          "2. Power he has wielded, honor is His garment,\nrisen from the snares of death.\nHis word He has spoken, one bread He has broken,\nnew life he now gives to all.",
          "3. Courage in our darkness, comfort in our sorrow,\nSpirit of our God most high.\nSolace for the weary, pardon for the sinner,\nsplendour of the living God.",
          "4. Praise Him with your singing, praise Him with the trumpet,\npraise God with the lute and harp.\nPraise Him with the cymbals, praise Him with your dancing.\nPraise God till the end of days.",
        ],
      ),
      Hymn(
        id: 445,
        number: "445",
        title: "Sing Praise To The Living God",
        category: "Praise & Worship",
        refrain: "Glory to the Trinity, undivided unity,\nthe Father, Son and Spirit One,\nfrom Whom all life and goodness come.",
        stanzas: [
          "1. Sing praise to the living God, Glory alleluia.\nCome adore the living God, Glory alleluia.\nThough sun and moon may pass away,\nHis word will ever stay.\nHis power is forever more, Glory alleluia.",
          "2. To the living God we sing Glory alleluia.\nLet our love and praises ring. Glory alleluia.\nTo His sons He always gives His mercy and His love.\nPraise Him now forever more, Glory alleluia.",
          "3. To the God who cannot die Glory alleluia.\nTo the living God we cry, Glory alleluia.\nHe promised to be with us. And He lives in everyone.\nLove Him now forever more, Glory alleluia.",
        ],
