      Hymn(
        id: 446,
        number: "446",
        title: "Sing Sing Sing",
        category: "Praise & Worship",
        refrain: "Sing, sing, sing out your praise.\nDance, dance, dance all your days.\nPlay, play, play like a child\nAnd celebrate your life in Him.",
        stanzas: [
          "1. Jesus has called us children of light.\nDarkness and sadness put to its flight.\nFor He has died and now we must live;\nto celebrate our life in Him.",
          "2. Why should we worry what we shall need?\nWhat we will wear or where we will sleep?\nThere will be time for all these concerns.\nLet's celebrate our life in Him.",
          "3. Don't be afraid if you're slow to begin.\nOpen your heart and let Him come in.\nAnd soon you'll learn to sing and dance.\nAnd celebrate your life in Him.",
        ],
