        category: "Word of God & Guidance",
        refrain: "Beautiful words, wonderful words, wonderful words of life.\nBeautiful words, wonderful words, wonderful words of life.",
        stanzas: [
          "1. Sing them over again to me, wonderful words of life.\nLet me more of their beauty see wonderful words of life.\nWords of life and beauty Teach faith and duty.",
          "2. Christ, the blessed One, gives to all, wonderful words of life.\nSinner, listen to the loving call, wonderful words of life\nAll so freely given, wooing us to heaven.",
          "3. Sweetly echoes the gospel call, wonderful words of life\noffer pardon and peace to all, wonderful words of life.\nJesus, only Saviour, saves and keeps forever.",
        ],
      ),
      Hymn(
