      Hymn(
        id: 449,
        number: "449",
        title: "Softly And Tenderly",
        category: "Penitential & Lent",
        refrain: "Come home, come home,\nYe who are weary come home;\nEarnestly, tenderly, Jesus is calling,\nCalling O sinners come home!",
        stanzas: [
          "1. Softly and tenderly Jesus is calling,\ncalling for you and for me;\nPatiently Jesus is waiting and watching,\nwatching for you and for me.",
          "2. Why should we tarry when Jesus is pleading,\npleading for you and for me?\nWhy should we linger and heed not His mercies,\nmercies for you and for me?",
          "3. Time is now fleeting the moments are passing,\npassing for you and for me;\nShadows are gathering and death may be coming,\ncoming for you and for me.",
          "4. Oh for the wonderful love He has promised,\npromised for you and for me!\nThough we have sinned He has mercy and pardon,\npardon for you and for me.",
        ],
      ),
      Hymn(
        id: 450,
        number: "450",
        title: "Sons Of God",
        category: "Communion & Eucharist",
        refrain: "Sons of God, hear His holy word,\nGather round the table of the Lord;\nEat His body, drink His blood,\nand we shall sing a song of love.\nAllelu, Allelu, Alleluia.",
        stanzas: [
          "1. Brothers, sisters we are one.\nAnd our life has just begun\nIn the Spirit we are young\nWe can live forever.",
          "2. Shout together to the Lord\nWho has promised His reward:\nHappiness a hundred fold\nAnd we shall live forever.",
          "3. Jesus gave a new command,\nthat we love our fellowman,\ntill we reach the promised land,\nwhere we shall live forever.",
          "4. If we want to live with Him,\nwe must also die with Him,\ndie to selfishness and sin.\nThen we shall live forever.",
        ],
      ),
      Hymn(
        id: 451,
        number: "451",
        title: "Spirit Of God",
        category: "Holy Spirit & Pentecost",
        refrain: "Blow, blow, blow till I be\nbut breath of the Spirit blowing in me.",
        stanzas: [
          "1. Spirit of God in the clear running waters,\nblowing to greatness the trees on the hill,\nSpirit of God in the finger of morning,\nfill the earth and blow where you will.",
          "2. I saw the scar of a year that lay dying.\nHeard the lament of the lone whip-poor-will.\nSpirit of God, see that cloud crying,\nfill the earth...",
          "3. Down in the meadow the willows are moaning.\nSheep in the pasture land cannot lie still.\nSpirit of God, creation is groaning,\nfill the earth...",
          "4. Spirit of God, every man's heart is lonely,\nwatching and waiting and hungry until,\nSpirit of God, man longs that You only\nfulfill the earth...",
        ],
      ),
      Hymn(
        id: 452,
        number: "452",
        title: "Spirit Of The Living God",
        category: "Holy Spirit & Pentecost",
        stanzas: [
          "1. Spirit of the living God, fall afresh on me.\nSpirit of the living God, fall afresh on me.\nMelt me, mould me, fill me, use me.\nSpirit of the living God, fall afresh on me.",
          "2. Spirit of the living God, fall afresh on us.\nSpirit of the living God, fall afresh on us.\nMelt us, mould us, fill us, use us.\nSpirit of the living God, fall afresh on us.",
        ],
      ),
      Hymn(
        id: 453,
        number: "453",
        title: "Soul Of My Saviour",
        category: "Communion & Eucharist",
        stanzas: [
          "1. Soul of my Saviour, sanctify my breast,\nBody of Christ, be Thou my saving guest.\nBlood of my Saviour, bathe me in Thy tide\nWash me with waters flowing from His side.",
          "2. Strength and protection, may His passion be.\nO Blessed Jesus, hear and answer me.\nDeep in Thy wounds, Lord, hide and shelter me.\nSo shall I never, never part from Thee.",
          "3. Guard and defend me from the foe malign.\nIn death's dread moments make me only Thine.\nCall me and bid me, come to Thee on high,\nwhere I may praise Thee with the saints for aye.",
        ],
      ),
      Hymn(
        id: 454,
        number: "454",
        title: "Sowing In The Morning",
        category: "Social Justice & Christian Living",
        refrain: "Bringing in the sheaves (2)\nwe shall come rejoicing,\nbringing in the sheaves.",
        stanzas: [
          "1. Sowing in the morning, sowing seeds of kindness,\nsowing in the noon tide and the dewy eves.\nWaiting for the harvest and the time of reaping,\nwe shall come rejoicing, bringing in the sheaves.",
          "2. Sowing in the sunshine, sowing in the shadows,\nfearing neither clouds nor winter's chilling breeze.\nBy and by the harvest and the labour ended:\nwe shall come rejoicing, bringing in the sheaves.",
          "3. Going forth with weeping, sowing for the Master,\nthrough the loss sustained our spirit often grieves.\nWhen our weeping's over He shall bid us welcome.\nWe shall come rejoicing, bringing in the sheaves.",
        ],
      ),
      Hymn(
        id: 455,
        number: "455",
        title: "Standing On The Promises",
        category: "Faith & Trust",
        refrain: "Standing (3) on the promises of God my Saviour,\nStanding (2) I'm standing on the promises of God.",
        stanzas: [
          "1. Standing on the promises of Christ my King,\nthrough eternal ages let His praises ring:\nGlory in the highest, I will shout and sing,\nstanding on the promises of God.",
          "2. Standing on the promises that cannot fail\nwhen the howling storms of doubts and fears assail,\nby the living word of God I shall prevail,\nstanding on the promises of God.",
          "3. Standing on the promises I now can see,\npresent perfect cleansing in the blood for me:\nStanding in the liberty where Christ makes free,\nStanding on the promises of God.",
          "4. Standing on the promises that cannot fail\nlistening every moment to the Spirit's call.\nResting in my Saviour as my all in all,\nstanding on the promises of God.",
        ],
      ),
      Hymn(
        id: 456,
        number: "456",
        title: "Stand Up My Friends",
        category: "Offertory & Gifts",
        stanzas: [
          "1. Stand up my friends lets go 'n' offer, offer,\nour gifts to the Father above.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
          "2. Do not mind, do not mind.\nDo not mind as our gifts are so small.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
          "3. Receive them, receive them.\nReceive them unworthy as we are.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
          "4. We offer them, we offer them.\nWe offer them together with our hearts.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
          "5. O Jesus our Saviour, take our poor offering, to our Father.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
          "6. Receive the wine, receive the wine,\nreceive the wine which we have given.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
          "7. Praise the Father, praise the Son.\nPraise the Holy Spirit.\nFather, take our offering -\nTake our offering. Take our offering.\nFather, take the poor offering which we give.",
        ],
      ),
      Hymn(
        id: 457,
        number: "457",
        title: "Stand Up! Stand Up For Jesus",
        category: "Consecration & Dedication",
        stanzas: [
          "1. Stand up! Stand up for Jesus!\nYe Soldiers of the cross;\nLift high His royal banner,\nIt must not suffer loss.\nFrom victory unto victory\nHis army shall He lead,\nTill every foe is vanquished,\nAnd Christ is Lord indeed.",
          "2. Stand up! Stand up for Jesus!\nThe trumpet call obey;\nForth to the mighty conflict\nIn this His glorious day!\nYe that are men, now serve him\nAgainst unnumbered foes;\nLet courage rise with danger,\nAnd strength to strength oppose.",
          "3. Stand up! Stand up for Jesus!\nStand in his strength alone:\nThe arm of flesh will fail you\nYe dare not trust your own:\nPut on the gospel armour,\nAnd watching unto prayer,\nWhere duty calls or danger,\nBe never wanting there.",
          "4. Stand up! Stand up for Jesus!\nThe strife will not be long;\nThis day the noise of battle,\nThe next the victor's song;\nTo him that over cometh\nA crown of life shall be;\nHe with the King of Glory\nShall reign eternally.",
        ],
      ),
      Hymn(
        id: 458,
        number: "458",
        title: "Sweet Are The Promises",
        category: "Word of God & Guidance",
        refrain: "Where He leads I follow: follow all the way. (2)\nFollow Jesus every way.\nWhere He leads I follow. (2)\nFollow all the way, yes.\nFollow Jesus every way.",
        stanzas: [
          "1. Sweet are the promises, kind is the word:\ndearer far than any message man ever heard.\nPure was the mind of Christ sinless I see.\nHe the great example is and pattern for me.",
          "2. Sweet is the kinder love Jesus hath shown:\nsweeter far than any love that mortals have known:\nkind to every one: faithful is He\nHe the great example is and pattern for me.",
          "3. Listen to the loving words come unto me:\nWeary, heavy laden there is sweet rest for thee:\ntrust in His promises, faithful and the same:\nlean upon the Saviour and thy soul is secured.",
        ],
      ),
      Hymn(
        id: 459,
        number: "459",
        title: "Sweet Chiming Christmas Bells",
        category: "Advent & Christmas",
        refrain: "Sweet chiming Christmas bells (sweet bells)\nSweet chiming Christmas bells (sweet bells)\nThey cheer us on our heav'n ward way\nSweet chiming bells. (2x)",
        stanzas: [
          "1. The bells ring out at Christmas time\ntheir message loud and clear\nour hearts and stared as on the air\nthe joyful sound we hear.",
          "2. Thanks be to God from whom we learn\nThe bell's exultant theme\nThe babe of Bethlehem was born\nThis lost world to redeem.",
          "3. Glad message of the Christmas bells\nof God whose name is love\nOh may this message all our days\nour hope and comfort prove.",
        ],
      ),
      Hymn(
        id: 460,
        number: "460",
        title: "Sweet Heart Of Jesus",
        category: "Sacred Heart",
        stanzas: [
          "1. Sweet heart of Jesus, fount of love and mercy,\ntoday we come, thy blessing to implore;\nO touch our hearts, so cold and so ungrateful,\nand make them, Lord, thine own for evermore.\nSweet heart of Jesus, we implore,\nO make us love thee more and more.",
          "2. Sweet heart of Jesus, make us know and love thee,\nunfold to us the treasures of thy grace,\nthat so our hearts, from things of earth uplifted,\nmay long alone to gaze upon thy face.",
          "3. Sweet heart of Jesus make us pure and gentle,\nand teach us how to do thy blessed will,\nto follow close the print of thy dear footprints,\nand when we fall sweet heart, O love us still.",
          "4. Sweet heart of Jesus, bless all hearts that love thee,\nand may thine own heart ever blessed be;\nbless us, dear Lord, and bless the friends we cherish,\nand keep us true, to Mary and to thee.",
        ],
      ),
      Hymn(
        id: 461,
        number: "461",
        title: "Sweet Sacrament Divine",
        category: "Communion & Eucharist",
        stanzas: [
          "1. Sweet sacrament divine,\nhid in Thy earthly home,\nlo! round Thy lowly shrine\nwith suppliant hearts we come.\nJesus, to Thee our voice we raise,\nin songs of love and heartfelt praise,\nsweet sacrament divine.",
          "2. Sweet sacrament of peace,\ndear home of every heart,\nwhere restless yearnings cease,\nand sorrows all depart,\nthere in Thine ear all trustfully\nwe tell our tale of misery,\nsweet sacrament of peace.",
          "3. Sweet sacrament of rest,\nark from the ocean's roar,\nwithin Thy shelter blest\nsoon may we reach the shore.\nSave us, Save us, for still the tempest raves.\nSave, lest we sink beneath the waves.\nSweet Sacrament of rest.",
          "4. Sweet sacrament divine,\nearth's light and jubilee,\nin Thy far depths doth shine\nThy Godhead's majesty.\nSweet light, so shine on us, we pray,\nthat earthly joys may fade away.\nSweet Sacrament divine.",
        ],
      ),
      Hymn(
        id: 462,
        number: "462",
        title: "Sweet Saviour Bless Us",
        category: "Recessional & Dismissal",
        refrain: "Through life's long day and death's dark night,\nO gentle Jesus be our light.",
        stanzas: [
          "1. Sweet Saviour bless us ere we go.\nThy word into our hearts instill.\nAnd make our lukewarm hearts to glow\nwith lowly love and fervent will.",
          "2. The day is done, its hours have run\nAnd Thou hast taken count of all,\nthe scanty triumphs grace has won,\nthe broken vow, the frequent fall.",
          "3. Labour is sweet, for Thou hast toiled,\nAnd care is light for Thou hast cared.\nLet not our works with self be soiled,\nnor in unsimple ways ensnared.",
          "4. For all we love the poor, the sad,\nthe sinful - unto Thee we call.\nOh, let Thy mercy make us glad.\nThou art our Jesus and our all.",
        ],
