        number: "463",
        title: "Take And Eat",
        category: "Communion & Eucharist",
        refrain: "Take and eat, this is my body.\nTake and drink this is my blood,\ngiven to you in the face of redemption.\nTake and eat, this is my body,\ngiven to you in the face of redemption.\nRemember me. (2)",
        stanzas: [
          "1. I couldn't be here, remember me.\nI live all alone. Remember me.\nI kiss you good night and call you 'my father'.\nRemember me. Remember me. (2)",
          "2. Take and eat, this is my gift, myself.\nKnown is my pledge now to be with you always.\nRemember me. Remember me. (2)",
        ],
