        number: "464",
        title: "Take And Sanctify",
        category: "Offertory & Gifts",
        stanzas: [
          "1. Take and sanctify for your honor Lord\nAnd sanctify these gifts for your honour Lord\nTake and sanctify these gifts for your honour Lord.",
          "2. All that I am and all that I do\nEverything I will ever make\nTake my life and take my all\nEverything I will ever make.",
          "3. All that I need and all that I pray\nEverything I will ever have\nTake my life and take my all\nEverything I will ever have.",
          "4. All that I dream all that I crave\nEverything I will ever be\nTake my life and take my all\nEverything I will ever be.",
        ],
      ),
      Hymn(
        id: 465,
        number: "465",
        title: "Take Me As I Am",
        category: "Penitential & Lent",
        refrain: "And take me as I am, and take me as I am\nMy only plea - Christ died for me!\nOh, take me as I am.",
        stanzas: [
          "1. Jesus my Lord, to thee I cry;\nUnless thou help me I must die!\nOh, bring thy free salvation nigh,\nAnd take me as I am.",
          "2. Helpless I am, and full of guilt;\nBut yet for me thy blood was spilt,\nAnd thou canst make me what thou wilt.\nAnd take me as I am.",
          "3. No preparation can I make,\nMy best resolves I only break,\nYet save me for thine own name's sake,\nAnd take me as I am.",
          "4. Behold me, Saviour at thy feet;\nDeal with me as thou see'st meet;\nThy work begins, thy work complete.\nAnd take me as I am.",
        ],
      ),
      Hymn(
        id: 466,
        number: "466",
        title: "Take My Hands",
        category: "Consecration & Dedication",
        stanzas: [
          "1. Take my hands and make them as your own.\nAnd use them for your kingdom, here on earth.\nConsecrate them to your care anoint them for your service,\nwhere you may need your gospel to be sown.",
          "2. Take my hands. They speak now for my heart.\nAnd by their actions, they will show their love.\nGuard them on their daily course.\nBe their strength and guiding force:\nto ever serve the Trinity above.",
          "3. Take my hands, I give them to You, Lord.\nPrepare me for the service of Your name.\nOpen them to human need.\nAnd by their love they'll sow Your seed,\nso all may know the love and hope You gave.\nTake my hands, take my hands, O Lord.",
        ],
      ),
      Hymn(
        id: 467,
        number: "467",
        title: "Take Our Bread",
        category: "Offertory & Gifts",
        refrain: "Take our bread, we ask You.\nTake our hearts, we love You.\nTake our lives, O Father.\nWe are Yours. (2)",
        stanzas: [
          "1. Yours as we stand at the table You set.\nYours as we eat the bread our hearts can't forget.\nWe are a sign of Your Life with us yet.\nWe are Yours. (2)",
          "2. Your holy people standing, washed in Your blood.\nSpirit-filled yet hungry we await Your food.\nWe are poor, but we've brought ourselves, the best we could.\nWe are Yours. (2)",
        ],
      ),
      Hymn(
        id: 468,
        number: "468",
        title: "Take Up Your Cross",
        category: "Penitential & Lent",
        stanzas: [
          "1. 'Take up your cross' the Saviour said,\n'If you would My disciples be,\ntake up your cross and follow Me.'",
          "2. Take up your cross. Let not its weight\nfill your weak soul with vain alarm.\nHis strength shall bear your spirit up,\nand brace your heart and nerve Your arm.",
          "3. Take up Your cross, don't heed the shame.\nAnd let your foolish pride be still,\nYour Lord did not refuse to die\nupon a cross, on Calvary's hill.",
          "4. Take up your cross and follow Christ,\nnor think till death to lay it down.\nFor only he who bears the cross,\nmay hope to wear the glorious crown.",
        ],
      ),
      Hymn(
        id: 469,
        number: "469",
        title: "Tell It To Jesus",
        category: "Prayer & Petition",
        refrain: "Tell it to Jesus, tell it to Jesus,\nHe is a friend that is well known.\nYou have no other such a friend or a brother,\nTell it to Jesus alone.",
        stanzas: [
          "1. Are you weary, are you heavy hearted?\nTell it to Jesus alone. (2)\nAre you grieving over joys departed?\nTell it to Jesus alone.",
          "2. Though the tears flow your cheeks untidied,\ntell it to Jesus. (2)\nHave you sinned that no man's eyes are hidden?\nTell it to Jesus alone.",
          "3. Do you hear the gathering clouds of sorrow?\nTell it to Jesus. (2)\nAre you anxious of what will be tomorrow?\nTell it to Jesus alone.",
          "4. Are you troubled with the thought of dying?\nTell it to Jesus. (2)\nFor Christ's coming Kingdom are you sighing?\nTell it to Jesus alone.",
        ],
      ),
      Hymn(
        id: 470,
        number: "470",
        title: "Ten Unclean",
        category: "Thanksgiving",
        refrain: "Unclean and nowhere to go,\nten men cleansed as clean as snow.\nOne returned to give God thanks,\nbut nine went away.",
        stanzas: [
          "1. Ten men lepers, in a Hebrew town!\nTen crying Lord, Won't You please come down?\nNo hope near till one fine day,\nJesus of Nazareth passed that way.",
          "2. Lord, make me clean, was their single cry.\nSee, now, the whole world passes us by.\nNo man's home will take us in;\nThen Christ bent down and touched their skin.",
          "3. God gives gifts to us ev'ry day,\nfavours His people in ev'ry way.\nHope restored and pain relieved.\nDo you ever give thanks for a gift received?",
          "4. Thank you, Lord, for the rising sun,\nfor sight and song and good deeds done.\nFaith and family and loving friends,\nfor the day that begins and the night that ends.",
        ],
      ),
      Hymn(
        id: 471,
        number: "471",
        title: "Taste And See",
        category: "Communion & Eucharist",
        refrain: "Taste and see that the Lord is good.",
        stanzas: [
          "1. I will bless the Lord at all times,\nHis praises always on my lips.\nIn the Lord my soul shall make its boast.\nThe humble shall hear and be glad.",
          "2. Glorify the Lord with me.\nTogether let us praise His name.\nI sought the Lord and He answered me.\nFrom all my terrors He set me free.",
          "3. Look towards Him and be radiant.\nLet your faces not be abashed.\nThis poor man called, the Lord heard Him.\nAnd rescued him from all his distress.",
          "4. The angel of the Lord is encamped around those who revere Him, to rescue them.\nTaste and see that the Lord is good.\nHe is happy who seeks refuge in Him.",
          "5. Revere the Lord, you, His saints.\nThey lack nothing, those who revere Him.\nStrong lions suffer want and go hungry.\nBut those who seek the Lord lack no blessing.",
          "6. Give praise to the Father Almighty,\nto His Son, Jesus Christ, the Lord,\nto the Spirit Who dwells in our hearts,\nboth now, and forever, Amen.",
        ],
      ),
      Hymn(
        id: 472,
        number: "472",
        title: "Thanks Be To God Who Leads His Saints",
        category: "Saints & Martyrs",
        stanzas: [
          "1. Thanks be to God who leads His saints,\nIn Christ's triumphant march,\nAlong the way their fragrance spreads,\nTo make Christ known to men.",
          "2. In them the glory of the Lord,\nShines brightly as the sun;\nFor they became in Jesus Christ\nTrue likenesses of God.",
          "3. They suffered much on every side,\nBut never lacked God's love.\nTheir bodies carried Jesus' death\nTo show His life at work.",
          "4. While on this earth, they sowed in tears,\nBut now they reap with joy,\nTheir earthly tent gives way to one,\nWhich never shall fall down.",
          "5. O Christ, while we are far from home,\nGive courage to us here,\nTo please the Father as we hear,\nAll that the Spirit says.",
        ],
      ),
      Hymn(
        id: 473,
        number: "473",
        title: "Thank You",
        category: "Thanksgiving",
        stanzas: [
          "1. Thank You for waking me this morning,\nThank You for giving me today.\nThank You for every new day dawning.\nI'll be thanking You.",
          "2. Thank You for every tree and flower.\nThank You for sky of blue.\nThank you, I should be every hour\ntruly thanking You.",
          "3. Thank You for every note of music.\nThank You for every song I sing,\nThank You for giving me sweet music.\nThanks for everything.",
          "4. Thank You for everything You give me.\nThank You for everything we share.\nThank You for simply being near me\nThanks for ever being here.",
          "5. Thank You for cheering me with laughter.\nThank You for every smile you bring.\nThank you for now and ever after.\nThanks for everything.",
        ],
      ),
      Hymn(
        id: 474,
        number: "474",
        title: "That Man Of Calvary",
        category: "Passion & Cross",
        refrain: "That man of Calvary has won my heart from me\nand died to set me free, blest man of Calvary.",
        stanzas: [
          "1. Fairest of all the earth betide,\nchiefest of all unto thy bride,\nfullness divine in thee I see,\nwonderful man of Calvary.",
          "2. Granting the sinner life and peace,\nGranting the captive sweet release,\nShedding His blood to make us free,\nmerciful man of Calvary.",
          "3. Giving the gifts obtained for men,\nPouring out love beyond our ken,\nGiving us spotless purity,\nBountiful man of Calvary.",
          "4. Comfort of all my earthly way,\nJesus I'll meet thee some sweet day,\nCenter of Glory thee I'll see,\nWonderful man of Calvary.",
        ],
      ),
      Hymn(
        id: 475,
        number: "475",
        title: "The Angels Rolled The Stone",
        category: "Easter & Resurrection",
        refrain: "The angels rolled the stone away.\nThe angels rolled the stone away.\nIt was early Easter Sunday morning,\nThe angels rolled the stone away.",
        stanzas: [
          "1. Mary came a running about the break of day\nlooking for Lord Jesus.\nThe stone was rolled away.",
          "2. She sadly walked the garden.\nA shadow barred her way.\nPlease tell me, Mr. Gardener,\n'who rolled the stone away?'",
          "3. She waited for an answer.\n'Mary', He did say\nRabboni, 'O my Master,\nYou rolled the stone away.'",
          "4. She returned from darkness\nAnd He's here to stay.\nFear no more my brothers.\nAngels rolled the stone away.",
        ],
      ),
      Hymn(
        id: 476,
        number: "476",
        title: "The Baker-Woman",
        category: "Marian Hymns",
        stanzas: [
          "1. The baker-woman in her humble lodge\nreceived a grain of wheat from God.\nFor nine whole months the grain she stored,\nbehold the handmaid of the Lord.\nBake us the bread Mary, Mary,\nBake us the bread we need to be fed.",
          "2. The baker-woman took the bread\nwhich led to Bethlehem, the house of bread.\nTo knead the bread she laboured through the night\nand brought it forth before midnight,\nBake us the bread, Mary, Mary.\nBake us the bread we need to be fed.",
          "3. She baked the bread for thirty years,\nby the fire of her love, and the salt of her tears,\nso tender and bright, so brown and white.\nBring us the bread, Mary, Mary.\nBring us the bread We need to be fed.",
          "4. After thirty years the bread was done.\nIt was taken to the town by her only Son,\nthe soft white bread to be given free\nto the hungry people of Galilee.\nGive us the bread Mary, Mary.\nGive us the bread, need to be fed.",
          "5. For thirty coins the bread was sold\nand a thousand teeth so cold, so cold\ntore it to pieces on a Friday noon,\nwhen the sun turned black and red the noon.\nBreak us the bread, Mary, Mary.\nBreak us the bread. We need to be fed.",
          "6. And when she saw the bread so white,\nthe living bread she had made at night,\ndevoured as wolves might devour a sheep,\nthe baker woman began to weep.\nWeep for the bread, Mary, Mary.\nWeep for the bread, we need to be fed.",
          "7. But the baker woman's only son\nappeared to His friends when three days had run\non the road which to Emmaus led,\nand they knew Him in the breaking of bread.\nLift up your head, Mary, Mary.\nLift up your head, for we've been fed.",
        ],
      ),
      Hymn(
        id: 477,
        number: "477",
        title: "The Basilican Creed",
        category: "Creed & Faith",
        refrain: "I believe in God the Father,\nI believe in God the Son,\nI believe in God the Spirit,\nOne God for ever more.",
        stanzas: [
          "1. Mighty Father I believe\nYou created heaven and earth\nAnd in Jesus Christ our Lord,\nEverlasting Son of God.",
          "2. Equal in the Father's power\nand through Him all things were made\nHe it was who saved us all,\nFrom heaven He came to earth.",
          "3. Of the Virgin Mary born,\nBy the Spirit Word made flesh,\nSuffered death was crucified,\nAnd He rose up from the dead.",
          "4. He ascended in heaven\nAnd His kingdom has no end;\nIn the Spirit I believe,\nLord and giver of all life.",
          "5. With the Father and the Son\nHe's adored and glorified;\nI believe in the holy Church,\nAnd one baptism professed.",
          "6. I shall see Him in heaven,\nO yes Lord I believe\nLiving in the world to come,\nAmen, Amen.",
        ],
      ),
      Hymn(
        id: 478,
        number: "478",
        title: "The Comforter Has Come",
        category: "Holy Spirit & Pentecost",
        refrain: "The Comforter has come, the Comforter has come,\nThe Holy Ghost from heaven, The Father's promise given;\nOh spread the tidings round, Wherever man is found,\nThe Comforter has come.",
        stanzas: [
          "1. Oh spread the tidings round,\nWherever man is found,\nWherever human hearts and human woes abound;\nLet ev'ry Christian tongue proclaim the joyful sound:\nThe Comforter has come.",
          "2. The long, long night is past,\nThe morning breaks at last;\nThe hush'd the dreadful wail and fury of the blast\nAs o'er the golden hills, the day advances fast;\nThe Comforter has come.",
          "3. The mighty King of kings, with healing in His wings\nTo e'vry captive soul a full deliverance brings;\nAnd through the vacant cells the songs of triumph rings:\nThe Comforter has come.",
          "4. The boundless love divine!\nHow shall this tongue of mine\nTo wandering mortals tell the matchless grace divine\nThat I may with Him dwell, and in His image shine:\nThe Comforter has come.",
          "5. Then let the echoes fly, above the vaulted sky\nAnd all the saints above to all below reply\nLet praise of endless love, the song that ne'er will die;\nThe Comforter has come.",
        ],
      ),
      Hymn(
        id: 479,
        number: "479",
        title: "The First Noel",
        category: "Advent & Christmas",
        refrain: "Noel, Noel, Noel, Noel.\nBorn is the King of Israel.",
        stanzas: [
          "1. The first Noel, the angel did say,\nwas to certain poor shepherds in fields as they lay:\nIn fields where they lay keeping their sheep,\non a cold winter's night that was so deep.",
          "2. They looked above and saw a star\nthat shone in the east beyond them afar,\nand which to earth did give a great light.\nAnd so it continued by day and by night.",
          "3. And by the light of that same star\nthree wise men came, from a country afar\nto seek for a king was their intent,\nand to follow the star wherever it went.",
          "4. This star drew near to the northwest,\nat length over Bethlehem seemed to rest.\nAnd there it stayed by night and by day,\nright over the place where Jesus lay.",
          "5. Then entered in those wise men three,\nmost reverently with bended knee,\nand offered there, in His presence,\nboth gold and myrrh with frankincense.",
          "6. Then let us all with one accord,\nsing praises to our heavenly Lord,\nthat made both heaven and earth of nought,\nAnd with His blood mankind has bought.",
        ],
      ),
      Hymn(
        id: 480,
        number: "480",
        title: "The Heavens Are Telling",
        category: "Praise & Worship",
        refrain: "The heavens are telling the glory of God.\nAnd all creation is shouting for joy.\nCome, dance in the forest.\nCome, play in the fields\nAnd sing, sing to the glory of the Lord.",
        stanzas: [
          "1. Sing to the sun, the bringer of day.\nHe carries the light of the Lord, in his rays,\nthe moon and the stars, who light up our way\nunto the Lord.",
          "2. Praise to the wind, that blows through the trees,\nthe seas mighty storms, the gentlest breeze.\nThey blow where they will.\nThey blow where they please,\nto please the Lord.",
          "3. Praise to the rain, that waters our fields,\nand blesses our crops, so all the earth yields.\nFrom death unto life the mystery concealed,\nsprings forth in joy.",
          "4. Praise to the death, makes our life real,\nknowledge of loss helps us to feel, the gift of Yourself,\nyour presence revealed, to bring us home.",
        ],
      ),
      Hymn(
        id: 481,
        number: "481",
        title: "The Holly And The Ivy",
        category: "Advent & Christmas",
        refrain: "The rising of the sun,\nand the running of the deer,\nthe playing of the merry organ,\nsweet singing in the choir.",
        stanzas: [
          "1. The holly and the ivy when they are both full grown,\nof all the trees that are in the wood,\nthe holly bears the crown.",
          "2. The holly bears the blossom as white as lily flower.\nAnd Mary bore sweet Jesus Christ, to be our sweet Saviour.",
          "3. The holly bears the prickle as sharp as any thorn.\nAnd Mary bore sweet Jesus Christ on Christmas day in the morn.",
        ],
      ),
      Hymn(
        id: 482,
        number: "482",
        title: "The King Of Glory",
        category: "Advent & Christmas",
        refrain: "The King of glory comes, the nation rejoices.\nOpen the gates before Him, lift up your voices.",
        stanzas: [
          "1. Who is the King of glory, how shall we call Him?\nHe is Emmanuel, the promised of ages.",
          "2. In all of Galilee, in city or village,\nHe goes among His people, curing their illness.",
          "3. Sing then of David's son, Our Saviour and our Brother.\nIn all of Galilee was never another.",
          "4. He gave His life for us; the pledge of salvation.\nHe took upon Himself the sins of the nation.",
          "5. He conquered sin and death. He truly has risen.\nAnd He will share with us His heavenly vision.",
        ],
      ),
      Hymn(
        id: 483,
        number: "483",
        title: "The Lord Hears The Cry",
        category: "Praise & Worship",
        refrain: "The Lord hears the cry of the poor.\nBlessed be the Lord.",
        stanzas: [
          "1. I will bless the Lord at all times\nHis praises ever in my mouth.\nLet my soul glory in the Lord.\nFor He hears the cry of the poor.",
          "2. Let the lowly hear and be glad,\nThe Lord listens to their pleas.\nAnd to hearts broken He is near.\nFor He hears the cry of the poor.",
          "3. Every spirit crushed He will save,\nwill be ransom for their lives,\nwill be safe shelter for their fears.\nFor He hears the cry of the poor.",
          "4. We proclaim the greatness of God,\nHis praise ever in my mouth.\nEvery face brightened in His light\nFor He hears the cry of the poor.",
        ],
      ),
      Hymn(
        id: 484,
        number: "484",
        title: "The Lord Is Calling Today",
        category: "Penitential & Lent",
        stanzas: [
          "1. The Lord is calling today, is calling you.\nHe has something for you.\nForsake your sins today,\nHe wants you to repent and have new life in you today. (2)\nOne day, just one day, this world will end.\nThe bar you go to drink will be no more.\nHe wants you to repent and have new life in you today.",
          "2. Your money in the bank, He knows all\nYour sin back in your home, He sees them all.\nHe wants you to repent and have new life in you today.",
          "3. Teachers hear Him today. He knows you all.\nTraders seek Him today. He rings for you.\nHe wants you to repent and have new life in you today.",
          "4. Workers meet him today. He gives you work.\nRich men what of your selves? He made you rich.\nHe wants you to repent and have new life in you today.",
        ],
      ),
      Hymn(
        id: 485,
        number: "485",
        title: "The Lord Is Dawn And Darkness",
        category: "Praise & Worship",
        refrain: "For He is mighty Lord God of all.\nHe is love and Lord of all. (2)",
        stanzas: [
          "1. The Lord is dawn and darkness. He is light for today.\nHe knows our weakness, yet He walks our ways,\nHe is steady, to every creature that lives.\nHe is mighty Lord.",
          "2. O serve the Lord with gladness. Serve the Lord with song.\nAnd know He made us. He is steady love.\nAnd He alone is our God. He is mighty Lord.",
        ],
      ),
      Hymn(
        id: 486,
        number: "486",
        title: "The Lord Is King",
        category: "Praise & Worship",
        refrain: "Kalamazoo, Kalamazoo mmm,\nKalamazoo, Kalamazoo mmm,\nKalamazoo.",
        stanzas: [
          "1. The Lord is King forever. Kalamazoo - Kalamazoo.\nHe reigns on earth from sea to sea\nKalamazoo - Kalamazoo.\nPraise Him, Praise Him.\nLet all creation praise the Lord.\nHe reigns on earth from sea to sea\nAll Praise His name in Kalamazoo.",
          "2. His might is made known in His work\nKalamazoo - Kalamazoo\nThe rain, the waves, the stormy sea\nKalamazoo - Kalamazoo.\nPraise Him, praise Him,\nall raise their voices in His praise. The rains,\nthe waves, the stormy sea\nall praise His name in Kalamazoo.",
        ],
      ),
      Hymn(
        id: 487,
        number: "487",
        title: "The Lord Is My Shepherd",
        category: "Trust & Comfort",
        refrain: "My shepherd is the Lord,\nnothing indeed shall I want.",
        stanzas: [
          "1. The Lord is my shepherd.\nThere is nothing I shall want\nFresh and green are the pastures where He gives me repose.\nNear restful waters He leads me to revive my drooping spirit.",
          "2. He guides me along the right path.\nHe is true to His name.\nIf I should walk in the valley of darkness,\nno evil would I fear, you are there with your crook and your staff.\nWith these You give me comfort.",
          "3. You have prepared a banquet for me in the sight of my foes.\nMy head You have anointed with oil My cup is overflowing.",
          "4. Surely goodness and kindness shall follow me all the days of my life.\nIn the Lord's own house shall I dwell, forever and ever.",
          "5. To the Father and Son give glory\nGive glory to the Spirit, to God who is, who was\nand who will be forever and ever.\nHis goodness shall follow me always, to the end of my days.",
        ],
      ),
      Hymn(
        id: 488,
        number: "488",
        title: "The Lord's My Shepherd",
        category: "Trust & Comfort",
        stanzas: [
          "1. The Lord's my Shepherd I'll not want\nHe makes me down to lie In pastures green, He leadeth me, the quiet waters by.",
          "2. My soul He doth restore again, and me to walk doth make,\nwithin the paths of righteousness e'en for His own name's sake.",
          "3. My table Thou hast furnished in presence of my foes.\nMy head Thou dost with oil anoint and my cup overflows.",
          "4. Goodness and mercy all my life shall surely follow me.\nAnd in God's house for evermore, my dwelling place shall be.",
        ],
      ),
      Hymn(
        id: 489,
        number: "489",
        title: "The Love I Have",
        category: "Love & Charity",
        stanzas: [
          "1. The love I have for you, O Lord, is only a shadow of Your love for me;\nonly a shadow of Your love for me, Your deep abiding love.",
          "2. My own belief in you, O Lord, is only a shadow of Your faith in me,\nYour deep and lasting faith.",
          "3. My life is in your hands, my Lord.\nMy life is in your hands, my Lord.\nMy love for you will grow, my God.\nYour light in me will shine.",
          "4. The dream I have today, my Lord,\nis only a shadow of Your dreams for me,\nonly a shadow of all that will be if I but follow you.",
          "5. The joy I feel today, my Lord,\nis only a shadow of Your joys for me,\nonly a shadow of Your joys for me when we meet face to face.",
        ],
      ),
      Hymn(
        id: 490,
        number: "490",
        title: "The Mass Is Ended",
        category: "Recessional & Dismissal",
        stanzas: [
          "1. The Mass is ended, all go in peace\nWe must diminish, and Christ increase.\nWe take Him with us wher'er we go, that through our actions\nHis life may show.",
          "2. We witness His love to ev'ryone.\nBy our communion with Christ the Son,\nwe take the Mass to where men may be,\nso Christ may shine forth for all to see.",
          "3. Thanks to the Father Who shows the way.\nHis life is with us throughout each day. Let all our longing and loving be\nto praise and honor the Trinity.",
        ],
      ),
      Hymn(
        id: 491,
        number: "491",
        title: "There Is A Green Hill",
        category: "Passion & Cross",
        stanzas: [
          "1. There is a green hill far away\noutside a city wall,\nwhere the dear Lord was crucified,\nwho died to save us all.",
          "2. We may not know, we cannot tell,\nwhat pains He had to bear\nBut we believe it was for us\nHe hung and suffered there.",
          "3. He died that we might be forgiven\nHe died to make us good,\nthat we might go at last to heaven\nsaved by His precious blood.",
          "4. There was no other good enough\nto pay the price of sin.\nHe only could unlock the gate\nof heaven, and let us in.",
          "5. O dearly, dearly has He loved,\nand we must love Him too,\nand trust in His redeeming blood,\nand try His work to do.",
        ],
      ),
      Hymn(
        id: 492,
        number: "492",
        title: "There Is A Stranger",
        category: "Penitential & Lent",
        stanzas: [
          "1. There is a stranger at the door.\nLet Him in (let the Saviour in).\nHe's been often here before.\nLet Him in (let the Saviour in).\nLet Him in ere He is gone.\nLet the Saviour in. (2)\nLet Him in, the Holy One,\nJesus Christ, the Father's Son.\nLet Him in (let the Saviour in) (2).",
          "2. Open now to Him your hearts.\nLet Him in (let the Saviour in) (2)\nIf You won't He will depart.\nLet Him in (let the Saviour in).\nLet Him in He is our friend.\nHe Your soul will sure defend.\nHe will keep You to the end.\nLet Him in (let the Saviour in).",
          "3. You now in-loving voice.\nLet Him in (let the Saviour in).\nNow, oh now make Him your choice.\nLet Him in. (Let Him in, let the Saviour in).\nJoy to you He will restore. (2)\nAnd His name You will adore.\nLet Him in (let the Saviour in). (2)",
        ],
      ),
      Hymn(
        id: 493,
        number: "493",
        title: "There Shall Be Showers Of Blessing",
        category: "Praise & Worship",
        refrain: "Showers of blessing;\nShowers of blessing we need\nMercy drops round us are falling,\nBut for the showers we plead.",
        stanzas: [
          "1. There shall be showers of blessing,\nThis is the promise of love;\nThere shall be seasons refreshing,\nSent from the Saviour above.",
          "2. There shall be showers of blessing\nPrecious reviving again,\nOver the hills and the valleys\nSound of abundance of rain.",
          "3. There shall be showers of blessing;\nSending upon us O Lord;\nGrant to us now a refreshing\nCome, now and honour Thy word.",
          "4. There shall be showers of blessing\nOh that today they might fall,\nNow as to God we're confessing\nNow as on Jesus we call.",
        ],
      ),
      Hymn(
        id: 494,
        number: "494",
        title: "There's A Call",
        category: "Mission & Evangelization",
        refrain: "Send the Light - the blessed gospel light.\nLet it shine - from shore to shore\nSend the light - the blessed Gospel light\nLet it shine forever more -",
        stanzas: [
          "1. There's a call comes ringing o'er the restless waves\nSend the light! Send the light!\nThere are souls to rescue, There are souls to save.\nSend the light - Send the light.",
          "2. We have heard the Macedonian call today.\nSend the light - Send the light.\nAnd our grateful offerings at the cross we lay.\nSend the light - Send the light.",
          "3. May the grace of Jesus unto all abound.\nSend the light - Send the light.\nAnd a Christ-like spirit everywhere be found,\nSend the light - Send the light.",
          "4. Let us not grow weary in the work of love.\nSend the light - Send the light.\nWhile we gather jewels for our crown above\nSend the light - Send the light.",
        ],
      ),
      Hymn(
        id: 495,
        number: "495",
        title: "There Was A Man In Jericho",
        category: "Children & Youth",
        stanzas: [
          "1. There was a man in Jericho called Zaccheus. (2)\nNow the Hebrews they were tall.\nBut Zaccheus he was small.\nBut the Lord loved Zaccheus better than them all.",
          "2. The Lord went walking one day through Jericho town.\nAnd the people began to gather from miles around.\nNow Zaccheus he couldn't see.\nSo he climbed a sycamore tree.\nAnd the Lord looked up and said 'Zaccheus come down.'",
          "3. The Lord said Zaccheus I'm dining with you today.\nZaccheus I come to your house, come lead the way.\nThen Zaccheus he gave a cheer.\nAnd the people began to sneer:\n'Does the Lord seek lodging here?'",
          "4. Now Zaccheus was small in stature.\nBut he could show that a man who is stout of heart can grow and grow.\n'If I have cheated young and old,\nI restore the goods fourfold.\nAnd salvation came that day to his whole household.'",
        ],
      ),
      Hymn(
        id: 496,
        number: "496",
        title: "The Royal Banners",
        category: "Passion & Cross",
        stanzas: [
          "1. The royal banners forward go.\nThe cross shines forth in mystic glow,\nwhere He in flesh, our flesh who made,\nOur sentence bore, our ransom paid.",
          "2. Deep for us the spear was dyed.\nLife's torrent rushing from His side,\nto wash us in that precious flood,\nwhere mingled water flowed and blood.",
          "3. Fulfilled is all that David told\nin true prophetic song of old,\namidst the nations, God, saith He,\nhath reigned and triumphed from the tree.",
          "4. O tree of beauty, tree of light!\nO tree with royal purple light\nelect on whose triumphal breast,\nThose holy limbs should find their rest.",
          "5. On whose dear arms, so widely flung,\nthe weight of this world's ransom hung,\nthe price of human kind\nAnd spoil the spoiler of his prey.",
          "6. O cross, our own reliance, hail!\nSo may Thy power with us avail,\nto give new virtue to the saint\nand pardon to the penitent.",
          "7. To Thee, eternal Three in One,\nlet homage meet by all be done,\nwhom by the cross Thou dost restore.\nPreserve and govern evermore.",
        ],
      ),
      Hymn(
        id: 497,
        number: "497",
        title: "The Solid Rock",
        category: "Faith & Trust",
        refrain: "On Christ the Solid Rock I stand\nAll other ground is sinking sand\nAll other ground is sinking sand.",
        stanzas: [
          "1. My hope is built on nothing less\nThan Jesus' blood and righteousness\nI dare not trust the sweetest frame\nBut wholly lean on Jesus' name.",
          "2. When darkness seems to hide His face\nI rest on His unchanging grace\nIn ev'ry high and stormy gale\nMy anchor holds within the veil.",
          "3. His oath, His covenant, His blood\nSupport me in the whelming flood;\nWhen all around my soul gives way,\nHe then is all my hope and stay.",
          "4. When He shall come with trumpet sound,\nOh, may I then in Him be found;\nDressed in His righteousness alone,\nFaultless to stand before the throne.",
        ],
      ),
      Hymn(
        id: 498,
        number: "498",
        title: "The Spirit Is Moving",
        category: "Holy Spirit & Pentecost",
        refrain: "The Spirit is moving, is moving all over this land.",
        stanzas: [
          "1. People are gathering The Church is born.\nThe Spirit is blowing on a world reborn.",
          "2. Doors are opening as the Spirit comes.\nHis fire is burning in His people now.",
          "3. Filled with His Spirit, we are sent to serve.\nWe are called out as brothers. We are called to work.",
          "4. The world, born once, is born again.\nWe recreate it in love and joy.",
          "5. Old men are dreaming dreams\nand young men see the light.",
          "6. Old walls are falling down.\nAnd people are speaking with each other.",
          "7. The Spirit fills us with His power\nto be His witnesses, to all we meet.",
          "8. The Spirit urges us to travel light;\nto be people of courage Who spread His fire.",
          "9. God has poured out His Spirit on all,\non all creation.",
        ],
      ),
      Hymn(
        id: 499,
        number: "499",
        title: "The Spirit Of God",
        category: "Holy Spirit & Pentecost",
        refrain: "The Spirit of God rests upon me.\nThe Spirit of God consecrates me.\nThe Spirit of God bids me go forth to proclaim His peace, His joy.",
        stanzas: [
          "1. The Spirit of God sends me forth,\ncalled to witness the Kingdom of Christ among all the nations.\nCalled to proclaim the Good News of Christ to the poor.\nMy Spirit rejoices in God, my Saviour,\nMy Spirit rejoices in God, my Saviour.",
          "2. The Spirit of God sends me forth\nCalled to witness the Kingdom of Christ among all the nations\nCalled to console the hearts overcome with great sorrow.\nMy Spirit rejoices in God, my Saviour.",
          "3. The Spirit of God sends me forth.\nCalled to witness the Kingdom of Christ among all the nations.\nCalled to comfort the poor Who mourn and who weep.\nMy Spirit rejoices in God, my Saviour.",
          "4. The Spirit of God sends me forth.\nCalled to witness the Kingdom of Christ among all the nations.\nCalled to announce the grace of salvation to men.\nMy Spirit rejoices in God my Saviour.",
          "5. The Spirit of God sends me forth.\nCalled to witness the Kingdom of Christ among all the nations.\nCalled to reveal His glory among all the people.\nMy Spirit rejoices in God my Saviour.",
        ],
      ),
      Hymn(
        id: 500,
        number: "500",
        title: "The Strife Is O'er",
        category: "Easter & Resurrection",
        refrain: "Alleluia! Alleluia!! Alleluia!!!",
        stanzas: [
          "1. The strife is o'er the battle done\nNow is the victor's triumph won\nNow let the song of praise be sung Alleluia!",
          "2. Death; mightiest pow'rs have done their worst\nAnd Jesus hath His foes dispersed\nLet shout of praise and joy outburst; Alleluia!",
          "3. On the third morn He rose again\nGlorious in majesty to reign\nO let us swell the joyful strain;\nAlleluia!",
          "4. Lord by the stripes which wounded Thee\nFrom death's dread sting Thy servants free\nThat we may live and sing to Thee\nAlleluia!",
        ],
      ),
      Hymn(
        id: 501,
        number: "501",
        title: "The Summons",
        category: "Discipleship & Following Christ",
        stanzas: [
          "1. Will you come and follow me if I but call your name?\nWill you go where you don't know and never be the same?\nWill you let my love be shown, will you let my name be known?\nWill you let my life be grown in you and you in me?",
          "2. Will you leave yourself behind, if I but call your name?\nWill you care for cruel and kind, and never be the same?\nWill you risk the hostile stare, should life attract or scare?\nWill you let me answer prayer in you and you in me?",
          "3. Will you let the blinded see if I but call your name?\nWill you set the prisoners free and never be the same?\nWill you kiss the leper clean, and do such as this unseen\nAnd admit to what I mean in you and you in me?",
          "4. Will you love the 'You' you hide if I but call your name?\nWill you quell the fear inside and never be the same?\nWill you use the faith you've found, to reshape the world around\nThrough my sight and touch and sound in you and you in me?",
          "5. Lord your summons echoes true, when you but call my name\nLet me turn and follow you and never be the same\nIn your company I'll go where your love and footsteps show\nThus I'll move and live and grow in you and you in me.",
        ],
      ),
      Hymn(
        id: 502,
        number: "502",
        title: "The Ten Commandments",
        category: "Word of God & Guidance",
        stanzas: [
          "1. I am the Lord and thou shall serve no other God but Me.\nReligion true thou shall observe, faith, hope and charity.\nAll these that Thou command.\nO Lord we cheerfully obey.\nAnd look to heaven for our reward through all eternity.",
          "2. Thou shall not take God's name in vain, nor swear unlawfully\nThings holy Thou shall not profane nor curse irreverently.",
          "3. Remember that thou sanctify the holy Sabbath day.\nWork not without necessity\nHear Holy Mass and pray.",
          "4. Thy parents honor, serve and love and cheerfully obey.\nAnd servants must obedient prove, when without sin they may.",
          "5. Thou shalt not kill nor vengeance take,\nnor hate thy enemy.\nForgive and love for Jesus' sake all that have injured Thee.",
          "6. Do not commit adultery in thoughts, words and deeds.\nBeware of evil company and read not dangerous books.",
          "7. Thou shalt not keep nor steal nor waste nor cheat in any way.\nDestruction done thou must repair as well as calumny.",
          "8. Thou shan't covet thy neighbour's wife,\nnor look with lustful eyes.\nThou shan't covet Thy neighbour's goods nor eye them enviously.",
        ],
      ),
      Hymn(
        id: 503,
        number: "503",
        title: "The Tree Of Life",
        category: "Praise & Worship",
        stanzas: [
          "1. The tree of life grows in paradise\nand its roots reach out ev'rywhere to the north, to the east and west.\nAnd all its branches praise the living God.",
          "2. The fire of life burns in Paradise\nand its flames reach out ev'rywhere to the north, to the south, to the east, and west.\nAnd all its flames praise the living God.",
          "3. The book of life is read in Paradise\nand its name called out ev'rywhere to the north, to the south, to the east and west.\nAnd all His friends shall praise the living God.",
          "4. The Lord of life lives in Paradise\nand His arms reach out ev'rywhere to the north, to the south, to east and west.\nAnd all His friends shall praise the living God.",
        ],
