      Hymn(
        id: 504,
        number: "504",
        title: "The Virgin Mary Had A Baby Boy",
        category: "Advent & Christmas",
        refrain: "He came from the glory,\nHe came from the glorious kingdom (2x).\nOh yes believers (2x).\nHe came from the glory,\nHe came from the glorious kingdom.",
        stanzas: [
          "1. The Virgin Mary had a baby boy,\nThe Virgin Mary had a baby boy,\nThe Virgin Mary had a baby boy,\nAnd they said that His name was Jesus.",
          "2. The angels sang when the baby was born.\nThe angels sang when the baby was born.\nThe angels sang when the baby was born.\nAnd proclaimed Him the Saviour Jesus.",
          "3. The wise men saw where the baby was born.\nThe wise men saw where the baby was born.\nThe wise men saw where the baby was born.\nAnd they saw that His name was Jesus.",
        ],
      ),
      Hymn(
        id: 505,
        number: "505",
        title: "They Say I Am Wise",
        category: "Passion & Cross",
        stanzas: [
          "1. They say I am wise and they say I am king.\nI'm a carpenter's son and I don't own a thing.\nThey say I am rich and they say I am poor.\nAnd when I came knocking, they bolted the door.",
          "2. They asked me for bread and they asked me for sign\nI gave them some bread and I gave them some wine.\nThe bread was my body, the wine was my blood.\nThey still turn away from me looking for food.",
          "3. They shouted with joy. They laid palms on the road.\nBut into the town on a donkey I rode.\nThey said do not go far for we can't stand the loss.\nThe very next morning they gave Me a cross.",
          "4. They brought Me down low, though they hung Me up high.\nThey brought Me to life though they left Me to die\nThey buried Me deep with a stone at My head.\nBut I am the living and they are the dead.",
        ],
      ),
      Hymn(
        id: 506,
        number: "506",
        title: "This Holy Witness",
        category: "Saints & Martyrs",
        stanzas: [
          "1. This holy witness, humble in the Lord's sight,\nRightly we honor, at this celebration.\nOn this his/her feast day, he/she went home to stay with,\nJesus in glory.",
          "2. Prayerful and prudent, continent and humble,\nGently and kindly, was this saint among us\nThroughout his/her lifetime, setting good example,\nHe/she followed Jesus.",
          "3. Those who in sickness, in their pain and sorrow,\nTurned to him/her asking for his intercession,\nOften find healing, both in mind and body,\nThrough the Lord's goodness.",
          "4. Therefore in chorus, we now sing his/her praises,\nHoping to join him/her, in eternal glory,\nWhere we shall worship, Father, Son and Spirit,\nIn life unending.",
        ],
      ),
      Hymn(
        id: 507,
        number: "507",
        title: "This Is My Body",
        category: "Communion & Eucharist",
        refrain: "This is my body given for your freedom.\nThis is my blood which was shed for all mankind\nTake all and eat till the day of My return.",
        stanzas: [
          "1. Peace to Sion, Yahweh's people.\nPut your sorrows in My hands.\nAs I once led you to freedom, come now to My Father's house.",
          "2. On your journey to the Kingdom\nyou will find the strength you need\nat this table of remembrance\nof my rising from the dead.",
          "3. Hear My flock now, hear My calling\nFor I know you all by name.\nCome with Me the Blessed Shepherd\nto the new Jerusalem.",
          "4. When the whole world shakes with terror,\nwhen the sky bursts into flames, on the clouds\nshall I appear. And you shall know My hour has come.",
        ],
