      Hymn(
        id: 508,
        number: "508",
        title: "This Is My Story",
        category: "Praise & Worship",
        refrain: "This is my story, this is my song praising my Saviour all the day long.\nThis is my story, this is my song, praising my Saviour all the day long.",
        stanzas: [
          "1. Blessed assurance, Jesus is mine!\nOh, what a foretaste of glory divine!\nHeir of salvation, purchase of God!\nBorn of the Spirit, washed in His blood.",
          "2. Perfect submission, perfect delight!\nVisions of rapture now burst on my sight;\nAngels descending from above,\nechoes of mercy, whispers of love.",
          "3. Perfect submission, all is at rest.\nI in my Saviour am happy and blest\nWatching and waiting, looking above\nFilled with His goodness, lost in His love.",
        ],
      ),
      Hymn(
        id: 509,
        number: "509",
        title: "This Is My Will",
        category: "Love & Charity",
        stanzas: [
          "1. This is My will. My one command:\nthat love should dwell among you all.\nThis is My will, that you should love,\nas I have shown that I love you.",
          "2. No greater love a man can have\nthan that he die to save his friends.\nYou are My friends if you obey\nwhat I command that you should do.",
          "3. I call you now no longer slaves.\nNo slave knows all his master does.\nI call you friends, for all I hear\nMy father says you hear from Me.",
          "4. You chose not Me, but I chose you,\nthat you should go and bear much fruit.\nI chose you out that you in Me\nshould bear much fruit that will abide.",
          "5. All that you ask, My Father dear\nfor My name's sake you shall receive.\nThis is My will, My one command\nthat love should dwell in each in all.",
        ],
      ),
      Hymn(
        id: 510,
        number: "510",
        title: "This Is The Day",
        category: "Easter & Resurrection",
        refrain: "Alleluia, Alleluia, Alleluia is our song of joy;\nSing the song we will sing forever\nAlleluia, Alleluia.",
        stanzas: [
          "1. This is the day that the Lord has made\nLet us be glad and rejoice in it.\nLet us be glad and rejoice!\nThis is the day that the Lord has made.",
          "2. This is the day when the Lord arose.\nLet us be glad and rejoice in it.\nLet us be glad and rejoice!\nThis is the day when the Lord arose.",
          "3. This is the day when we rise with Him.\nLet us be glad and rejoice in it.\nLet us be glad and rejoice!\nThis is the day when we rise with Him.",
          "4. This is the day all the world is new.\nLet us be glad and rejoice in it!\nLet us be glad and rejoice!\nThis is the day all the world is new!",
        ],
      ),
      Hymn(
