        number: "511",
        title: "This Is The Day (2)",
        category: "Easter & Resurrection",
        stanzas: [
          "1. This is the day, this is the day, that the Lord has made\nThat the Lord has made, we will rejoice,\nwe will rejoice and be glad in it, And be glad in it.\nThis is the day that the Lord has made.\nWe will rejoice and be glad in it\nThis is the day, this is the day That the Lord has made.",
          "2. This is the day, this is the day when He rose again\nWhen He rose again We will rejoice,\nwe will rejoice and be glad in it And be glad in it\nThis is the day when He rose again\nWe will rejoice and be glad in it\nThis is the day when He rose again.",
          "3. This is the day, this is the day we rise with Him\nWe rise with Him We will rejoice,\nwe will rejoice and be glad in it And be glad in it\nThis is the day when we rise with Him\nWe will rejoice and be glad in it\nThis is the day when we rise with Him.",
          "4. This is the day, this is the day when the Spirit came\nWhen the Spirit came We will rejoice,\nwe will rejoice and be glad in it And be glad in it\nThis is the day when the Spirit came\nWe will rejoice and be glad in it\nThis is the day when the Spirit came.",
        ],
      ),
      Hymn(
        id: 512,
        number: "512",
        title: "This Is The Day The Lord Has Made",
        category: "Holy Spirit & Pentecost",
        refrain: "So, come down Holy Spirit, come down Holy Spirit.\nCome down, Holy Spirit, come down\nAlleluia, Alleluia, Alleluia, Alleluia, Amen Alleluia.",
        stanzas: [
          "1. This is the day the Lord has made.\nLet us be glad and rejoice in it.\nLet us thank the Lord for this wonderful day,\nwhen we gather to share His blessings.",
          "2. Come down, Holy Spirit, and fill our hearts.\nCome and fill the hearts of all your faithful people.\nKindle in our hearts the fire of Your love.\nDescend on us, Creator Spirit.",
          "3. Send forth Your Spirit to us, O Lord.\nLet it renew all the face of the earth.\nThe love of God has been poured in our hearts,\nby His Spirit living in His people.",
        ],
      ),
      Hymn(
        id: 513,
        number: "513",
        title: "This World Is Not My Home",
        category: "Faith & Trust",
        stanzas: [
          "1. This world is not my home I am a stranger here.\nI have seen amidst this world the other world appear.\nMy life is now transformed though earthly as before.\nAnd I can't feel at home in this world anymore.\nAmazing world, the land of mystery,\nof consciousness and care, and wild tranquility.\nMy life is now transformed though earthly as before.\nAnd I can't feel at home in this world anymore.",
          "2. A land of mystery, assaults on every side,\nwhere death is waiting all, and there's no place to hide.\nA yearning floods my life, more lonely than before.\nAnd I don't feel at home in this world anymore.",
          "3. A mighty river flows of conscious care in me,\na willing child of faith I live creatively.\nMy life's precious gift that I must answer for.\nAnd I can't feel at home in this world anymore.",
        ],
      ),
      Hymn(
        id: 514,
        number: "514",
        title: "Though The Mountains May Fall",
        category: "Faith & Trust",
        refrain: "Though the mountains may fall and the hills turn to dust\nyet the love of the Lord will stand,\nas a shelter for all who will call on His name\nsing the praise and the glory of God.",
        stanzas: [
          "1. Could the Lord ever leave you?\nCould the Lord forget His love?\nThough a mother forsake her child,\nHe will not abandon you.",
          "2. Should you turn and forsake Him,\nHe will gently call your name\nShould you wander away from Him,\nHe will always take you back.",
          "3. Go to Him when you're weary,\nHe will give you angel's wings\nYou will run never tire,\nFor your God will be your strength.",
          "4. As He swore to your Fathers,\nwhen the flood destroyed the land\nHe will never forsake you,\nHe will swear to you again.",
        ],
      ),
      Hymn(
        id: 515,
        number: "515",
        title: "Throughout These Forty Days",
        category: "Penitential & Lent",
        stanzas: [
          "1. Throughout these forty days, O Lord\nwith You we fast and pray,\nthat flesh subdued and spirit freed,\nYour will we may obey.",
          "2. As You repelled temptation, Lord,\nand conquered Satan's reign,\ngive us the strength to conquer sin,\nand live by grace again.",
          "3. Throughout these days of penitence,\nthrough Lent and Passiontide,\ntake up Your cross in us again,\nin us be crucified.",
          "4. Do not abandon us, O Lord,\nBut keep us at Your side,\nthat we may rise to life anew,\nredeemed and glorified.",
          "5. Abide with us until this life\nof suffering once past,\nan Easter of unending joy\nwe may attain at last.",
        ],
      ),
      Hymn(
        id: 516,
        number: "516",
        title: "To Do Your Will",
        category: "Consecration & Dedication",
        stanzas: [
          "1. To do Your will is my desire.\nTo live in You, Lord, is my life.\nTo spend your love through all the earth.\nTo find in You the joy of life.",
          "2. All of my days I sing Your praise.\nThrough all my nights, You are my light.\nYou will shine forth through all my years\nand joyously will bring me home.",
          "3. Through all this world I see Your face\nIn all my ways You guide my heart.\nYou touch my face and comfort me.\nI love the life You gave to me.",
          "4. I search this world so restlessly,\nseeking a home from hate and strife.\nI've found in you the strength to see\nthe meaning of this troubled life.",
          "5. And so, my God, I give to you,\nthese straining words, these restless times.\nAnd take my life as a tribute\nto Your endless love for all mankind.",
        ],
      ),
      Hymn(
