          "2. O Heart for me on fire with love on man can speak.\nMy yet untold desire, God gives me for Thy sake.",
          "3. Too true I have forsaken Thy love for willful sin.\nYet now, let me be taken back by Thy grace again.",
          "4. As Thou art meek and lowly, and ever pure of heart,\nso may my heart be wholly of Thine the counterpart.",
