        category: "Peace & Unity",
        refrain: "And they'll know we are Christians by our love, by our love.\nAnd they'll know we are Christians by our love.",
        stanzas: [
          "1. We are one in the Spirit, We are one in the Lord.\nWe are one in the Spirit, We are one in the Lord.\nAnd we pray that all unity may one day be restored.",
          "2. We will walk with each other, We will walk hand in hand.\nWe will walk with each other, We will walk hand in hand.\nAnd together we'll spread the news that God is in our land.",
