      Hymn(
        id: 526,
        number: "526",
        title: "We Believe In One God",
        category: "Creed & Faith",
        stanzas: [
          "1. We believe in one God, the Father Almighty,\nMaker of heaven and earth, things visible and invisible,",
          "2. We believe in Jesus Christ, the Only Son of God,\nconceived of the Holy Spirit, born of the Virgin Mary,",
          "3. For our sake He was punished. For our sake He was crucified,\nSuffered death and was buried, rose again from the dead.",
          "4. He ascended into heaven, sits at the right hand of the Father.\nFrom thence He shall come to judge the living and the dead.",
          "5. We believe in the Holy Spirit, Who proceeds from the Father,\nand from the Son, together all are one.",
          "6. We believe in the Holy Catholic Church,\nthe Sacrament of Baptism, the forgiveness of sins and life everlasting.",
          "7. For our sake He was punished. For our sake He was crucified,\nsuffered death and was buried, rose again from the dead, Amen.",
