          "2. Make us one, Lord, as You prayed. (2)\nGrant us peace, Lord, hear our prayer.\nO Lord, kumbaya.",
          "3. Let us love, Lord, as you loved. (2)\nIn this banquet, Lord, we find strength.\nO Lord, kumbaya.",
