        number: "528",
        title: "We Gather Together",
        category: "Entrance & Gathering",
        stanzas: [
          "1. We gather together, to sing the Lord's praises,\nto worship the Father, through Jesus, His Son.\nin this celebration all sing with jubilation:\nWe are His holy people, whose freedom He won.",
          "2. We greet our Lord present, within Our assembly.\nWe hear His good news, announced clearly to all.\nOur priest is presiding in Christ we are abiding,\nas we invoke God's blessing, and answer His call.",
          "3. Since Christ is the Vine, and His people the branches,\nIn Him we give praise to the Father above.\nHe brings every nation to learn of His salvation:\nthat all may grow in knowledge, in faith, hope and love.",
