      Hymn(
        id: 529,
        number: "529",
        title: "We Give You Thanks",
        category: "Thanksgiving",
        refrain: "We give You thanks. (2)\nWe worship You. (2)\nWe sing Your praise and glory, Lord our God.",
        stanzas: [
          "1. To your people the promised bread of life.\nYou gave bread from heaven,\nThose who will eat of this bread will not hunger again.",
          "2. You have given us wine, bringing gladness,\nthe promise of Your love.\nThose who will drink from the cup will not ever know thirst.",
          "3. To the kingdom of joy, peace and happiness,\nYou lead Your holy people\nSafe in the clasp of Your hand guard us ever in love.",
          "4. To the Father, the Son, and the Spirit,\nwe sing our hymns of praise.\nAll honour, glory and might, through all ages to come.",
        ],
      ),
      Hymn(
        id: 530,
        number: "530",
        title: "We Long For You",
        category: "Communion & Eucharist",
        stanzas: [
          "1. We long for you, O Lord. (2)\nCome make us one with You in love.\nWe long for you, O Lord.",
          "2. We cannot rest, O Lord. (2)\nCome Lamb of God and give us peace\nWe cannot rest, O Lord.",
          "3. We hunger for you, O Lord. (2)\nCome feed us now with living bread.\nWe hunger for you, Lord.",
          "4. Your flesh is strength, O Lord. (2)\nCome Holy strong One, make us strong.\nYour flesh is strength, O Lord.",
          "5. You live in us, O Lord. (2)\nTo be our way and truth and life,\nYou live in us, O Lord.",
          "6. You live in others, Lord. (2)\nOur love of them is love of You.\nYou live in others, Lord.",
          "7. You live through us, O Lord. (2)\nWe are your heart and hand and voice.\nYou live through us, O Lord.",
          "8. You want one flock, O Lord. (2)\nYour word and bread can make us one,\nYou want one flock, O Lord.",
        ],
      ),
      Hymn(
        id: 531,
        number: "531",
        title: "We Long To See",
        category: "Advent & Christmas",
        refrain: "O come, O come, O come\nour Saviour dear to be.\nO come, O come, O come,\nwe have no King but Thee.",
        stanzas: [
          "1. We long to see Thee so,\nto see the newly born.\nWe long for Christmas morn.\nThe sands of time run slow,",
          "2. We long to see Thee so,\nto see the angels' glory;\nto hear their midnight story\nand with the shepherds go.",
          "3. We long to see Thee so.\nNo other joys can please us.\nWe want Thee baby Jesus.\nThe sands of time run slow.",
        ],
      ),
      Hymn(
        id: 532,
        number: "532",
        title: "We Love The Place",
        category: "Entrance & Gathering",
        stanzas: [
          "1. We love the place O God,\nWherein thy honor dwells;\nThe joy of thine abode\nAll earthly joy excels.",
          "2. It is the house of prayer,\nWherein thy servants meet;\nAnd thou O Lord art there\nThy chosen flock to greet.",
          "3. We love the sacred font\nFor there the holy dove\nTo pour is ever wont\nHis blessing from above.",
          "4. We love thy altar Lord;\nO what on earth so dear?\nFor there in faith adored,\nWe find thy presence near.",
          "5. We love the word of life,\nThe word that tells of peace\nOf comfort in that strife,\nAnd joy that never cease.",
          "6. We love to sing below\nFor mercies freely giv'n\nBut O, we long to know\nThe triumph song of heaven.",
          "7. Lord Jesus, give us grace\nOn earth to love thee more,\nIn heaven to see thy face,\nAnd with thy saints adore.",
