        number: "533",
        title: "We Offer Thee",
        category: "Offertory & Gifts",
        stanzas: [
          "1. We offer Thee the Holy Mass,\nThee our Creator to adore;\nTo thank Thee for thy precious gifts and praise\nThy name forever more.",
          "2. We pray for pardon and for grace,\nTo change the lives that we have led\nAnd beg Thee for Thy Son's dear sake to bless\nThe living and the dead. Amen.",
        ],
