      Hymn(
        id: 534,
        number: "534",
        title: "We Plough The Fields",
        category: "Thanksgiving & Harvest",
        refrain: "All good gifts around us\nare sent from heaven above.\nThen thank the Lord,\nO thank the Lord for all His love.",
        stanzas: [
          "1. We plough the fields and scatter the good seed on the land\nBut it is fed and water'd by God's Almighty Hand.\nHe sends the snow in winter, the warmth to swell the grain,\nThe breezes and the sunshine and soft refreshing rain.",
          "2. He only is the Maker of all things near and far.\nHe paints the wayside flower. He lights the evening star.\nThe winds and waves obey Him. By Him the birds are fed.\nMuch more to us, His children, He gives our daily bread.",
          "3. We thank Thee, then, O Father, for all things bright and good,\nThe seed time and the harvest, our life, our health, our food.\nAccept the gifts we offer for all Thy love imparts,\nAnd what thou most desirest, our humble thankful hearts.",
        ],
      ),
      Hymn(
