        number: "535",
        title: "We Praise Thee",
        category: "Praise & Worship",
        refrain: "Alleluia... Thine the glory.\nAlleluia, Amen.\nAlleluia, Thine the glory,\nRevive us again.",
        stanzas: [
          "1. We praise Thee, O God, for the sign of Thy love,\nFor Jesus Who died, and is now gone above.",
          "2. We praise Thee, O God, for the Spirit of Light\nWho has shown us our Saviour, and scattered our night.",
          "3. All-glory and praise to the Lamb that was slain,\nAnd hath cleansed every stain from all His children.",
          "4. Revive us again. Fill each soul with Thy love.\nMay each soul be rekindled with fire from above.",
