      Hymn(
        id: 536,
        number: "536",
        title: "Were You There?",
        category: "Lent & Passion",
        stanzas: [
          "1. Were you there when they crucified my Lord? (2)\nOh - sometimes it causes me to tremble, tremble, tremble.\nWere you there when they crucified my Lord?",
          "2. Were you there when they nailed Him to the tree? (2)\nOh sometimes it causes me to tremble, tremble, tremble.\nWere you there when they nailed Him to the tree?",
          "3. Were you there when they pierced Him in the side? (2)\nOh sometimes it causes me to tremble, tremble, tremble.\nWere you there when they pierced Him in the side?",
          "4. Were you there when the sun refused to shine? (2)\nOh sometimes it causes me to tremble, tremble, tremble.\nWere you there when the sun refused to shine?",
          "5. Were you there when they laid Him in the tomb? (2)\nOh sometimes it causes me to tremble, tremble, tremble.\nWere you there when they laid Him in the tomb?",
          "6. Were you there when He rose from out the tomb? (2)\nOh sometimes it causes me to tremble, tremble, tremble.\nWere you there when He rose from out the tomb?",
