      Hymn(
        id: 537,
        number: "537",
        title: "We See The Lord",
        category: "Praise & Worship",
        stanzas: [
          "1. We see the Lord. (2)\nAnd He is high and lifted up.\nAnd His strength fills the temple. He is high and lifted up.\nAnd His strength fills the temple.\n\nThe angels cry 'Holy'\nThe angels cry 'Holy'.\nThe angels cry 'Holy is the Lord'.",
          "2. We see the Lord. (2)\nAnd His face shines forth\nas a light in the darkness. (2)",
          "3. We hear the Lord. (2)\nAnd His word issues forth\nand resounds through the temple. (2)\n\nThe seraph cry 'Holy'\nThe seraph cry 'Holy'.\nThe seraph cry 'Holy is the Lord'.",
          "4. We bless the Lord. (2)\nAnd as incense goes forth\nso our prayers fill the temple. (2)\n\nThe elders cry Amen.\nThe elders cry Amen.\nThe elders cry Amen it is so.",
        ],
      ),
      Hymn(
        id: 538,
        number: "538",
        title: "We Shall Go Up",
        category: "Entrance & Gathering",
        refrain: "We shall go up into God's house with shout of joy\nWe shall go into the house of the Lord",
        stanzas: [
          "1. I rejoice when I heard them say\nLet us go to God's house.\nAnd now our feet are standing\nwithin your gates O Jerusalem.",
          "2. Jerusalem is built as a city, strongly compact.\nIt is there that the tribes go up,\nthe tribes of the Lord.",
          "3. For Israel's law it is there to praise the Lord's name.\nThere were set the thrones of judgement of the house of David.",
          "4. Praise the Father, the Son and Holy Spirit,\nboth now and forever.\nThe God Who is, Who was and is to come\nat the end of the ages.",
        ],
      ),
      Hymn(
        id: 539,
        number: "539",
        title: "We Stand For God",
        category: "Faith & Dedication",
        refrain: "Strengthen our faith, Redeemer!\nGuard us when danger is nigh.\nTo you we pledge our lives and service\nstrong in a trust that ne'er shall die.",
        stanzas: [
          "1. We stand for God and for His glory,\nthe Lord supreme and God of all.\nAgainst His foes we raise His standard.\nAround the cross we hear His call.",
          "2. We stand for God, let us be loyal,\nOur love proclaim with every breath,\nTo Christ the King, and Lord of all Lords,\nwe will be faithful unto death.",
        ],
      ),
      Hymn(
        id: 540,
        number: "540",
        title: "We Three Kings Of Orient",
        category: "Advent & Christmas",
        refrain: "O star of wonder, star of might,\nstar with royal beauty bright,\nwestward leading, still proceeding,\nguide us to Thy perfect light.",
        stanzas: [
          "1. We three kings of orient are,\nbearing gifts we traverse afar,\nfield and fountain, moor and mountain\nfollowing yonder star.",
          "2. Born a king on Bethlehem's plain,\ngold I bring to crown Him again,\nKing forever, ceasing never,\nover us all to reign.",
          "3. Frankincense to offer have I,\nincense owns a deity nigh.\nPraying and praising, all men raising,\nworship Him, God most high.",
          "4. Myrrh is mine its bitter perfume\nbreathe a life of gathering gloom\nsorrowing, sighing, bleeding, dying,\nsealed in the stone cold tomb.",
          "5. Glorious now, behold Him arise\nKing and God and sacrifice,\nAlleluia, Alleluia,\nearth to the heaven replies.",
        ],
      ),
      Hymn(
        id: 541,
        number: "541",
        title: "We Walk By Faith",
        category: "Faith & Trust",
        stanzas: [
          "1. We walk by faith not by sight.\nNo gracious words we hear of Him Who spoke\nas none e'er spoke,\nbut we believe Him near.",
          "2. We may not touch His hands and side,\nnor follow where He trod -\nYet in His promise we rejoice,\nand cry 'My Lord and God!'",
          "3. Help then, O Lord, our unbelief\nAnd may our faith abound -\nto call on You when you art near,\nand seek where You are found.",
          "4. That when our life and faith is done\nin realms of clear light -\nwe may behold You as you are\nin full and endless light.",
        ],
      ),
      Hymn(
        id: 542,
        number: "542",
        title: "What A Blessed Hope",
        category: "Praise & Worship",
        refrain: "He will my soul defend,\nHe my unchanging friend\nHe will keep me to the end\nAll glory be to Jesus.",
        stanzas: [
          "1. What a blessed hope is mine,\nThrough the love of Jesus,\nI am heir of love divine,\nThrough the love of Jesus.",
          "2. I lay up my strife in this world,\nFor our salvation dear Christ\nDid come down to us from the Lord.",
        ],
      ),
      Hymn(
        id: 543,
        number: "543",
        title: "What A Friend We Have",
        category: "Prayer & Petition",
        stanzas: [
          "1. What a friend we have in Jesus,\nall our sins and griefs to bear!\nWhat a privilege to carry\neverything to God in prayer!\nOh, what peace we often forfeit!\nOh, what needless pain we bear!\nAll because we do not carry\neverything to God in prayer!",
          "2. Have we trials and temptations?\nIs there trouble anywhere?\nWe should never be discouraged,\nTake it to the Lord in prayer.\nCan we find a friend so faithful,\nWho will all our sorrows share?\nJesus knows our every weakness,\nTake it to the Lord in prayer.",
          "3. Are we weak and heavy laden,\ncumbered with a load of care?\nPrecious Saviour still our refuge,\nTake it to the Lord in prayer.\nDo your friends despise, forsake you?\nTake it to the Lord in prayer.\nIn His arms He'll take and shield you,\nYou will find a solace there.",
        ],
      ),
      Hymn(
        id: 544,
        number: "544",
        title: "What Can We Bring",
        category: "Offertory & Gifts",
        stanzas: [
          "1. What can we bring to offer,\nas our gift to You, O Lord,\nO God as our gift to you?\nYou are full of kindness,\nfor Your sinful sons, O Lord,\nO God, for your sinful sons.\nFather, all that we have\nFather comes from Your hands.\nSo we offer You, Jesus, as our Holy Gift,\nO Lord, O God, as our holy gift.",
          "2. Take then all our labour,\nsuffering and pain,\nO Lord, O God, suffering and pain.\nTake them, beauty and gladness,\nheart and mind and will,\nO Lord, O God, heart and mind and will.",
          "3. Bread and wine will be given,\nhumble food and drink,\nO Lord, O God! humble food and drink\nSymbols of human labour, symbols of ourselves.\nO Lord, O God, symbols of ourselves.",
          "4. But our Jesus will change them,\nto His risen self,\nO Lord, O God, to His risen self.\nHe will share with His brothers,\nLife and Truth and Love,\nO Lord, O God, Life and Truth and Love.",
        ],
      ),
      Hymn(
        id: 545,
        number: "545",
        title: "What Child Is This",
        category: "Advent & Christmas",
        refrain: "This! This is Christ the King\nwhom shepherds guard and angels sing.\nHaste! Haste to bring Him laud,\nthe babe, the son of Mary.",
        stanzas: [
          "1. What child is this who laid to rest\nOn Mary's lap, is sleeping\nWhen angels greet with anthem sweet,\nWhile shepherds watch and keeping.",
          "2. Why lies He in such mean estate\nWhere ox and ass are feeding?\nGood Christian fear for sinners here\nThe silent word is pleading.",
          "3. So bring Him incense, gold and myrrh,\nCome rich and poor to own Him.\nThe King of Kings salvation bring,\nLet loving hearts enthrone Him.",
        ],
      ),
      Hymn(
        id: 546,
        number: "546",
        title: "What Did He Do?",
        category: "Salvation & Redemption",
        refrain: "Who saved us from eternal toss?\nWho but God's Son upon the cross?\nWhat did He do? He died for us.\nWhere is He now?\nBelieve it, He in heaven is interceding.",
        stanzas: [
          "1. O listen to a wondrous story,\nCounted once among the lost.\nYes, one came down from heaven's glory,\nSaving us at awful cost.",
          "2. No angel could his place have taken,\nHighest of the high was He,\nThe loved one on the cross forsaken\nWas one of the Godhead Three.",
          "3. Will you surrender to this Saviour?\nTo His sceptre humbly bow;\nYou too shall come to know His favour,\nHe will save you, save you now.",
        ],
      ),
      Hymn(
        id: 547,
        number: "547",
        title: "What Have We To Offer Him",
        category: "Offertory & Gifts",
        stanzas: [
          "1. What have we to offer Him\nWho is God and Lord of all?\nWe have one true sacrifice,\nJesus Christ our Lord.",
          "2. From the Father came the Son\nCrucified to save us all;\nThis our only offering,\nJesus Christ our Lord.",
          "3. All true men are joined in Him\nWho for love has saved the world;\nJoined in one as God made man,\nJesus Christ our Lord.",
          "4. Father take this offering,\nTake the bread and take the wine;\nTake the victim now prepared,\nJesus Christ our Lord.",
        ],
