      Hymn(
        id: 551,
        number: "551",
        title: "Whatsoever You Do",
        category: "Charity & Service",
        refrain: "Whatsoever you do to the least of My brothers,\nThat you do unto Me.\nLet us offer our lives,\nLet us offer to the Lord.\nWe adore Him, we thank Him,\nWe praise Him for His love.",
        stanzas: [
          "1. When I was hungry you gave me to eat.\nWhen I was thirsty you gave me to drink.\nNow enter into the home of My Father.",
          "2. When I was homeless you opened your door.\nWhen I was naked you gave me your coat -\nNow enter into the home of My Father.",
          "3. When I was weary you helped Me find rest.\nWhen I was anxious you calmed all My fears.\nNow enter into the home of My Father.",
          "4. When I was restless, you listened and cared.\nWhen I was lonely you gave me your love.\nNow enter into the home of My Father.",
          "5. When in a prison you came to My cell.\nWhen on a sick bed, you cared for My needs.\nNow enter into the home of My Father.",
          "6. In a strange country you made me at home.\nSeeking employment you found me a job.\nNow enter into the home of My Father.",
          "7. Hurt in the battle, you bound up My wounds,\nSearching for kindness you held out your hand.\nNow enter into the home of My Father.",
        ],
      ),
      Hymn(
        id: 552,
        number: "552",
        title: "When A Sinner Comes",
        category: "Repentance & Reconciliation",
        stanzas: [
          "1. When a sinner comes as a sinner may,\nthere is joy - there is joy.\nWhen he turns to God in the gospel way,\nthere is joy.\nThere is joy among the angels,\nAnd their harps with music ring, music ring,\nwhen a sinner comes repenting,\nbending low before our King.",
          "2. When a soul is born in the kingdom bright,\nthere is joy, there is joy.\nWhen it walks by faith in the gospel bright,\nthere is joy - there is joy.",
        ],
      ),
      Hymn(
        id: 553,
        number: "553",
        title: "When All Thy Mercies",
        category: "Thanksgiving",
        stanzas: [
          "1. When all thy mercies O my God\nMy rising soul surveys,\nTransported with the view I'm lost\nin wonder, love and praise.",
          "2. Unnumbered comforts to my soul,\nThy tender care bestowed,\nBefore my infant heart conceived,\nfrom whom those comforts flowed.",
          "3. When in the slippery paths of youth,\nwith heedless steps I ran,\nThine arm unseen conveyed me safe\nAnd led me up to man.",
          "4. Ten thousand thousand precious gifts\nmy daily thanks employ,\nAnd not the least a cheerful heart\nwhich tastes those gifts with joy.",
          "5. Through every period of my life,\nThy goodness I'll pursue,\nAnd after death in distant worlds,\nThe glorious theme renew.",
          "6. Through all eternity to thee\nA joyful song I'll raise,\nFor O, eternity's too short,\nTo utter all thy praise.",
        ],
      ),
      Hymn(
        id: 554,
        number: "554",
        title: "When Creation Was Begun",
        category: "Mary & Saints",
        refrain: "You are with us day by day,\nin our joys and our dismay\nmake us joyful as we say\nHoly Mary, full of grace.\nAve, Ave, Ave Maria.",
        stanzas: [
          "1. When creation was begun,\nGod had chosen you to be,\nmother of His blessed Son.\nHoly Mary, full of grace.\nAve, Ave, Ave Maria.",
          "2. When creation was restored\nYou were there beside the Lord,\nwhom you cherished and adored,\nHoly Mary, full of grace.\nAve, Ave, Ave Maria.",
          "3. Lead us to Your child above.\nHe will teach us how to love,\nhow to pity and forgive.\nHoly Mary, full of grace.\nAve, Ave, Ave Maria.",
          "4. In the vision which transcends\nall our dreams and never ends,\nGod will gather all His friends\nin the kingdom of your Son.\nAve, Ave, Ave Maria.",
          "5. Praise the Father and the Son,\nand the Spirit, Three in One,\nas it was when time began,\nnow and evermore, amen.\nAve, Ave, Ave Maria.",
        ],
      ),
      Hymn(
        id: 555,
        number: "555",
        title: "When He Comes Back",
        category: "Advent & Christmas",
        refrain: "When He comes back (2)\nour lamps will be burning\nto welcome Him,\nwhen He comes back.",
        stanzas: [
          "1. The master has promised that He will return\non a night when there's no one expecting to see Him at all.\nKeep oil in the lamps so they're ready to burn\nin the night of His secret, when those who are waiting, He'll call.",
          "2. Look not for His presence in heaven's dark space\nBy the light of our living on earth, we'll discover His face.\nFor the face of the master is always at hand,\nin the hungry, the poor, in the stranger, the face of a man.",
          "3. This stranger will search for his home in the night.\nAnd then how will he find it unless all the windows are bright?\nBut if we are waiting, why, then He'll come in\nand there will be a homecoming,\nwith dancing and singing within.",
