      ),
      Hymn(
        id: 556,
        number: "556",
        title: "When I Look At The Work",
        category: "Praise & Worship",
        refrain: "When I look at the work of Your hands,\nwonderful, wonderful is Your handiwork.",
        stanzas: [
          "1. Lord, our God, glorious is Your name,\nblazoned through all the earth.\nEven the infants Your power proclaim,\nAnd babes at new birth.",
          "2. When I look at the heavens above,\nthe moon and stars You have set.\nWhat is man that you show Him love\nand never forget?",
          "3. Your dominion You let him share\nof creatures of field and stall,\nfish of the sea and birds of the air,\nfor him You made all.",
