      ),
      Hymn(
        id: 557,
        number: "557",
        title: "When I Needed A Neighbour",
        category: "Charity & Service",
        refrain: "I'll be there, I'll be there,\nWherever you travel, I'll be there.\nAnd the creed and the colour\nand the name won't matter, I'll be there.",
        stanzas: [
