          "3. I was cold, I was naked... were you there?",
          "4. When I needed a shelter... were you there?",
          "5. When I needed a healer... were you there?",
          "6. Wherever you travel, were you there?",
        ],
      ),
      Hymn(
        id: 558,
        number: "558",
        title: "When All Thy Mercies",
        category: "Thanksgiving",
        stanzas: [
          "1. When all thy mercies O my God\nMy rising soul surveys,\nTransported with the view\nI'm lost in wonder love and praise.",
          "2. Unnumbered comforts to my soul,\nThy tender care bestowed,\nBefore my infant heart conceived,\nfrom whom those comfort flowed.",
          "3. When in the slippery paths of youth,\nwith heedless steps I ran,\nThine arm unseen conveyed me safe\nAnd led me up to man.",
