      ),
      Hymn(
        id: 559,
        number: "559",
        title: "When Israel Were In Bondage",
        category: "Praise & Worship",
        refrain: "To turn back Pharaoh's army (3)\nAlleluia.\nTo turn back, turn back, turn back,\nTo turn back, turn back, turn back,\nTo turn back Pharaoh's army. Alleluia.\nTo turn back Pharaoh's army Allelu...ia\nTo turn back Pharaoh's army, Alleluia.",
        stanzas: [
          "1. When Israel were in bondage,\nthey cried but to Moses,\nto turn back Pharaoh's army.\nAlleluia.",
          "2. When Moses struck the water,\nthe water came together,\nto turn back Pharaoh's army.\nAlleluia.",
          "3. If you want to go to heaven,\nyou better be a soldier,\nto turn back Pharaoh's army.\nAlleluia.",
        ],
      ),
      Hymn(
        id: 560,
        number: "560",
        title: "When I Survey",
        category: "Lent & Passion",
        stanzas: [
          "1. When I survey the wondrous cross,\nOn which the prince of glory died,\nMy richest gain I count but loss,\nAnd poor contempt on all my pride.",
          "2. Forbid it Lord, that I should boast,\nSave in the death of Christ my God\nAll the vain things that charms me most\nI sacrifice them to his blood.",
          "3. See! From his head, his hands, his feet,\nSorrow and love flow mingled down!\nDid e'er such love and sorrow meet?\nOr thorns compose so rich a crown?",
          "4. Were the whole realm of nature mine,\nThat were an offering far too small:\nLove so amazing, so divine,\nDemands my soul, my life, my all.",
        ],
      ),
      Hymn(
        id: 561,
        number: "561",
        title: "When I See The Blood",
        category: "Salvation & Redemption",
        refrain: "When I see the blood, When I see the blood,\nWhen I see the blood,\nI will pass, I will pass over you.",
        stanzas: [
          "1. Christ our redeemer died on the cross,\nDied for the sinner, paid all his due;\nAll who receive him need never fear\nYes he will pass, will pass over you.",
          "2. Chiefest of sinners Jesus can save,\nAs he has promised, so he will do,\nOh sinners hear him, trust in his word,\nThen he will pass, he will pass over you.",
          "3. Judgment is coming, all will be there\nWho have rejected, who have refused,\nOh, sinner, hasten, let Jesus in,\nThen God will pass, will pass over you.",
          "4. Oh what compassion, oh boundless love\nJesus has power, Jesus is true.\nAll who believe are safe from the storm\nOh, he will pass, will pass over you.",
        ],
      ),
      Hymn(
        id: 562,
        number: "562",
        title: "When Peace Like A River",
        category: "Faith & Trust",
        refrain: "It is well, it is well with my soul\nIt is well with my soul\nIt is well with my soul.",
        stanzas: [
          "1. When peace like a river attendeth my way,\nwhen sorrows like sea billows roll;\nwhatever my Lord Thou hast taught me to say:\nIt is well, it is well with my soul.",
          "2. Though Satan should buffet, though trials should come,\nlet this blest assurance control,\nThat Christ has regarded my helpless estate:\nIt is well, it is well with my soul.",
          "3. My sin - oh, the bliss of this glorious thought!\nMy sin - not in part, but the whole is nailed to the cross\nand I bear it no more.\nIt is well, it is well with my soul.",
        ],
      ),
      Hymn(
        id: 563,
        number: "563",
        title: "When Upon Life's Billows",
        category: "Thanksgiving",
        refrain: "Count your blessings, name them one by one.\nCount your blessings, see what God hath done\nCount your blessings, name them one by one.\nAnd it will surprise you what the Lord hath done.",
        stanzas: [
          "1. When upon life's billows you are tempest-tossed,\nwhen you are discouraged, thinking all is lost,\ncount your many blessings, name them one by one.\nAnd it will surprise you what the Lord hath done.",
          "2. Are you ever burdened with a load of care?\nDoes the cross seem heavy you are called to bear?\nCount your many blessings, every doubt will fly,\nAnd you will be singing as the days go by.",
          "3. When you look at others with their lands and gold,\nthink that Christ has promised you His wealth untold.\nCount your many blessings, money cannot buy,\nYour reward in heaven, nor your home on high.",
          "4. So amid the conflict, whether great or small,\ndo not be discouraged, God is overall.\nCount your many blessings, angels will attend,\nhelp and comfort give you to your journey's end.",
        ],
      ),
      Hymn(
        id: 564,
        number: "564",
        title: "When We Walk With The Lord",
        category: "Faith & Trust",
        refrain: "Trust and obey\nfor there's no other way,\nto be happy in Jesus\nbut to trust and obey,",
        stanzas: [
          "1. When we walk with the Lord,\nin the light of His word,\nwhat a glory He sheds on our way!\nWhile we do His good will,\nHe abides with us still,\nand with all who will trust and obey.",
          "2. Not a shadow can rise,\nnot a cloud in the skies,\nbut His smile quickly drives it away.\nNot a doubt nor a fear,\nnot a sigh nor a tear\ncan abide while we trust and obey.",
          "3. Not a burden we bear,\nnor a sorrow we share,\nbut our toil he doth richly repay;\nnot a grief nor a loss,\nnot a crown nor a cross,\nbut is blest if we trust and obey.",
          "4. But we never can prove\nthe delight of His love,\nuntil all on the altar we lay.\nFor the favour He shows,\nAnd the joy He bestows\nare for them who will trust and obey.",
        ],
      ),
      Hymn(
        id: 565,
        number: "565",
        title: "Where Are You Bound",
        category: "Mary & Saints",
        refrain: "Where are you bound Mary, Mary?\nWhere are you bound mother of God?",
        stanzas: [
          "1. Beauty is a dove,\nsitting on a sunlit bough.\nBeauty is a prayer without the needs of words.\nWords are more than sounds falling off an empty tongue:\nLet it be according to His word.",
          "2. Mary heard the word spoken in her inmost heart.\nMary bore the Word and beheld Him in her arms.\nSorrow she has known, seeing him upon the cross\ngreater joy to see Him rise again.",
          "3. Where are we all bound, carrying the Word of God?\nTime and place are ours to make His glory known.\nMary bore Him first, we will tell the world wide world:\nlet it be according to His word.",
        ],
      ),
      Hymn(
        id: 566,
        number: "566",
        title: "Where There Is Charity And Love",
        category: "Love & Unity",
        refrain: "Where there is charity and love, there the God of love abides.",
        stanzas: [
          "1. The love of Christ has gathered us here as one.\nRejoice in Him with joy which He imparts.\nLet us revere and love the living God.\nAnd love each other with unfailing heart.",
          "2. And so when we are gathered as here as one,\nlet quarrels die and evil rancours cease.\nBe our resolve all bitterness to shun.\nAnd in our midst be Christ His love and peace.",
          "3. O lead us Master by Your saving grace\nto where the blessed glory in your sight.\nThere let us see and love face to face.\nGather once more in everlasting light.",
        ],
      ),
      Hymn(
        id: 567,
        number: "567",
        title: "Where True Love Is Dwelling",
        category: "Love & Unity",
        stanzas: [
          "1. Where true love is dwelling God is dwelling there.\nLove's own loving Presence Love does ever share.",
          "2. Love of Christ has made us out of many one.\nIn our midst is dwelling God's eternal Son.",
          "3. Give Him joyful welcome. Love Him and revere.\nCherish one another with a love sincere.",
          "4. As in Christ we gather discord has no part;\nOurs is but one spirit, but one mind and heart.",
          "5. Bitterness now ended, let there be accord;\nalways with us dwelling be our God and Lord.",
          "6. May we share the vision with the saints on high\nof Christ's matchless glory when we come to die.",
          "7. Joy of all the blessed, be our heavenly prize.\nDwell with us forever Lord of Paradise.",
          "8. Where true love is dwelling God is dwelling there.\nLove's own loving Presence Love does ever share.",
        ],
      ),
      Hymn(
        id: 568,
        number: "568",
        title: "Where Two Or Three",
        category: "Entrance & Gathering",
        refrain: "Where two or three are gathered together for My sake\nthere I am in the midst of them.",
        stanzas: [
          "1. If you come to eat, if you come to play\nif you come to work, or if you come to pray.",
          "2. If you walk in love, as I told you to,\nwhen you can call My name,\nwill be there with you.",
          "3. If your skin is dark, if your skin is light,\nyou are in My heart, and you are in my sight.",
        ],
      ),
      Hymn(
        id: 569,
        number: "569",
        title: "While Shepherds Watched",
        category: "Advent & Christmas",
        stanzas: [
          "1. While shepherds watched their flocks by night,\nall seated on the ground,\nthe angel of the Lord came down\nand glory shone around,",
          "2. 'Fear not,' said He, 'For mighty dread\nhad seized their troubled mind.\nGlad tidings of great joy I bring\nto you and all mankind.",
          "3. To you, in David's town this day\nis born of David's line.\nThe Saviour, who is Christ the Lord,\nand this shall be the sign.",
          "4. The heavenly Babe you there shall find,\nto human view displayed,\nall meanly wrapped in swathing band,\nand in a manger laid.",
          "5. Thus spoke the seraph and forthwith\nappeared a shining throng of angels praising God,\nWho thus addressed their joyful song:",
          "6. All glory be to God on high,\nand to the Earth be peace, goodwill\nhenceforth, from heaven to men,\nbegin and never cease.",
        ],
      ),
      Hymn(
        id: 570,
        number: "570",
        title: "While We Pray",
        category: "Consecration & Dedication",
        refrain: "Why not, why not now?\nwhy not, why not now?\nwhy not come to Jesus now?",
        stanzas: [
          "1. While we pray, - while we plead,\nwhile you see our souls still here.\nWhile your Father calls you home,\nwill you not my brothers come.",
          "2. Jesus, grant me this I pray,\never in Thy heart to stay.\nLet me evermore abide\nin Your heart and wounded side.",
          "3. If the evil one prepare,\nor the world's tempting snares,\nI am safe when I abide in Your heart\nand wounded side.",
          "4. If the flesh more dangerous still\ntempt my soul to deeds of ill,\nnought I fear when I abide,\nin your heart and wounded side.",
          "5. Death will come one day to me,\nJesus cast me not from Thee,\ndying let me still abide\nin Your heart and wounded side.",
        ],
      ),
      Hymn(
        id: 571,
        number: "571",
        title: "Winds Of Change",
        category: "Praise & Worship",
        refrain: "All the past is but a stepping stone on man's trek into this present day.\nBut the future cries for something more,\ncries to all: create the new way.\nWinds of change are whirling round and round.\nAnd I choose with those upon the Way.",
        stanzas: [
          "1. Winds of change are whirling round and round\nand a new world dawns let everyman take heed.\nWinds of change are whirling round and round\nand they call for all to risk a deed.",
          "2. What shall be somehow depends on me\nWhat I am, have been and now decide to be.\nAnd all men of Way become my own.\nAnd thus we become the larger me.\nWe the Way, in time have ever been.\nWith our now, we watch towards the yet to be,\never on, to forge the ever new for all men in all history. -\nWhat shall be, somehow, depends on me.\nAnd I'm on with those upon the Way.",
        ],
      ),
      Hymn(
