        refrain: "With a joyful heart, O Lord, my God\nI give all to You.",
        stanzas: [
          "1. Behold, O Lord, this bread\nwhich we now carry to Your altar.\nThis bread will become Your body.",
          "2. Behold, O Lord, this wine\naccept and bless it for our gladness.\nThis wine will become Your blood.",
          "3. We come to You, Lord.\nWe bring the gifts that you have made,\nthe gifts we return to You.",
        ],
      ),
      Hymn(
        id: 573,
        number: "573",
        title: "With An Everlasting Love",
        category: "Praise & Worship",
        refrain: "With an everlasting love, You care for me, O Lord.\nI will sing forever of Your love.",
        stanzas: [
          "1. I give thanks to You with all my heart.\nYou have heard the words of my mouth.",
          "2. On the day I called You answered me.\nYou increased The strength of my soul.",
          "3. Though I walk in the midst of affliction,\nYou stretched out Your hand to help.",
          "4. Your love, O Lord, is eternal.\nDiscard not the work of Your hands.",
        ],
      ),
      Hymn(
        id: 574,
        number: "574",
        title: "With Joyful Lips",
        category: "Praise & Worship",
        refrain: "With joyful lips, O Lord,\nI will sing Your praises.\nYou are a feast for my soul.",
        stanzas: [
          "1. O God, you are my God, and my hope.\nMy soul thirsts after you.",
          "2. Your glory, I behold, in the temple,\nYour Majesty enthroned.",
          "3. More beautiful than life is Your glory.\nMy lips shall sing your praise.",
          "4. So all my life I bless you, O Lord.\nTo You I lift my hands.",
          "5. As one that You have called to Your feast,\nMy heart gives thanks to you.",
          "6. The shadow of your wing is my shelter.\nMy soul clings fast to you.",
          "7. My thoughts have turned to You in the night.\nAt dawn I sing Your praise.",
          "8. For you have been the light of my soul.\nIn you I put my trust.",
          "9. To Father, Son and Spirit,\ngive glory, both now and evermore.",
        ],
      ),
      Hymn(
        id: 575,
        number: "575",
        title: "With My Saviour",
        category: "Faith & Trust",
        refrain: "In the hollow of His hands,\nin the hollow of His hands,\nI am safe whatever may betide me\nin the hollow of His hands. (2)",
        stanzas: [
          "1. With my Saviour ever near to guide me,\nI am safe whatever may betide me,\nFrom the storm and tempest He will hide me\nin the hollow of His hands.",
          "2. In His arm of love He doth enfold me.\nWords of peace His voice divine hath told me.\nI am safe for God Himself do hold me\nin the hollow of His hands.",
          "3. He will guard my soul and leave me never,\nfrom His love No favour on earth shall sever.\nAnd I know He'll keep me now and ever\nin the hollow of His hands.",
        ],
      ),
      Hymn(
