        number: "576",
        title: "Worthy, Worthy Is The Lamb",
        category: "Praise & Worship",
        stanzas: [
          "1. Worthy, worthy is the Lamb (3) that was slain.\nPraise Him, alleluia. (3)\nPraise the lamb.",
          "2. We the crown of life shall wear.\nWe the palm of victory bear.\nAll our Father's blessings share in the Lamb.",
          "3. And when landed safe above,\nin the Kingdom of His love\nWe shall all the fullness prove of the Lamb.",
        ],
      ),
      Hymn(
