        number: "577",
        title: "Yahweh Is The God",
        category: "Praise & Worship",
        refrain: "Yahweh is the God of my salvation\nI trust in Him and have no fear.\nI sing of the joy which His love gives to me.\nAnd I draw deeply from the springs of His great kindness.",
        stanzas: [
          "1. Open our eyes, to the wonder of this moment,\nthe beginning of another day.",
          "2. Be with us, Lord as we break through with each other,\nto find the truth and beauty of each friend.",
          "3. When evening comes and our day of toil is over,\ngive us rest, O Lord,\nin the joy of many friends.",
        ],
      ),
      Hymn(
        id: 578,
        number: "578",
        title: "Yahweh's Love",
        category: "Praise & Worship",
        refrain: "Yahweh's love will last forever.\nHis faithfulness till the end of time.\nYahweh is a loving God,\nYahweh, the faithful one.",
        stanzas: [
          "1. Have no fear, for I am with you.\nI will be your shield.\nGo now and leave your homeland,\nFor I will give you a home.",
