      Hymn(
        id: 579,
        number: "579",
        title: "Ye Sons And Daughter Of The Lord",
        category: "Easter & Resurrection",
        refrain: "Al-le-lu-ya! Al-le-lu-ya! Al-le-lu-ya!",
        stanzas: [
          "1. Ye sons and daughters of the Lord\nThe King of glory, King adored\nThis day Himself from death restored, Alleluia!",
          "2. All in the early morning grey\nWent holy women on their way\nTo see the tomb where Jesus lay. Alleluia!",
          "3. Of spices pure of precious store,\nIn their pure hands those women bore,\nTo anoint the sacred body o'er, Alleluia!",
          "4. Then straight away one in white they see.\nWho saith, \"ye seek the Lord;\nBut He is risen, and gone to Galilee\"\nAlleluia!",
          "5. This told they Peter told they John;\nWho forthwith to the tomb are gone?\nBut Peter is by outrun,\nAlleluia!",
          "6. That self-same night, while out of fear,\nThe doors were shut, their Lord most dear\nTo His apostles did appear.\nAlleluia!",
          "7. But Thomas when of this he heard,\nWas doubtful of his brethren's word\nTherefore again there comes the Lord\nAlleluia!",
          "8. Thomas behold my side saith He\nMy hands my feet, my body see,\nAnd doubt not but believe in me. Alleluia!",
          "9. When Thomas say that wounded side\nThe truth no longer he denied\n\"Thou art my Lord and God\" he cried,\nAlleluia!",
          "10. Oh blest are who have not seen,\nTheir Lord and yet believe in Him\nEternal life awaiteth them. Alleluia!",
          "11. Now let praise the Lord most high\nAnd strive His name to magnify\nOn this great day, through earth and sky.\nAlleluia!",
          "12. Whose mercy ever runneth o'er\nWho men and angel host adore;\nTo Him be glory evermore.\nAlleluia!",
        ],
      ),
      Hymn(
        id: 580,
        number: "580",
        title: "Yes, Heaven Is The Prize",
        category: "Faith & Eternal Life",
        refrain: "'Tis heaven - 'tis heaven\nYes, heaven is the prize. (2)",
        stanzas: [
          "1. Yes, heaven is the prize,\nmy soul shall strive to gain.\nOne glimpse of Paradise\nrepays a life of pain.",
          "2. Yes, heaven is the prize.\nMy soul, O think of this.\nAll earthly goods despise\nfor such a crown of bliss.",
          "3. Yes, heaven is the prize.\nWhen sorrows press around,\nlook up beyond the skies,\nwhere hope and strength are found.",
          "4. Yes, heaven is the prize\nO, 'tis not hard to gain.\nHe surely wins who tries\nFor hope can conquer pain.",
          "5. Yes, heaven is the prize.\nThe strife will soon be past.\nFaint not, but raise your eyes.\nAnd struggle till the last.",
        ],
      ),
      Hymn(
        id: 581,
        number: "581",
        title: "Yes, I Shall Arise",
        category: "Lent & Passion",
        refrain: "Yes, I shall arise and return to my Father.",
        stanzas: [
          "1. To you, O Lord, I lift up my soul.\nIn you, O my God, I place all my trust.",
          "2. Look down on me, have mercy, O Lord.\nForgive me my sins, behold all my grief.",
          "3. My heart and soul shall yearn for your face.\nBe gracious to me and answer my plea.",
          "4. Do not withhold your goodness from me.\nO Lord, may Your love be deep in my soul.",
          "5. To you I pray: Have pity on me\nMy God I have sinned against Your great love.",
          "6. Mercy, I cry, O Lord: wash me clean\nAnd whiter than snow my spirit shall be.",
          "7. Give me again the joy of your help\nNow open my lips, your praise I will sing.",
          "8. Happy is he, forgiven by God.\nHis sins blotted out, his guilt is no more.",
          "9. You are my joy, my refuge and strength.\nLet all upright hearts give praise to the Lord.",
          "10. My soul will sing, my heart will rejoice.\nThe blessings of God will fill all my days.",
        ],
