        refrain: "Yes, we will enter your house to praise\nYour name, O Lord.\nYes, we will enter Your house with happiness. (2)\nAlleluia (3) with happiness",
        stanzas: [
          "1. Come let us go to the house of God to sing\nand praise His name, forever more.",
          "2. Come let us go and ask for mercy.\nThe Lord will forgive forever more.",
          "3. Glory and praise be to the Father,\nthe Son and Holy Ghost, forever more.",
        ],
