      Hymn(
        id: 583,
        number: "583",
        title: "You Are Blest",
        category: "Praise & Worship",
        stanzas: [
          "1. You are blest, Lord God, of our fathers!\nTo you glory and praise for evermore.",
          "2. Blest your glorious holy name\nTo you glory and praise for evermore.",
          "3. You are blest in the temple of Your glory!\nTo you glory and praise for evermore.",
          "4. You are blest who gaze into the depths!\nTo You glory and praise for evermore.",
          "5. You are blest in the firmament of heaven!\nTo you glory and praise for evermore.",
          "6. You walk on the wings of the wind!\nTo You glory and praise for evermore.",
          "7. May they bless you, the saints and the angels!\nTo you glory and praise for evermore.",
          "8. From the heavens, the earth and the sea!\nTo you glory and praise for evermore.",
          "9. You are blest, Lord God of our Fathers!\nTo You glory and praise for evermore.",
        ],
      ),
      Hymn(
        id: 584,
        number: "584",
        title: "You Are God",
        category: "Offertory & Gifts",
        refrain: "Let your love carry me on.\nI feel your love making me strong.",
        stanzas: [
          "1. You are God, mighty and true.\nAll that I see was made O Father, by You.\nNow I bring You what is Your own.\nLay it with love before your heavenly home.\n\nHere is bread and here is the wine\nI give you back all that is mine.",
          "2. O Jesus, holy and true,\nchange in Your flesh this bread, this wine to your blood.\nSend on us your Spirit of love.\nGive us the fullness of Your grace and your love.\n\nIn Your love, Lord, make me strong.\nIn Your love, Lord, make me wise.",
          "3. Come, O Lord, and take my hand.\nAnd in Your love we'll walk together as one.\nWash my sins away in Your blood.\nAnd in Your mercy drive away all my fears.\n\nLet your love carry me on\nI feel Your love making me strong.",
          "4. Take my hand, listen to me.\nHelp me to grow and be what I must be.\n\nLet your love carry me on.\nI feel your love making me strong.",
          "5. Turn me round facing your light.\nAnd in Your love, Lord, I'll love everyone.",
