      Hymn(
        id: 585,
        number: "585",
        title: "You Are The Honor",
        category: "Mary & Saints",
        refrain: "You are the honor, you are the glory of our people,\nHoly Virgin Mary,",
        stanzas: [
          "1. You are the glory of Jerusalem,\nHoly Virgin Mary!",
          "2. You are the greatest of Israel,\nHoly Virgin Mary.",
          "3. You are the highest honor of our race,\nHoly Virgin Mary.",
          "4. May you blessed by the Lord most high,\nHoly Virgin Mary Now,\nand for all ages without end,\nHoly Virgin Mary.\nGive praise to God in the Church and Christ,\nHoly Virgin Mary.",
